COURSE.add({
  id: 'm03', order: 3, icon: '🪨',
  title: { en: 'Amazon Bedrock: calling models', he: 'Amazon Bedrock: קריאה למודלים' },
  summary: { en: 'Models, model IDs and inference profiles, the Converse API, streaming, errors, and every way to pay for inference.', he: 'מודלים, model IDs ו-inference profiles, ה-Converse API, streaming, שגיאות, וכל הדרכים לשלם על inference.' },
  glossary: [
    { term: 'Model ID', aka: ['modelId', 'model IDs'], en: 'The string that names a model in an API call, for example `anthropic.claude-sonnet-4-6`.', he: 'המחרוזת שמציינת מודל בקריאת API, למשל `anthropic.claude-sonnet-4-6`.' },
    { term: 'Model card', aka: ['model cards'], en: 'The docs page of one model: its IDs, limits, Regions, supported features and tiers.', he: 'דף התיעוד של מודל אחד: המזהים שלו, המגבלות, ה-Regions, היכולות הנתמכות וה-tiers.' },
    { term: 'Model catalog', en: 'The page in the Bedrock console where you browse all models and open one in a playground.', he: 'הדף בקונסול של Bedrock שבו עוברים על כל המודלים ופותחים אחד ב-playground.' },
    { term: 'Playground', aka: ['playgrounds'], en: 'A console screen where you chat with a model by hand, with no code.', he: 'מסך בקונסול שבו מדברים עם מודל ידנית, בלי קוד.' },
    { term: 'Model lifecycle', aka: ['Legacy', 'EOL', 'end-of-life'], en: 'The stages of a model version: Active, then Legacy, then end-of-life (EOL), when it is switched off.', he: 'השלבים של גרסת מודל: Active, אחר כך Legacy, ואז end-of-life (EOL), כשמכבים אותה.' },
    { term: 'Inference profile', aka: ['inference profiles'], en: 'A named resource that defines a model plus the Regions a request may run in. You pass its ID as `modelId`.', he: 'משאב עם שם שמגדיר מודל ועוד ה-Regions שבהם בקשה יכולה לרוץ. מעבירים את המזהה שלו בתור `modelId`.' },
    { term: 'Cross-Region inference', aka: ['CRIS', 'geographic profile', 'global profile'], en: 'Letting Bedrock run your request in another Region to find capacity. Geographic profiles stay inside one geography (`us.`), global profiles can use any commercial Region (`global.`).', he: 'לתת ל-Bedrock להריץ את הבקשה שלך ב-Region אחר כדי למצוא קיבולת. Geographic profiles נשארים בתוך גאוגרפיה אחת (`us.`), global profiles יכולים להשתמש בכל Region מסחרי (`global.`).' },
    { term: 'Application inference profile', aka: ['AIP'], en: 'An inference profile that you create and tag yourself, to track cost and usage per application or team.', he: 'inference profile שאתה יוצר ומתייג בעצמך, כדי לעקוב אחרי עלות ושימוש לכל אפליקציה או צוות.' },
    { term: 'Converse API', aka: ['Converse'], en: 'The Bedrock request format that is the same for every model that supports messages.', he: 'פורמט הבקשה של Bedrock שזהה לכל מודל שתומך בהודעות.' },
    { term: 'ConverseStream', aka: ['converse_stream'], en: 'The streaming twin of Converse. The answer arrives as a series of small events.', he: 'התאום של Converse עם streaming. התשובה מגיעה כסדרה של אירועים קטנים.' },
    { term: 'InvokeModel', aka: ['invoke_model'], en: 'The lower-level call where you send the JSON body in the model provider\'s own format.', he: 'הקריאה ברמה הנמוכה יותר, שבה שולחים את גוף ה-JSON בפורמט של ספק המודל עצמו.' },
    { term: 'Messages API', en: 'Anthropic\'s own request format. On Bedrock you can use it with the Anthropic SDK.', he: 'פורמט הבקשה של Anthropic עצמה. ב-Bedrock אפשר להשתמש בו עם ה-SDK של Anthropic.' },
    { term: 'Responses API', en: 'OpenAI\'s stateful request format: the server can keep the conversation for you. Available on Bedrock.', he: 'פורמט הבקשה ה-stateful של OpenAI: השרת יכול לשמור את השיחה בשבילך. זמין ב-Bedrock.' },
    { term: 'Chat Completions', aka: ['Chat Completions API'], en: 'OpenAI\'s stateless chat format. Available on Bedrock with the OpenAI SDK.', he: 'פורמט הצ׳אט ה-stateless של OpenAI. זמין ב-Bedrock עם ה-SDK של OpenAI.' },
    { term: 'bedrock-runtime', en: 'The main, recommended inference endpoint: Converse, InvokeModel, and the OpenAI- and Anthropic-compatible paths.', he: 'ה-endpoint הראשי והמומלץ ל-inference: Converse, InvokeModel, והנתיבים התואמים ל-OpenAI ול-Anthropic.' },
    { term: 'bedrock-mantle', aka: ['mantle'], en: 'The second inference endpoint. It adds Projects, server-side tools and background runs, but has no Converse and no cross-Region inference.', he: 'ה-endpoint השני ל-inference. מוסיף Projects, כלים בצד השרת והרצות ברקע, אבל אין בו Converse ואין cross-Region inference.' },
    { term: 'Control plane', en: 'The APIs that manage resources (list models, create guardrails, start jobs). boto3 client: `bedrock`.', he: 'ה-APIs שמנהלים משאבים (להציג מודלים, ליצור guardrails, להתחיל עבודות). ה-client ב-boto3: `bedrock`.' },
    { term: 'Data plane', en: 'The APIs that do the real work, here: running inference. boto3 client: `bedrock-runtime`.', he: 'ה-APIs שעושים את העבודה האמיתית, כאן: הרצת inference. ה-client ב-boto3: `bedrock-runtime`.' },
    { term: 'Content block', aka: ['content blocks'], en: 'One piece of a message in Converse: a text, an image, a document, a tool request, and so on.', he: 'חלק אחד של הודעה ב-Converse: טקסט, תמונה, מסמך, בקשה לכלי וכדומה.' },
    { term: 'On-demand', aka: ['on-demand inference'], en: 'Pay per token, no commitment. The default way to use Bedrock.', he: 'תשלום לפי טוקן, בלי התחייבות. הדרך הרגילה להשתמש ב-Bedrock.' },
    { term: 'Service tier', aka: ['service tiers', 'Flex', 'Priority', 'Reserved'], en: 'The priority and price class of a request: Reserved, Priority, Standard or Flex.', he: 'מחלקת העדיפות והמחיר של בקשה: Reserved, Priority, Standard או Flex.' },
    { term: 'Batch inference', aka: ['batch'], en: 'Many prompts sent as a file in S3 and processed later, not in real time.', he: 'הרבה פרומפטים שנשלחים כקובץ ב-S3 ומעובדים מאוחר יותר, לא בזמן אמת.' },
    { term: 'Provisioned Throughput', aka: ['PT', 'model unit', 'model units'], en: 'Dedicated model capacity at a fixed hourly price, measured in model units.', he: 'קיבולת מודל ייעודית במחיר קבוע לשעה, שנמדדת ב-model units.' },
    { term: 'Prompt caching', en: 'Reusing an already-processed start of a prompt, to save time and input cost.', he: 'שימוש חוזר בתחילת פרומפט שכבר עובדה, כדי לחסוך זמן ועלות קלט.' },
    { term: 'Cache checkpoint', aka: ['cachePoint', 'cache checkpoints'], en: 'The marker in a request that says "cache everything before this point".', he: 'הסימן בבקשה שאומר "שמור ב-cache את כל מה שלפני הנקודה הזו".' },
    { term: 'TTL', aka: ['time to live'], en: 'Time to live: how long a cache entry stays alive without being used.', he: 'Time to live: כמה זמן רשומה ב-cache נשארת בחיים בלי שמשתמשים בה.' },
    { term: 'Intelligent prompt routing', aka: ['prompt router', 'prompt routers'], en: 'A router that sends each prompt to the cheaper or the stronger of two models from the same family.', he: 'נתב ששולח כל פרומפט למודל הזול או לחזק מבין שני מודלים מאותה משפחה.' },
    { term: 'TPM', aka: ['tokens per minute', 'RPM'], en: 'Tokens per minute: the main rate limit per model. RPM is requests per minute.', he: 'Tokens per minute: מגבלת הקצב העיקרית לכל מודל. RPM הוא requests per minute.' },
    { term: 'Burndown rate', aka: ['burndown'], en: 'The multiplier applied to output tokens when they are counted against your quota (not your bill).', he: 'המכפיל שמופעל על טוקני פלט כשסופרים אותם מול ה-quota שלך (לא מול החשבונית).' },
    { term: 'Exponential backoff', aka: ['backoff', 'jitter'], en: 'Retrying after a wait that doubles each time, plus a small random part (jitter).', he: 'ניסיון חוזר אחרי המתנה שמכפילה את עצמה בכל פעם, ועוד חלק אקראי קטן (jitter).' },
    { term: 'ValidationException', en: 'The error (HTTP 400) for a request that is built wrong. Retrying the same request will fail again.', he: 'השגיאה (HTTP 400) על בקשה שבנויה לא נכון. ניסיון חוזר עם אותה בקשה ייכשל שוב.' },
    { term: 'Distillation', aka: ['model distillation'], en: 'Using a big "teacher" model\'s answers to train a smaller, cheaper "student" model.', he: 'שימוש בתשובות של מודל "מורה" גדול כדי לאמן מודל "תלמיד" קטן וזול יותר.' },
    { term: 'Reinforcement fine-tuning', aka: ['RFT'], en: 'Fine-tuning where a reward function scores the model\'s answers, instead of fixed labeled examples.', he: 'Fine-tuning שבו פונקציית תגמול נותנת ציון לתשובות המודל, במקום דוגמאות מתויגות קבועות.' },
    { term: 'Custom Model Import', en: 'Bringing your own model weights into Bedrock and serving them there.', he: 'הבאת משקלי מודל משלך לתוך Bedrock והגשתם משם.' },
    { term: 'EULA', en: 'End User License Agreement of a third-party model. You accept it by invoking the model.', he: 'End User License Agreement של מודל צד שלישי. מקבלים אותו בעצם הפעלת המודל.' },
    { term: 'Adaptive thinking', aka: ['thinking'], en: 'The model decides how much to reason before it answers. Thinking tokens are billed as output tokens.', he: 'המודל מחליט כמה לחשוב לפני שהוא עונה. טוקני חשיבה מחויבים כטוקני פלט.' }
  ],
  lessons: [
    {
      id: 'm03l1', minutes: 14,
      title: { en: 'What Bedrock is, and how to pick a model', he: 'מה זה Bedrock, ואיך בוחרים מודל' },
      blocks: [
        { t: 'p', en: '[[Amazon Bedrock]] is one AWS service that gives you API access to [[Foundation model]]s from many companies, plus tools around them (knowledge bases, guardrails, evaluations and more). It is [[Serverless]]: there is no server to start, and with the default [[On-demand]] mode you pay per token.', he: '[[Amazon Bedrock]] הוא שירות אחד של AWS שנותן לך גישת API ל-[[Foundation model]]s של הרבה חברות, ועוד כלים מסביבם (knowledge bases, guardrails, evaluations ועוד). הוא [[Serverless]]: אין שרת להפעיל, ובמצב הרגיל [[On-demand]] משלמים לפי טוקן.' },
        { t: 'p', en: 'Why do companies go through Bedrock and not directly to each model vendor? One bill, one permission system ([[IAM]]), one security review, the data stays inside AWS, and changing a model is changing one string. The Bedrock FAQ states it plainly: your content is not used to improve the base models and is not shared with the model providers.', he: 'למה חברות עוברות דרך Bedrock ולא ישירות לכל ספק מודלים? חשבונית אחת, מערכת הרשאות אחת ([[IAM]]), סקירת אבטחה אחת, המידע נשאר בתוך AWS, והחלפת מודל היא החלפת מחרוזת אחת. ה-FAQ של Bedrock אומר את זה בפשטות: התוכן שלך לא משמש לשיפור מודלי הבסיס ולא משותף עם ספקי המודלים.' },
        { t: 'note', kind: 'info', en: 'A detail that a pro knows: "not shared with providers" does not always mean "nothing is kept". For some of the newest models AWS runs automated abuse detection. For Claude Fable 5.x, all traffic is kept up to 30 days for that purpose, inside AWS, and your account must opt in by setting a data retention mode called `aws_review` (there was no console screen for it at launch, only an API). Without it, calls to those models on the main endpoint fail with a `ValidationException`. Read the data section of the model card before you promise anything to a customer.', he: 'פרט שמקצוען מכיר: "לא משותף עם ספקים" לא תמיד אומר "שום דבר לא נשמר". לחלק מהמודלים החדשים ביותר AWS מריצה זיהוי שימוש לרעה אוטומטי. ב-Claude Fable 5.x כל התעבורה נשמרת עד 30 יום למטרה הזו, בתוך AWS, והחשבון שלך חייב להסכים על ידי קביעת מצב data retention בשם `aws_review` (בזמן ההשקה לא היה לזה מסך בקונסול, רק API). בלי זה, קריאות למודלים האלה ב-endpoint הראשי נכשלות עם `ValidationException`. קרא את חלק המידע ב-model card לפני שאתה מבטיח משהו ללקוח.' },
        { t: 'h', en: 'Who is on the shelf (November 2026)', he: 'מי על המדף (נובמבר 2026)' },
        { t: 'table', head: { en: ['Provider', 'Models you will hear about'], he: ['ספק', 'מודלים שתשמע עליהם'] }, rows: {
          en: [['Amazon', 'Nova 2 Lite, Nova Pro, Nova Lite, Nova Micro (text). Nova 2 Sonic and Nova 2.5 Sonic (speech). Titan and Nova embedding models.'], ['Anthropic', 'Claude 5.x: Fable 5.2, Mythos 5.2, Opus 5.5, Sonnet 5.5, Haiku 5.5. Older Claude 4.x models are still listed.'], ['OpenAI', 'GPT-6 and GPT-5.x families, and the open-weight gpt-oss models.'], ['Meta', 'Llama 4 and Llama 3.x.'], ['Mistral AI', 'Mistral Large 3, Pixtral Large, and small models.'], ['Cohere', 'Command R and R+, Embed (embeddings), Rerank.'], ['Google', 'Only the open-weight Gemma models. Gemini is not on Bedrock.'], ['Others', 'DeepSeek, xAI (Grok), Qwen, NVIDIA, Moonshot AI (Kimi), MiniMax, Z.AI, AI21 Labs, Writer. For images and video: Stability AI, Luma AI, TwelveLabs.']],
          he: [['Amazon', 'Nova 2 Lite, Nova Pro, Nova Lite, Nova Micro (טקסט). Nova 2 Sonic ו-Nova 2.5 Sonic (דיבור). מודלי embedding של Titan ו-Nova.'], ['Anthropic', 'Claude 5.x: Fable 5.2, Mythos 5.2, Opus 5.5, Sonnet 5.5, Haiku 5.5. מודלי Claude 4.x ישנים יותר עדיין ברשימה.'], ['OpenAI', 'משפחות GPT-6 ו-GPT-5.x, ומודלי ה-open-weight בשם gpt-oss.'], ['Meta', 'Llama 4 ו-Llama 3.x.'], ['Mistral AI', 'Mistral Large 3, Pixtral Large, ומודלים קטנים.'], ['Cohere', 'Command R ו-R+, Embed (embeddings), Rerank.'], ['Google', 'רק מודלי ה-open-weight בשם Gemma. Gemini לא נמצא ב-Bedrock.'], ['אחרים', 'DeepSeek, xAI (Grok), Qwen, NVIDIA, Moonshot AI (Kimi), MiniMax, Z.AI, AI21 Labs, Writer. לתמונות ווידאו: Stability AI, Luma AI, TwelveLabs.']] } },
        { t: 'p', en: 'Inside the Anthropic family the names tell you the class. **Haiku** is the fastest and cheapest. **Sonnet** is the middle: coding and agents at scale. **Opus** is the most capable general line, for long-running agents and coding. **Fable** is the frontier model for technical work and long autonomous tasks. **Mythos** is a gated model for cybersecurity and life-sciences research, available only through Anthropic\'s verification programs.', he: 'בתוך המשפחה של Anthropic השמות מספרים לך את המחלקה. **Haiku** הוא המהיר והזול ביותר. **Sonnet** הוא האמצע: קוד וסוכנים בקנה מידה גדול. **Opus** הוא הקו הכללי החזק ביותר, לסוכנים שרצים זמן רב ולקוד. **Fable** הוא מודל החזית לעבודה טכנית ולמשימות אוטונומיות ארוכות. **Mythos** הוא מודל בגישה מוגבלת למחקר סייבר ומדעי החיים, שזמין רק דרך תוכניות האימות של Anthropic.' },
        { t: 'note', kind: 'warn', en: 'This list gets old fast. Model names from tutorials written a year ago (Claude 3.5 Sonnet, Titan Text, Nova Premier) are no longer in it. Every model version has a [[Model lifecycle]]: **Active**, then **Legacy**, then **EOL** (switched off). Two habits follow. Keep the model ID in configuration, never spread through the code. And keep a small test set, so that moving to a new model is a one-day job and not a crisis.', he: 'הרשימה הזו מתיישנת מהר. שמות מודלים ממדריכים שנכתבו לפני שנה (Claude 3.5 Sonnet, Titan Text, Nova Premier) כבר לא נמצאים בה. לכל גרסת מודל יש [[Model lifecycle]]: **Active**, אחר כך **Legacy**, ואז **EOL** (כיבוי). מזה נובעים שני הרגלים. שומרים את ה-model ID בקונפיגורציה, אף פעם לא מפוזר בקוד. ושומרים סט בדיקות קטן, כך שמעבר למודל חדש הוא עבודה של יום ולא משבר.' },
        { t: 'h', en: 'The model card: read it before you code', he: 'ה-model card: קוראים לפני שכותבים קוד' },
        { t: 'p', en: 'Every model has a [[Model card]] in the docs. It is the source of truth for IDs, limits and supported features. Here is what the card of Claude Fable 5.2 says, as an example of how much one page can change your design:', he: 'לכל מודל יש [[Model card]] בתיעוד. זה מקור האמת למזהים, מגבלות ויכולות נתמכות. הנה מה שכתוב ב-card של Claude Fable 5.2, כדוגמה לכמה דף אחד יכול לשנות את התכנון שלך:' },
        { t: 'table', head: { en: ['On the card', 'Value', 'What it means for your code'], he: ['ב-card', 'ערך', 'מה זה אומר לקוד שלך'] }, rows: {
          en: [['Context window / max output', '1M tokens / 128K tokens', 'Huge inputs fit. That does not make them cheap.'], ['Sampling', 'temperature must be 1.0 or unset, top_p 0.99 or unset, never both', 'Code that always sends `temperature: 0` must change for this model.'], ['Reasoning', '[[Adaptive thinking]] is always on', 'Thinking tokens are billed as output tokens. Watch `outputTokens`.'], ['Endpoint and APIs', '`bedrock-runtime` only: Messages, Converse, Invoke', 'The OpenAI-style APIs do not work with it.'], ['In-Region', 'Not supported', 'You must call it through an inference profile ID.'], ['Service tiers', 'Standard only', 'No Flex discount for this model.'], ['Not supported', 'CountTokens, intelligent prompt routing', 'Do not design around these for this model.']],
          he: [['Context window / פלט מקסימלי', '1M טוקנים / 128K טוקנים', 'קלטים ענקיים נכנסים. זה לא הופך אותם לזולים.'], ['Sampling', 'temperature חייב להיות 1.0 או לא מוגדר, top_p 0.99 או לא מוגדר, אף פעם לא שניהם', 'קוד שתמיד שולח `temperature: 0` חייב להשתנות למודל הזה.'], ['Reasoning', '[[Adaptive thinking]] תמיד דולק', 'טוקני חשיבה מחויבים כטוקני פלט. עקוב אחרי `outputTokens`.'], ['Endpoint ו-APIs', 'רק `bedrock-runtime`: Messages, Converse, Invoke', 'ה-APIs בסגנון OpenAI לא עובדים איתו.'], ['In-Region', 'לא נתמך', 'חייבים לקרוא לו דרך inference profile ID.'], ['Service tiers', 'רק Standard', 'אין הנחת Flex למודל הזה.'], ['לא נתמך', 'CountTokens, intelligent prompt routing', 'לא מתכננים סביב אלה למודל הזה.']] } },
        { t: 'quiz', q: { en: 'Your invoice extractor sends `temperature: 0` on every call, as you learned in module 1. You switch it to Claude Fable 5.2 and requests stop working. What is the right fix?', he: 'מחלץ החשבוניות שלך שולח `temperature: 0` בכל קריאה, כמו שלמדת במודול 1. אתה מעביר אותו ל-Claude Fable 5.2 והבקשות מפסיקות לעבוד. מה התיקון הנכון?' },
          options: { en: ['Send `topP: 0` together with the temperature', 'Read the model card: this model accepts temperature only as 1.0 or unset, so leave the parameter out', 'Raise maxTokens', 'Ask AWS for a quota increase'], he: ['לשלוח `topP: 0` יחד עם ה-temperature', 'לקרוא את ה-model card: המודל הזה מקבל temperature רק כ-1.0 או לא מוגדר, אז משמיטים את הפרמטר', 'להעלות את maxTokens', 'לבקש מ-AWS העלאת quota'] },
          answer: 1, explain: { en: 'Many current models restrict the sampling parameters. The rule of thumb from module 1 (low temperature for extraction) is still right for models that allow it. But the model card always wins over a rule of thumb. For consistent output on such models you rely on clear instructions and structured output instead.', he: 'הרבה מודלים עדכניים מגבילים את פרמטרי ה-sampling. כלל האצבע ממודול 1 (temperature נמוכה לחילוץ מידע) עדיין נכון למודלים שמרשים את זה. אבל ה-model card תמיד מנצח כלל אצבע. לפלט עקבי במודלים כאלה מסתמכים על הוראות ברורות ועל structured output.' } },
        { t: 'h', en: 'How model access works now', he: 'איך גישה למודלים עובדת היום' },
        { t: 'p', en: 'Old tutorials start with "go to the Model access page and request access". In commercial Regions that step is gone. Access to models is on by default: you pick a model in the [[Model catalog]] and open it in a [[Playground]], or you simply call the API. The old Model access page now matters only in AWS GovCloud. What is left are a few things that happen on the **first** call:', he: 'מדריכים ישנים מתחילים ב"לך לדף Model access ובקש גישה". ב-Regions מסחריים השלב הזה נעלם. הגישה למודלים דולקת כברירת מחדל: בוחרים מודל ב-[[Model catalog]] ופותחים אותו ב-[[Playground]], או פשוט קוראים ל-API. הדף הישן Model access חשוב היום רק ב-AWS GovCloud. מה שנשאר הם כמה דברים שקורים בקריאה ה**ראשונה**:' },
        { t: 'list', en: ['For models from many third-party providers (for example Anthropic and the closed OpenAI models), the first call starts an **AWS Marketplace subscription** in the background. It can take up to 15 minutes, and calls may already succeed while it runs.', 'The principal that makes that first call needs three extra permissions: `aws-marketplace:Subscribe`, `aws-marketplace:Unsubscribe`, `aws-marketplace:ViewSubscriptions`. The account needs a valid payment method. If something is missing, later calls return `AccessDeniedException`.', 'For Anthropic models **older than Claude Opus 4.7** (for example Sonnet 4.6 and Haiku 4.5) there is still a one-time "First Time Use" form about your use case, once per account or once for the whole organization.', 'Some providers have no Marketplace step at all, among them Amazon, Meta, Mistral AI, DeepSeek and the open-weight gpt-oss models.', 'By invoking a third-party model you accept its [[EULA]] (license terms).'], he: ['במודלים של הרבה ספקי צד שלישי (למשל Anthropic והמודלים הסגורים של OpenAI), הקריאה הראשונה מתחילה **מנוי ב-AWS Marketplace** ברקע. זה יכול לקחת עד 15 דקות, וקריאות עשויות כבר להצליח בזמן שזה רץ.', 'ה-principal שמבצע את הקריאה הראשונה הזו צריך שלוש הרשאות נוספות: `aws-marketplace:Subscribe`, `aws-marketplace:Unsubscribe`, `aws-marketplace:ViewSubscriptions`. לחשבון צריך להיות אמצעי תשלום תקף. אם משהו חסר, קריאות מאוחרות יותר מחזירות `AccessDeniedException`.', 'במודלים של Anthropic **ישנים מ-Claude Opus 4.7** (למשל Sonnet 4.6 ו-Haiku 4.5) עדיין יש טופס חד-פעמי "First Time Use" על מקרה השימוש שלך, פעם אחת לחשבון או פעם אחת לכל הארגון.', 'לחלק מהספקים אין שלב Marketplace בכלל, ביניהם Amazon, Meta, Mistral AI, DeepSeek ומודלי ה-open-weight בשם gpt-oss.', 'בעצם הפעלת מודל צד שלישי אתה מקבל את ה-[[EULA]] שלו (תנאי הרישיון).'] },
        { t: 'quiz', q: { en: 'A brand-new account. Your application role calls a Claude model for the first time. The first few calls work. Twenty minutes later every call fails with `AccessDeniedException`. The role has `bedrock:InvokeModel` on that model. What is the most likely cause?', he: 'חשבון חדש לגמרי. ה-role של האפליקציה שלך קורא למודל Claude בפעם הראשונה. כמה קריאות ראשונות עובדות. עשרים דקות אחר כך כל קריאה נכשלת עם `AccessDeniedException`. ל-role יש `bedrock:InvokeModel` על המודל הזה. מה הסיבה הכי סבירה?' },
          options: { en: ['The model went to end-of-life during those 20 minutes', 'The role\'s temporary credentials expired', 'The background Marketplace subscription failed: the role lacks the `aws-marketplace` permissions, or the account has no valid payment method', 'The tokens-per-minute quota was exceeded'], he: ['המודל הגיע ל-end-of-life במהלך 20 הדקות האלה', 'ה-credentials הזמניים של ה-role פגו', 'המנוי ב-Marketplace שרץ ברקע נכשל: ל-role חסרות הרשאות `aws-marketplace`, או שלחשבון אין אמצעי תשלום תקף', 'עברו את ה-quota של טוקנים לדקה'] },
          answer: 2, explain: { en: 'This "works, then stops" pattern is the signature of the first-use subscription: calls may succeed during setup, and fail afterwards if the prerequisites were missing. A quota problem would be a 429 `ThrottlingException`, not a 403. The usual fix: let an identity with the Marketplace permissions make the first call in the account once. After fixing permissions, allow a couple of minutes.', he: 'הדפוס "עובד ואז מפסיק" הוא החתימה של המנוי בשימוש ראשון: קריאות עשויות להצליח בזמן ההקמה, ולהיכשל אחר כך אם התנאים המוקדמים היו חסרים. בעיית quota הייתה 429 `ThrottlingException`, לא 403. התיקון הרגיל: לתת לזהות עם הרשאות Marketplace לבצע פעם אחת את הקריאה הראשונה בחשבון. אחרי תיקון הרשאות, מחכים כמה דקות.' } },
        { t: 'note', kind: 'tip', en: 'Access being open by default has a second side: any role with `bedrock:InvokeModel` on `*` can start using an expensive model. To block a model, use an IAM or [[SCP]] Deny on `bedrock:InvokeModel` for that model ARN. The docs point out that denying `aws-marketplace:Subscribe` alone does not stop the first call.', he: 'לגישה שפתוחה כברירת מחדל יש צד שני: כל role עם `bedrock:InvokeModel` על `*` יכול להתחיל להשתמש במודל יקר. כדי לחסום מודל, משתמשים ב-Deny של IAM או [[SCP]] על `bedrock:InvokeModel` ל-ARN של המודל. התיעוד מציין שלאסור רק את `aws-marketplace:Subscribe` לא עוצר את הקריאה הראשונה.' },
        { t: 'h', en: 'Model ID or inference profile ID?', he: 'Model ID או inference profile ID?' },
        { t: 'p', en: 'In every call you pass a `modelId`. There are two kinds of string you can put there, and mixing them up is the most common first error in Bedrock.', he: 'בכל קריאה מעבירים `modelId`. יש שני סוגי מחרוזות שאפשר לשים שם, והבלבול ביניהם הוא השגיאה הראשונה הכי נפוצה ב-Bedrock.' },
        { t: 'table', head: { en: ['', 'Base model ID', 'Inference profile ID'], he: ['', 'Base model ID', 'Inference profile ID'] }, rows: {
          en: [['Example', '`amazon.nova-2-lite-v1:0`\n`anthropic.claude-sonnet-5-5`', '`us.anthropic.claude-sonnet-5-5`\n`global.anthropic.claude-opus-5`'], ['Where the request runs', 'Only in the Region you call ("In-Region")', 'In one of several Regions that the profile lists. Bedrock picks one with free capacity.'], ['Looks like', '`provider.model-name`', 'A prefix (`us.`, `global.` and others) + the model ID']],
          he: [['דוגמה', '`amazon.nova-2-lite-v1:0`\n`anthropic.claude-sonnet-5-5`', '`us.anthropic.claude-sonnet-5-5`\n`global.anthropic.claude-opus-5`'], ['איפה הבקשה רצה', 'רק ב-Region שקראת אליו ("In-Region")', 'באחד מכמה Regions שה-profile מפרט. Bedrock בוחר אחד עם קיבולת פנויה.'], ['איך נראה', '`provider.model-name`', 'קידומת (`us.`, `global.` ואחרות) + ה-model ID']] } },
        { t: 'p', en: 'An [[Inference profile]] is a small resource that says "this model, in these Regions". The feature is called [[Cross-Region inference]]. Here is the part that surprises people: **many new models have no In-Region option at all**. Claude Fable 5.2, for example, can only be called through a profile such as `us.anthropic.claude-fable-5-2` or `global.anthropic.claude-fable-5-2`. If you pass its bare model ID, the call fails. Lesson 4 comes back to profiles, because they also affect price, data location and IAM.', he: '[[Inference profile]] הוא משאב קטן שאומר "המודל הזה, ב-Regions האלה". ליכולת קוראים [[Cross-Region inference]]. והנה החלק שמפתיע אנשים: **להרבה מודלים חדשים אין אפשרות In-Region בכלל**. ל-Claude Fable 5.2, למשל, אפשר לקרוא רק דרך profile כמו `us.anthropic.claude-fable-5-2` או `global.anthropic.claude-fable-5-2`. אם מעבירים את ה-model ID החשוף שלו, הקריאה נכשלת. שיעור 4 חוזר ל-profiles, כי הם משפיעים גם על מחיר, מיקום המידע ו-IAM.' },
        { t: 'note', kind: 'jargon', en: 'You will see two styles of ID. Older models have long dated IDs with a version suffix, like `anthropic.claude-sonnet-4-5-20250929-v1:0`. Newer Claude and GPT models have short IDs, like `anthropic.claude-opus-5` or `openai.gpt-6.1-sol`. Never type an ID from memory. Copy it from the model card or from `aws bedrock list-foundation-models` and `aws bedrock list-inference-profiles`.', he: 'תראה שני סגנונות של מזהים. למודלים ישנים יותר יש מזהים ארוכים עם תאריך וסיומת גרסה, כמו `anthropic.claude-sonnet-4-5-20250929-v1:0`. למודלי Claude ו-GPT חדשים יש מזהים קצרים, כמו `anthropic.claude-opus-5` או `openai.gpt-6.1-sol`. אף פעם לא מקלידים מזהה מהזיכרון. מעתיקים אותו מה-model card או מ-`aws bedrock list-foundation-models` ו-`aws bedrock list-inference-profiles`.' },
        { t: 'fill', prompt: { en: 'Call Claude Sonnet 5.5 through the cross-Region profile that keeps requests inside the United States.', he: 'קרא ל-Claude Sonnet 5.5 דרך ה-cross-Region profile שמשאיר את הבקשות בתוך ארצות הברית.' },
          lang: 'python', code: 'response = client.converse(\n    modelId="{{1}}.anthropic.claude-sonnet-5-5",\n    messages=messages,\n)', blanks: [ { accept: ['us'], hint: { en: 'the prefix of the US geographic profile', he: 'הקידומת של ה-profile הגאוגרפי של ארה"ב' } } ],
          explain: { en: 'A profile ID is a prefix plus the model ID. `us.` is a geographic profile: the request can run in several US Regions but does not leave the US. `global.` may run in any supported commercial Region.', he: 'profile ID הוא קידומת ועוד ה-model ID. `us.` הוא profile גאוגרפי: הבקשה יכולה לרוץ בכמה Regions בארה"ב אבל לא יוצאת מארה"ב. `global.` יכול לרוץ בכל Region מסחרי נתמך.' } },
        { t: 'quiz', q: { en: 'You copy `modelId="anthropic.claude-fable-5-2"` from a blog post and call it from us-east-1. Your permissions are fine, but the call fails. Why?', he: 'העתקת `modelId="anthropic.claude-fable-5-2"` מפוסט בבלוג וקראת לו מ-us-east-1. ההרשאות שלך בסדר, אבל הקריאה נכשלת. למה?' },
          options: { en: ['This model has no In-Region option, so it must be called through an inference profile ID such as `us.anthropic.claude-fable-5-2`', 'Fable models need the old Model access page', 'The ID must end with `-v1:0`', 'The model can be called only from the console'], he: ['למודל הזה אין אפשרות In-Region, ולכן חייבים לקרוא לו דרך inference profile ID כמו `us.anthropic.claude-fable-5-2`', 'מודלי Fable צריכים את הדף הישן Model access', 'המזהה חייב להסתיים ב-`-v1:0`', 'אפשר לקרוא למודל רק מהקונסול'] },
          answer: 0, explain: { en: 'The base ID exists (you see it in ARNs and on the model card), but for this model In-Region inference is not supported in any Region. The Model access page is not used in commercial Regions, and new Claude IDs are short, with no version suffix.', he: 'ה-base ID קיים (רואים אותו ב-ARNs וב-model card), אבל במודל הזה In-Region inference לא נתמך באף Region. הדף Model access לא בשימוש ב-Regions מסחריים, ומזהי Claude חדשים הם קצרים, בלי סיומת גרסה.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Chat / Text playground', 'Cross-Region inference', 'Batch inference', 'Provisioned Throughput', 'API keys', 'Settings'], active: 'Model catalog', crumbs: ['Amazon Bedrock', 'Model catalog'],
          heading: 'Model catalog',
          panels: [
            { title: 'Models', n: 1, table: { cols: ['Model', 'Provider', 'Model ID'], rows: [['@Claude Sonnet 5.5', 'Anthropic', 'anthropic.claude-sonnet-5-5'], ['@Claude Haiku 5.5', 'Anthropic', 'anthropic.claude-haiku-5-5'], ['@Nova 2 Lite', 'Amazon', 'amazon.nova-2-lite-v1:0'], ['@GPT-6.1 Sol', 'OpenAI', 'openai.gpt-6.1-sol'], ['@Llama 3.3 70B', 'Meta', 'meta.llama3-3-70b-instruct-v1:0']] } }
          ],
          callouts: [
            { n: 1, en: 'The catalog lists every model. Choosing one shows its details and lets you open it in the playground. Notice the left menu: "Chat / Text playground" for testing by hand, "Cross-Region inference" for the list of inference profiles.', he: 'הקטלוג מציג כל מודל. בחירה באחד מציגה את הפרטים שלו ומאפשרת לפתוח אותו ב-playground. שים לב לתפריט השמאלי: "Chat / Text playground" לבדיקה ידנית, "Cross-Region inference" לרשימת ה-inference profiles.' }
          ],
          caption: { en: 'The Model catalog page, simplified into a table. The real page shows the models as cards with filters, and the left menu has more items.', he: 'דף ה-Model catalog, בצורה מפושטת כטבלה. הדף האמיתי מציג את המודלים ככרטיסים עם מסננים, ובתפריט השמאלי יש עוד פריטים.' } },
        { t: 'h', en: 'Choosing a model: quality, speed, price', he: 'בחירת מודל: איכות, מהירות, מחיר' },
        { t: 'p', en: 'You cannot have the best of all three. Bigger models reason better, answer slower and cost more per token. The professional way to choose is not "take the strongest". It is: **find the smallest model that passes your tests**.', he: 'אי אפשר לקבל את הטוב ביותר בשלושתם. מודלים גדולים חושבים טוב יותר, עונים לאט יותר ועולים יותר לטוקן. הדרך המקצועית לבחור היא לא "לקחת את החזק ביותר". היא: **למצוא את המודל הקטן ביותר שעובר את הבדיקות שלך**.' },
        { t: 'table', head: { en: ['Class', 'Examples', 'Good for'], he: ['מחלקה', 'דוגמאות', 'טוב בשביל'] }, rows: {
          en: [['Small and fast', 'Claude Haiku 5.5, Nova Micro, Nova Lite, Nova 2 Lite', 'Classification, extraction, routing, short answers, very high volume'], ['Middle', 'Claude Sonnet 5.5', 'Most production chat, RAG answers, agents at scale'], ['Top', 'Claude Opus 5.5, Claude Fable 5.2, the largest GPT models', 'Hard reasoning, long autonomous tasks, complex coding']],
          he: [['קטן ומהיר', 'Claude Haiku 5.5, Nova Micro, Nova Lite, Nova 2 Lite', 'סיווג, חילוץ מידע, ניתוב, תשובות קצרות, נפח גבוה מאוד'], ['אמצע', 'Claude Sonnet 5.5', 'רוב הצ׳אט ב-production, תשובות RAG, סוכנים בקנה מידה גדול'], ['עליון', 'Claude Opus 5.5, Claude Fable 5.2, מודלי GPT הגדולים ביותר', 'חשיבה קשה, משימות אוטונומיות ארוכות, קוד מורכב']] } },
        { t: 'list', en: ['Write 20 to 50 real examples of your task with the answers you expect. This is your first evaluation set.', 'Run them on a small model first. Go up one class only when the results are not good enough.', 'Check the non-quality limits on the model card: context window, input types (images? documents?), features you need (tools, prompt caching, guardrails), Regions, service tiers.', 'Measure cost with the real token counts from the `usage` field, not with a guess. Remember that thinking tokens are output tokens.', 'Different steps can use different models. A cheap model can classify the request, and an expensive one can handle only the hard cases.'], he: ['כתוב 20 עד 50 דוגמאות אמיתיות של המשימה שלך עם התשובות שאתה מצפה להן. זה סט ה-evaluation הראשון שלך.', 'הרץ אותן קודם על מודל קטן. עולים מחלקה אחת רק כשהתוצאות לא מספיק טובות.', 'בדוק ב-model card את המגבלות שאינן איכות: context window, סוגי קלט (תמונות? מסמכים?), יכולות שאתה צריך (כלים, prompt caching, guardrails), Regions, service tiers.', 'מדוד עלות עם ספירות הטוקנים האמיתיות מהשדה `usage`, לא עם ניחוש. זכור שטוקני חשיבה הם טוקני פלט.', 'שלבים שונים יכולים להשתמש במודלים שונים. מודל זול יכול לסווג את הבקשה, ומודל יקר יכול לטפל רק במקרים הקשים.'] },
        { t: 'match', prompt: { en: 'Match the job to the model class you would try first.', he: 'התאם את המשימה למחלקת המודל שהיית מנסה קודם.' }, pairs: [
          { a: { en: 'Tag 2 million support tickets a day with one of 12 labels', he: 'לתייג 2 מיליון טיקטים ביום באחת מ-12 תוויות' }, b: { en: 'Small and fast', he: 'קטן ומהיר' } },
          { a: { en: 'A customer chat that answers from retrieved documents', he: 'צ׳אט לקוחות שעונה מתוך מסמכים שאוחזרו' }, b: { en: 'Middle', he: 'אמצע' } },
          { a: { en: 'An agent that refactors a large codebase for hours', he: 'סוכן שעושה refactoring לבסיס קוד גדול במשך שעות' }, b: { en: 'Top', he: 'עליון' } },
          { a: { en: 'Turn text into vectors for search', he: 'להפוך טקסט לוקטורים לחיפוש' }, b: { en: 'An embedding model, not a chat model', he: 'מודל embedding, לא מודל צ׳אט' } }
        ] },
        { t: 'quiz', q: { en: 'Which statement about Bedrock in November 2026 is correct?', he: 'איזה משפט על Bedrock בנובמבר 2026 נכון?' },
          options: { en: ['You must request access to each model on the Model access page before the first call', 'Google Gemini models are available on Bedrock', 'Every model can be called with its base model ID in every Region', 'OpenAI GPT models are available on Bedrock, next to Claude, Nova, Llama and others'], he: ['חייבים לבקש גישה לכל מודל בדף Model access לפני הקריאה הראשונה', 'מודלי Google Gemini זמינים ב-Bedrock', 'אפשר לקרוא לכל מודל עם ה-base model ID שלו בכל Region', 'מודלי GPT של OpenAI זמינים ב-Bedrock, לצד Claude, Nova, Llama ואחרים'] },
          answer: 3, explain: { en: 'Both the closed GPT models and the open-weight gpt-oss models are on Bedrock. From Google there are only the open-weight Gemma models. Access is automatic in commercial Regions, and many new models can be called only through an inference profile.', he: 'גם מודלי GPT הסגורים וגם מודלי ה-open-weight בשם gpt-oss נמצאים ב-Bedrock. מ-Google יש רק את מודלי ה-open-weight בשם Gemma. הגישה אוטומטית ב-Regions מסחריים, ולהרבה מודלים חדשים אפשר לקרוא רק דרך inference profile.' } },
        { t: 'reveal', q: { en: 'Interview question: "How do you choose a model for a new feature?"', he: 'שאלת ראיון: "איך אתה בוחר מודל ליכולת חדשה?"' },
          a: { en: 'I start from the task, not from the model. I write a small evaluation set of real inputs with expected outputs. Then I check the hard constraints on the model cards: does the model accept my input types, is the context window enough, does it support the features I need, is it available in a Region and data geography we are allowed to use. Among the models that pass, I try the smallest first and move up only if the evaluation fails, because a smaller model is cheaper and faster on every single request. I measure real cost from the usage numbers. And I keep the model ID in configuration with the evaluation set next to it, because the model will be replaced within a year.', he: 'מתחילים מהמשימה, לא מהמודל. כותבים סט evaluation קטן של קלטים אמיתיים עם פלטים צפויים. אחר כך בודקים את האילוצים הקשיחים ב-model cards: האם המודל מקבל את סוגי הקלט שלי, האם ה-context window מספיק, האם הוא תומך ביכולות שאני צריך, האם הוא זמין ב-Region ובגאוגרפיית מידע שמותר לנו להשתמש בהם. מבין המודלים שעוברים, מנסים קודם את הקטן ביותר ועולים רק אם ה-evaluation נכשל, כי מודל קטן יותר זול ומהיר יותר בכל בקשה ובקשה. מודדים עלות אמיתית ממספרי ה-usage. ושומרים את ה-model ID בקונפיגורציה עם סט ה-evaluation לידו, כי המודל יוחלף בתוך שנה.' } }
      ]
    },
    {
      id: 'm03l2', minutes: 15,
      title: { en: 'The Converse API in depth', he: 'ה-Converse API לעומק' },
      blocks: [
        { t: 'p', en: 'The [[Converse API]] is the Bedrock-native way to talk to a model. Its big idea: **one request format for every model** that supports messages. Claude, Nova, Llama and the others each have their own native JSON. With Converse you write the code once, and changing the model is changing the `modelId` string.', he: 'ה-[[Converse API]] הוא הדרך המקורית של Bedrock לדבר עם מודל. הרעיון הגדול שלו: **פורמט בקשה אחד לכל מודל** שתומך בהודעות. ל-Claude, Nova, Llama ולאחרים יש לכל אחד JSON מקורי משלו. עם Converse כותבים את הקוד פעם אחת, והחלפת מודל היא החלפת המחרוזת `modelId`.' },
        { t: 'h', en: 'First: which client?', he: 'קודם כול: איזה client?' },
        { t: 'p', en: 'Bedrock is split into several boto3 clients. The split follows a general AWS idea: the [[Control plane]] manages things, the [[Data plane]] does the work.', he: 'Bedrock מחולק לכמה clients ב-boto3. החלוקה הולכת לפי רעיון כללי של AWS: ה-[[Control plane]] מנהל דברים, ה-[[Data plane]] עושה את העבודה.' },
        { t: 'table', head: { en: ['boto3 client', 'What it is for', 'Typical calls'], he: ['client ב-boto3', 'בשביל מה', 'קריאות אופייניות'] }, rows: {
          en: [['`bedrock`', 'Control plane: manage', '`list_foundation_models`, `list_inference_profiles`, `create_guardrail`, batch and customization jobs'], ['`bedrock-runtime`', 'Data plane: inference', '`converse`, `converse_stream`, `invoke_model`, `count_tokens`'], ['`bedrock-agent`', 'Build knowledge bases, prompts, flows', '`create_knowledge_base`, `create_prompt`'], ['`bedrock-agent-runtime`', 'Use them at run time', '`retrieve`, `retrieve_and_generate`']],
          he: [['`bedrock`', 'Control plane: ניהול', '`list_foundation_models`, `list_inference_profiles`, `create_guardrail`, עבודות batch ו-customization'], ['`bedrock-runtime`', 'Data plane: inference', '`converse`, `converse_stream`, `invoke_model`, `count_tokens`'], ['`bedrock-agent`', 'בניית knowledge bases, prompts, flows', '`create_knowledge_base`, `create_prompt`'], ['`bedrock-agent-runtime`', 'שימוש בהם בזמן ריצה', '`retrieve`, `retrieve_and_generate`']] } },
        { t: 'note', kind: 'warn', en: 'The classic first error: `boto3.client("bedrock").converse(...)` fails, because the `bedrock` client has no such method. Inference lives in `bedrock-runtime`.', he: 'השגיאה הראשונה הקלאסית: `boto3.client("bedrock").converse(...)` נכשל, כי ל-client בשם `bedrock` אין מתודה כזו. inference חי ב-`bedrock-runtime`.' },
        { t: 'h', en: 'The smallest call', he: 'הקריאה הקטנה ביותר' },
        { t: 'code', lang: 'python', code: 'import boto3\n\nclient = boto3.client("bedrock-runtime", region_name="us-east-1")\n\nresponse = client.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    messages=[\n        {"role": "user", "content": [{"text": "Name three AWS Regions."}]}\n    ],\n)\nprint(response["output"]["message"]["content"][0]["text"])', caption: { en: 'Two required things: `modelId` and `messages`. Everything else is optional.', he: 'שני דברים חובה: `modelId` ו-`messages`. כל השאר אופציונלי.' } },
        { t: 'fill', prompt: { en: 'Complete the call: the right client, the right method, and a model.', he: 'השלם את הקריאה: ה-client הנכון, המתודה הנכונה, ומודל.' },
          lang: 'python', code: 'import boto3\n\nclient = boto3.client("{{1}}", region_name="us-east-1")\n\nresponse = client.{{2}}(\n    {{3}}="us.anthropic.claude-sonnet-5-5",\n    messages=[{"role": "user", "content": [{"text": "Hello"}]}],\n)', blanks: [ { accept: ['bedrock-runtime'], hint: { en: 'the data plane client', he: 'ה-client של ה-data plane' } }, { accept: ['converse'], hint: { en: 'the method name, lowercase', he: 'שם המתודה, באותיות קטנות' } }, { accept: ['modelId'], hint: { en: 'camelCase: the parameter that names the model', he: 'camelCase: הפרמטר שמציין את המודל' } } ],
          explain: { en: 'Notice the two naming styles. boto3 method names are snake_case (`converse_stream`), while the parameters keep the camelCase of the API (`modelId`, `inferenceConfig`, `maxTokens`). You will type both styles in the same line all the time.', he: 'שים לב לשני סגנונות השמות. שמות המתודות ב-boto3 הם snake_case (`converse_stream`), והפרמטרים שומרים על ה-camelCase של ה-API (`modelId`, `inferenceConfig`, `maxTokens`). תקליד את שני הסגנונות באותה שורה כל הזמן.' } },
        { t: 'h', en: 'The request, field by field', he: 'הבקשה, שדה אחרי שדה' },
        { t: 'table', head: { en: ['Field', 'What it holds'], he: ['שדה', 'מה הוא מחזיק'] }, rows: {
          en: [['`modelId`', 'A model ID, an inference profile ID or ARN, or the ARN of other things that can answer (a provisioned or custom model, a stored prompt, a prompt router).'], ['`messages`', 'The conversation: a list of `{role, content}`. `role` is `"user"` or `"assistant"`. `content` is a **list** of [[Content block]]s.'], ['`system`', 'The [[System prompt]]: a **list** of blocks, for example `[{"text": "..."}]`. It is not a message and has no role.'], ['`inferenceConfig`', '`maxTokens`, `temperature`, `topP`, `stopSequences`.'], ['`additionalModelRequestFields`', 'Parameters that only some models have, for example `{"top_k": 200}` or thinking settings.'], ['`toolConfig`, `guardrailConfig`', 'Tools and guardrails. Later modules.'], ['`requestMetadata`', 'Up to 16 key-value labels of your own (user, feature, team). They appear in invocation logs, so you can filter by them.'], ['`serviceTier`, `performanceConfig`', 'How the request is served. Lesson 4.']],
          he: [['`modelId`', 'model ID, inference profile ID או ARN, או ARN של דברים אחרים שיכולים לענות (מודל provisioned או מותאם, prompt שמור, prompt router).'], ['`messages`', 'השיחה: רשימה של `{role, content}`. `role` הוא `"user"` או `"assistant"`. `content` הוא **רשימה** של [[Content block]]s.'], ['`system`', 'ה-[[System prompt]]: **רשימה** של בלוקים, למשל `[{"text": "..."}]`. זו לא הודעה ואין לה role.'], ['`inferenceConfig`', '`maxTokens`, `temperature`, `topP`, `stopSequences`.'], ['`additionalModelRequestFields`', 'פרמטרים שיש רק לחלק מהמודלים, למשל `{"top_k": 200}` או הגדרות חשיבה.'], ['`toolConfig`, `guardrailConfig`', 'כלים ו-guardrails. במודולים הבאים.'], ['`requestMetadata`', 'עד 16 תוויות key-value משלך (משתמש, יכולת, צוות). הן מופיעות ב-invocation logs, כך שאפשר לסנן לפיהן.'], ['`serviceTier`, `performanceConfig`', 'איך הבקשה מוגשת. שיעור 4.']] } },
        { t: 'p', en: 'Why is `content` a list and not a string? Because one message can mix several things: a text, an image, a document, later a tool request or a tool result. Each one is a [[Content block]]. A plain text message is simply a list with one `{"text": ...}` block.', he: 'למה `content` הוא רשימה ולא מחרוזת? כי הודעה אחת יכולה לערבב כמה דברים: טקסט, תמונה, מסמך, ובהמשך בקשה לכלי או תוצאה של כלי. כל אחד הוא [[Content block]]. הודעת טקסט רגילה היא פשוט רשימה עם בלוק `{"text": ...}` אחד.' },
        { t: 'fill', prompt: { en: 'Build a full request: a system prompt, one user message, and a limit of 300 output tokens.', he: 'בנה בקשה מלאה: system prompt, הודעת משתמש אחת, וגבול של 300 טוקני פלט.' },
          lang: 'python', code: 'response = client.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    {{1}}=[{"text": "You answer in one short sentence."}],\n    messages=[\n        {"role": "{{2}}", "content": [{"{{3}}": "Name three AWS Regions."}]}\n    ],\n    inferenceConfig={"{{4}}": 300},\n)', blanks: [ { accept: ['system'], hint: { en: 'the top-level field for the system prompt', he: 'השדה העליון של ה-system prompt' } }, { accept: ['user'], hint: { en: 'who is speaking in the first message', he: 'מי מדבר בהודעה הראשונה' } }, { accept: ['text'], hint: { en: 'the key of a text content block', he: 'המפתח של content block מסוג טקסט' } }, { accept: ['maxTokens'], hint: { en: 'camelCase: the output limit', he: 'camelCase: גבול הפלט' } } ],
          explain: { en: '`system` sits next to `messages`, not inside it. Both `system` and `content` are lists of blocks. And always set `maxTokens`: it limits your bill, your latency and, as you will see in lesson 4, the quota each request reserves.', he: '`system` יושב ליד `messages`, לא בתוכו. גם `system` וגם `content` הם רשימות של בלוקים. ותמיד מגדירים `maxTokens`: הוא מגביל את החשבון, את ה-latency, וכמו שתראה בשיעור 4, את ה-quota שכל בקשה שומרת לעצמה.' } },
        { t: 'quiz', q: { en: 'A developer writes `client.converse(modelId=..., system="You are a helpful assistant", messages=[...])` and gets an error before the model even runs. What is wrong?', he: 'מפתח כותב `client.converse(modelId=..., system="You are a helpful assistant", messages=[...])` ומקבל שגיאה עוד לפני שהמודל רץ. מה לא בסדר?' },
          options: { en: ['The system prompt is too short', 'Converse does not support system prompts', '`system` must be a list of blocks, like `[{"text": "..."}]`, not a string', 'The system prompt must be the first item in `messages`'], he: ['ה-system prompt קצר מדי', 'Converse לא תומך ב-system prompts', '`system` חייב להיות רשימה של בלוקים, כמו `[{"text": "..."}]`, לא מחרוזת', 'ה-system prompt חייב להיות הפריט הראשון ב-`messages`'] },
          answer: 2, explain: { en: 'A request with the wrong shape is rejected as a validation error. Nothing is wrong with the model or with your permissions. In Converse the roles inside `messages` are only `user` and `assistant`. The system prompt has its own top-level field, and it is a list.', he: 'בקשה עם צורה שגויה נדחית כשגיאת validation. אין שום בעיה במודל או בהרשאות שלך. ב-Converse ה-roles בתוך `messages` הם רק `user` ו-`assistant`. ל-system prompt יש שדה עליון משלו, והוא רשימה.' } },
        { t: 'h', en: 'The response', he: 'התשובה' },
        { t: 'code', lang: 'json', code: '{\n  "output": {\n    "message": {\n      "role": "assistant",\n      "content": [\n        { "text": "us-east-1, eu-central-1 and ap-southeast-1." }\n      ]\n    }\n  },\n  "stopReason": "end_turn",\n  "usage": {\n    "inputTokens": 24,\n    "outputTokens": 18,\n    "totalTokens": 42\n  },\n  "metrics": { "latencyMs": 612 }\n}', caption: { en: 'The main fields of a Converse response (the values are an illustration).', he: 'השדות העיקריים של תשובת Converse (הערכים הם המחשה).' } },
        { t: 'table', head: { en: ['Field', 'Meaning', 'What a pro does with it'], he: ['שדה', 'משמעות', 'מה מקצוען עושה איתו'] }, rows: {
          en: [['`output.message`', 'The answer, in the same shape as the messages you send', 'Appends it to the history as it is'], ['`stopReason`', 'Why the model stopped', 'Checks it on **every** call before using the text'], ['`usage`', 'Tokens that you pay for', 'Logs it on every call, with the user or feature it belongs to'], ['`metrics.latencyMs`', 'How long the call took', 'Sends it to monitoring']],
          he: [['`output.message`', 'התשובה, באותה צורה כמו ההודעות ששולחים', 'מוסיף אותה להיסטוריה כמו שהיא'], ['`stopReason`', 'למה המודל עצר', 'בודק אותו ב**כל** קריאה לפני שמשתמשים בטקסט'], ['`usage`', 'הטוקנים שמשלמים עליהם', 'רושם אותו בכל קריאה, עם המשתמש או היכולת שהוא שייך להם'], ['`metrics.latencyMs`', 'כמה זמן הקריאה לקחה', 'שולח את זה לניטור']] } },
        { t: 'p', en: 'You met three [[Stop reason]]s in module 1. Converse has more. These are the ones your code should handle:', he: 'פגשת שלושה [[Stop reason]]s במודול 1. ב-Converse יש יותר. אלה אלה שהקוד שלך צריך לטפל בהם:' },
        { t: 'table', head: { en: ['`stopReason`', 'What happened', 'What your code should do'], he: ['`stopReason`', 'מה קרה', 'מה הקוד שלך צריך לעשות'] }, rows: {
          en: [['`end_turn`', 'The model finished', 'Use the answer'], ['`max_tokens`', 'The answer was cut at your `maxTokens`', 'Do not show it as complete. Raise the limit or ask for less.'], ['`stop_sequence`', 'The model wrote one of your `stopSequences`', 'Use the answer. This is what you asked for.'], ['`tool_use`', 'The model wants a tool', 'Run the tool and call again (the tools module)'], ['`guardrail_intervened`', 'A guardrail blocked or changed something', 'Show the blocked message. Do not retry blindly.'], ['`content_filtered`', 'The content was filtered', 'Treat it as a refusal, and log it'], ['`model_context_window_exceeded`', 'Input plus output did not fit in the context window', 'Send less: trim or summarize the history']],
          he: [['`end_turn`', 'המודל סיים', 'להשתמש בתשובה'], ['`max_tokens`', 'התשובה נחתכה ב-`maxTokens` שלך', 'לא להציג אותה כשלמה. להעלות את הגבול או לבקש פחות.'], ['`stop_sequence`', 'המודל כתב אחד מה-`stopSequences` שלך', 'להשתמש בתשובה. זה מה שביקשת.'], ['`tool_use`', 'המודל רוצה כלי', 'להריץ את הכלי ולקרוא שוב (מודול הכלים)'], ['`guardrail_intervened`', 'guardrail חסם או שינה משהו', 'להציג את הודעת החסימה. לא לנסות שוב בעיוורון.'], ['`content_filtered`', 'התוכן סונן', 'להתייחס לזה כסירוב, ולרשום ללוג'], ['`model_context_window_exceeded`', 'קלט ועוד פלט לא נכנסו ל-context window', 'לשלוח פחות: לקצץ או לסכם את ההיסטוריה']] } },
        { t: 'quiz', q: { en: 'Read this part of a response: `"stopReason": "max_tokens"`, `"usage": {"inputTokens": 5200, "outputTokens": 300}`. The request had `maxTokens: 300`. Your app shows the text to the user as the final summary. What is the problem?', he: 'קרא את החלק הזה של תשובה: `"stopReason": "max_tokens"`, `"usage": {"inputTokens": 5200, "outputTokens": 300}`. בבקשה היה `maxTokens: 300`. האפליקציה שלך מציגה את הטקסט למשתמש כסיכום הסופי. מה הבעיה?' },
          options: { en: ['The summary was cut in the middle: the model used all 300 output tokens and was stopped', 'The input was too long and was ignored', 'The model refused to answer', 'Nothing. `max_tokens` is the normal stop reason.'], he: ['הסיכום נחתך באמצע: המודל ניצל את כל 300 טוקני הפלט ונעצר', 'הקלט היה ארוך מדי והתעלמו ממנו', 'המודל סירב לענות', 'כלום. `max_tokens` הוא ה-stop reason הרגיל.'] },
          answer: 0, explain: { en: 'The normal ending is `end_turn`. `max_tokens`, together with `outputTokens` equal to the limit, means the text is incomplete. A cut summary can be missing its most important sentence, and a cut JSON cannot be parsed at all. Check `stopReason` in code. Do not trust your eyes.', he: 'הסיום הרגיל הוא `end_turn`. `max_tokens`, יחד עם `outputTokens` ששווה לגבול, אומר שהטקסט לא שלם. בסיכום חתוך יכול להיות חסר המשפט הכי חשוב, ו-JSON חתוך אי אפשר לפרסר בכלל. בודקים את `stopReason` בקוד. לא סומכים על העיניים.' } },
        { t: 'fill', prompt: { en: 'Read the answer text, the stop reason and the number of output tokens from the response.', he: 'קרא מהתשובה את טקסט התשובה, את ה-stop reason ואת מספר טוקני הפלט.' },
          lang: 'python', code: 'text = response["{{1}}"]["message"]["content"][0]["text"]\nreason = response["{{2}}"]\nout_tokens = response["usage"]["{{3}}"]\n\nif reason == "max_tokens":\n    print("Warning: the answer was cut")', blanks: [ { accept: ['output'], hint: { en: 'the top-level field that holds the message', he: 'השדה העליון שמחזיק את ההודעה' } }, { accept: ['stopReason'], hint: { en: 'camelCase', he: 'camelCase' } }, { accept: ['outputTokens'], hint: { en: 'camelCase, inside usage', he: 'camelCase, בתוך usage' } } ],
          explain: { en: 'This path, `response["output"]["message"]["content"][0]["text"]`, is the one you will type a thousand times. One caution: `content` is a list, and with some models and features the first block is not text (for example a reasoning block or a tool request). Robust code loops over the blocks and collects the ones that have a `text` key.', he: 'את הנתיב הזה, `response["output"]["message"]["content"][0]["text"]`, תקליד אלף פעמים. אזהרה אחת: `content` הוא רשימה, ובחלק מהמודלים והיכולות הבלוק הראשון הוא לא טקסט (למשל בלוק reasoning או בקשה לכלי). קוד עמיד עובר על הבלוקים ואוסף את אלה שיש להם מפתח `text`.' } },
        { t: 'h', en: 'A conversation: you carry the memory', he: 'שיחה: אתה נושא את הזיכרון' },
        { t: 'p', en: 'The model is [[Stateless]]. Converse does not remember the last call. A chat works because **your code** keeps the list of messages and sends all of it again on every turn.', he: 'המודל [[Stateless]]. Converse לא זוכר את הקריאה הקודמת. צ׳אט עובד כי **הקוד שלך** שומר את רשימת ההודעות ושולח את כולה מחדש בכל תור.' },
        { t: 'code', lang: 'python', code: 'messages = [{"role": "user", "content": [{"text": "Name three AWS Regions."}]}]\n\nresp = client.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    system=[{"text": "You answer in one short sentence."}],\n    messages=messages,\n    inferenceConfig={"maxTokens": 300},\n)\n\n# Next turn: append the assistant message, then the new user message\nmessages.append(resp["output"]["message"])\nmessages.append({"role": "user", "content": [{"text": "Which one is the oldest?"}]})\n\nresp = client.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    system=[{"text": "You answer in one short sentence."}],\n    messages=messages,\n    inferenceConfig={"maxTokens": 300},\n)', caption: { en: 'The second call sends three messages: user, assistant, user. Without the first two, "which one" means nothing to the model. The system prompt is also sent again.', he: 'הקריאה השנייה שולחת שלוש הודעות: user, assistant, user. בלי שתי הראשונות, "which one" לא אומר כלום למודל. גם ה-system prompt נשלח שוב.' } },
        { t: 'order', prompt: { en: 'Put the steps of one chat turn in order.', he: 'סדר את השלבים של תור אחד בצ׳אט.' }, items: { en: ['Append the new user message to the `messages` list', 'Call `converse` with the system prompt and the whole list', 'Check `stopReason` and log `usage`', 'Append `response["output"]["message"]` to the list', 'Show the text to the user and wait for the next message'], he: ['להוסיף את הודעת המשתמש החדשה לרשימת `messages`', 'לקרוא ל-`converse` עם ה-system prompt וכל הרשימה', 'לבדוק את `stopReason` ולרשום את `usage`', 'להוסיף את `response["output"]["message"]` לרשימה', 'להציג את הטקסט למשתמש ולחכות להודעה הבאה'] },
          explain: { en: 'The list grows by two messages each turn. That is the whole "memory" of a simple chatbot. Where you keep the list between requests (in the browser, in a database, in a memory service) is a design decision that the memory module covers.', he: 'הרשימה גדלה בשתי הודעות בכל תור. זה כל ה"זיכרון" של צ׳אטבוט פשוט. איפה שומרים את הרשימה בין בקשות (בדפדפן, במסד נתונים, בשירות זיכרון) היא החלטת תכנון שמודול הזיכרון מכסה.' } },
        { t: 'fill', prompt: { en: 'The user asks a follow-up question. Add the last answer and the new question to the history, then call again.', he: 'המשתמש שואל שאלת המשך. הוסף את התשובה האחרונה ואת השאלה החדשה להיסטוריה, ואז קרא שוב.' },
          lang: 'python', code: 'messages.{{1}}(resp["output"]["{{2}}"])\nmessages.append({"role": "user", "content": [{"text": "And the newest?"}]})\n\nresp = client.converse(modelId=MODEL_ID, messages={{3}})', blanks: [ { accept: ['append'], hint: { en: 'add to the end of a Python list', he: 'להוסיף לסוף רשימה ב-Python' } }, { accept: ['message'], hint: { en: 'the assistant message inside output', he: 'הודעת ה-assistant בתוך output' } }, { accept: ['messages'], hint: { en: 'send the whole history, not only the new question', he: 'לשלוח את כל ההיסטוריה, לא רק את השאלה החדשה' } } ],
          explain: { en: '`resp["output"]["message"]` already has the right shape (`role: "assistant"` plus content blocks), so you append it without changes. This also keeps special blocks, such as tool requests, exactly as the model wrote them.', he: 'ל-`resp["output"]["message"]` כבר יש את הצורה הנכונה (`role: "assistant"` ועוד content blocks), ולכן מוסיפים אותו בלי שינויים. זה גם שומר בלוקים מיוחדים, כמו בקשות לכלים, בדיוק כמו שהמודל כתב אותם.' } },
        { t: 'quiz', q: { en: 'A user chats with your bot for an hour. Each turn costs a little more than the one before, though the questions stay short. What does the `usage` field show, and what do you do?', he: 'משתמש מדבר עם הבוט שלך שעה. כל תור עולה קצת יותר מהקודם, למרות שהשאלות נשארות קצרות. מה מראה השדה `usage`, ומה עושים?' },
          options: { en: ['`outputTokens` grows every turn. Lower the temperature.', '`inputTokens` grows every turn, because the whole history is sent again. Trim or summarize old turns, and cache the stable start of the prompt.', '`latencyMs` grows. Change the Region.', 'Nothing changes in `usage`. AWS charges more for long sessions.'], he: ['`outputTokens` גדל בכל תור. מורידים את ה-temperature.', '`inputTokens` גדל בכל תור, כי כל ההיסטוריה נשלחת שוב. מקצצים או מסכמים תורות ישנים, ושומרים ב-cache את ההתחלה היציבה של הפרומפט.', '`latencyMs` גדל. מחליפים Region.', 'שום דבר לא משתנה ב-`usage`. AWS גובה יותר על סשנים ארוכים.'] },
          answer: 1, explain: { en: 'Resent history is input tokens, and you pay for it on every turn. The `usage` numbers show it directly, which is why you log them. The tools: keep only the last N turns, summarize older ones, move facts to long-term memory, and use prompt caching (lesson 4) for the part that repeats.', he: 'היסטוריה שנשלחת שוב היא טוקני קלט, ומשלמים עליה בכל תור. מספרי ה-`usage` מראים את זה ישירות, ולכן רושמים אותם ללוג. הכלים: לשמור רק את N התורות האחרונים, לסכם ישנים, להעביר עובדות לזיכרון ארוך-טווח, ולהשתמש ב-prompt caching (שיעור 4) לחלק שחוזר על עצמו.' } },
        { t: 'reveal', q: { en: 'Interview question: "Why would you use the Converse API and not each model\'s native format?"', he: 'שאלת ראיון: "למה להשתמש ב-Converse API ולא בפורמט המקורי של כל מודל?"' },
          a: { en: 'Because the request and the response have the same shape for every model. My code for messages, system prompts, tools, stop reasons and usage is written once, and I can test another model by changing one string. That matters, because models are replaced often and I want to compare them on my own evaluation set. Converse is also the call shape that works together with other Bedrock features, such as guardrails and stored prompts. Model-specific options are still reachable through `additionalModelRequestFields`. I would drop to InvokeModel or to a provider-compatible API only when I need something Converse does not expose, or when I move existing code that already uses another SDK.', he: 'כי לבקשה ולתשובה יש אותה צורה בכל מודל. הקוד שלי להודעות, system prompts, כלים, stop reasons ו-usage נכתב פעם אחת, ואפשר לבדוק מודל אחר על ידי החלפת מחרוזת אחת. זה חשוב, כי מודלים מוחלפים לעיתים קרובות ואני רוצה להשוות אותם על סט ה-evaluation שלי. Converse הוא גם צורת הקריאה שעובדת יחד עם יכולות אחרות של Bedrock, כמו guardrails ו-prompts שמורים. אפשרויות שמיוחדות למודל עדיין נגישות דרך `additionalModelRequestFields`. הייתי יורד ל-InvokeModel או ל-API תואם-ספק רק כשצריך משהו ש-Converse לא חושף, או כשמעבירים קוד קיים שכבר משתמש ב-SDK אחר.' } }
      ]
    },
    {
      id: 'm03l3', minutes: 15,
      title: { en: 'Streaming, the other APIs, and errors', he: 'Streaming, ה-APIs האחרים, ושגיאות' },
      blocks: [
        { t: 'h', en: 'Streaming with ConverseStream', he: 'Streaming עם ConverseStream' },
        { t: 'p', en: 'With `converse` you wait for the whole answer. For a long answer that can be 20 seconds of an empty screen. [[ConverseStream]] sends the answer in small pieces while it is written. The total time is the same, but the user sees the first words almost at once. That is why chat products care about [[TTFT]].', he: 'עם `converse` מחכים לכל התשובה. בתשובה ארוכה זה יכול להיות 20 שניות של מסך ריק. [[ConverseStream]] שולח את התשובה בחתיכות קטנות תוך כדי כתיבה. הזמן הכולל זהה, אבל המשתמש רואה את המילים הראשונות כמעט מיד. לכן מוצרי צ׳אט מתעניינים ב-[[TTFT]].' },
        { t: 'code', lang: 'python', code: 'resp = client.converse_stream(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    messages=messages,\n    inferenceConfig={"maxTokens": 1000},\n)\n\nfor event in resp["stream"]:\n    if "contentBlockDelta" in event:\n        piece = event["contentBlockDelta"]["delta"].get("text", "")\n        print(piece, end="", flush=True)\n    elif "messageStop" in event:\n        stop_reason = event["messageStop"]["stopReason"]\n    elif "metadata" in event:\n        usage = event["metadata"]["usage"]', caption: { en: 'The request is the same as in `converse`. The response is different: `resp["stream"]` is a series of events, and each event has exactly one key.', he: 'הבקשה זהה לזו של `converse`. התשובה שונה: `resp["stream"]` הוא סדרה של אירועים, ולכל אירוע יש מפתח אחד בדיוק.' } },
        { t: 'table', head: { en: ['Event', 'What it carries'], he: ['אירוע', 'מה הוא נושא'] }, rows: {
          en: [['`messageStart`', 'The role (assistant)'], ['`contentBlockStart`', 'A new block begins, for example a tool request'], ['`contentBlockDelta`', 'A piece of text (or of tool input, or of reasoning)'], ['`contentBlockStop`', 'The block is complete'], ['`messageStop`', 'The `stopReason`'], ['`metadata`', '`usage` and `metrics`. It arrives last.']],
          he: [['`messageStart`', 'ה-role (assistant)'], ['`contentBlockStart`', 'בלוק חדש מתחיל, למשל בקשה לכלי'], ['`contentBlockDelta`', 'חתיכת טקסט (או של קלט לכלי, או של reasoning)'], ['`contentBlockStop`', 'הבלוק הושלם'], ['`messageStop`', 'ה-`stopReason`'], ['`metadata`', '`usage` ו-`metrics`. מגיע אחרון.']] } },
        { t: 'fill', prompt: { en: 'Print the answer piece by piece as it arrives.', he: 'הדפס את התשובה חתיכה אחרי חתיכה כשהיא מגיעה.' },
          lang: 'python', code: 'resp = client.{{1}}(modelId=MODEL_ID, messages=messages)\n\nfor event in resp["{{2}}"]:\n    if "{{3}}" in event:\n        print(event["contentBlockDelta"]["delta"].get("text", ""), end="")', blanks: [ { accept: ['converse_stream'], hint: { en: 'snake_case: the streaming method', he: 'snake_case: מתודת ה-streaming' } }, { accept: ['stream'], hint: { en: 'the key in the response that holds the events', he: 'המפתח בתשובה שמחזיק את האירועים' } }, { accept: ['contentBlockDelta'], hint: { en: 'the event that carries a piece of text', he: 'האירוע שנושא חתיכת טקסט' } } ],
          explain: { en: 'To keep the conversation going you must build the full assistant message yourself: join all the text pieces and append `{"role": "assistant", "content": [{"text": full_text}]}` to the history.', he: 'כדי להמשיך את השיחה צריך לבנות את הודעת ה-assistant המלאה בעצמך: מחברים את כל חתיכות הטקסט ומוסיפים `{"role": "assistant", "content": [{"text": full_text}]}` להיסטוריה.' } },
        { t: 'order', prompt: { en: 'Put the stream events of a simple text answer in the order they arrive.', he: 'סדר את אירועי ה-stream של תשובת טקסט פשוטה לפי סדר ההגעה.' }, items: { en: ['`messageStart`', '`contentBlockDelta` (many times)', '`contentBlockStop`', '`messageStop`', '`metadata`'], he: ['`messageStart`', '`contentBlockDelta` (הרבה פעמים)', '`contentBlockStop`', '`messageStop`', '`metadata`'] },
          explain: { en: 'Start, pieces, block end, message end with the stop reason, and only then the usage numbers.', he: 'התחלה, חתיכות, סוף בלוק, סוף הודעה עם ה-stop reason, ורק אז מספרי ה-usage.' } },
        { t: 'note', kind: 'warn', en: 'Three things that bite people with streaming.\n1. It needs its own IAM action: `bedrock:InvokeModelWithResponseStream`.\n2. Errors can arrive **in the middle** of the stream as events (for example a throttling or a model stream error), after you already showed half an answer. Decide what the user sees then.\n3. You know the `stopReason` and the `usage` only at the end. So you cannot check for `max_tokens` before you show the text. You can only mark the answer as cut afterwards.', he: 'שלושה דברים שנושכים אנשים ב-streaming.\n1. צריך פעולת IAM משלו: `bedrock:InvokeModelWithResponseStream`.\n2. שגיאות יכולות להגיע **באמצע** ה-stream כאירועים (למשל throttling או שגיאת stream של המודל), אחרי שכבר הצגת חצי תשובה. מחליטים מה המשתמש רואה אז.\n3. את ה-`stopReason` וה-`usage` יודעים רק בסוף. לכן אי אפשר לבדוק `max_tokens` לפני שמציגים את הטקסט. אפשר רק לסמן את התשובה כחתוכה אחר כך.' },
        { t: 'quiz', q: { en: 'Your streaming chat must record how many tokens each answer cost. Where do you get the numbers?', he: 'צ׳אט ה-streaming שלך חייב לרשום כמה טוקנים עלתה כל תשובה. מאיפה לוקחים את המספרים?' },
          options: { en: ['From the first `messageStart` event', 'You count the `contentBlockDelta` events', 'Streaming calls do not report usage', 'From the `metadata` event at the end of the stream'], he: ['מהאירוע הראשון `messageStart`', 'סופרים את אירועי ה-`contentBlockDelta`', 'קריאות streaming לא מדווחות usage', 'מאירוע ה-`metadata` בסוף ה-stream'] },
          answer: 3, explain: { en: 'The `metadata` event carries `usage` and `metrics`, and it comes last. Counting delta events is wrong, because one event is not one token. If your loop stops reading early (the user closed the page), you never get the usage. So always read the stream to its end on the server side.', he: 'אירוע ה-`metadata` נושא את `usage` ואת `metrics`, והוא מגיע אחרון. לספור אירועי delta זה שגוי, כי אירוע אחד הוא לא טוקן אחד. אם הלולאה שלך מפסיקה לקרוא מוקדם (המשתמש סגר את הדף), אף פעם לא תקבל את ה-usage. לכן תמיד קוראים את ה-stream עד סופו בצד השרת.' } },
        { t: 'h', en: 'InvokeModel: the older, lower-level call', he: 'InvokeModel: הקריאה הישנה יותר, ברמה נמוכה' },
        { t: 'p', en: 'Before Converse there was [[InvokeModel]], and it is still here. With it you send a JSON body in the **provider\'s own format**, and you get the provider\'s own JSON back. Bedrock passes it through.', he: 'לפני Converse היה [[InvokeModel]], והוא עדיין כאן. איתו שולחים גוף JSON ב**פורמט של הספק עצמו**, ומקבלים בחזרה את ה-JSON של הספק עצמו. Bedrock מעביר אותו הלאה.' },
        { t: 'code', lang: 'python', code: 'import json\n\nresponse = client.invoke_model(\n    modelId="global.anthropic.claude-opus-5",\n    body=json.dumps({\n        "anthropic_version": "bedrock-2023-05-31",\n        "messages": [{"role": "user", "content": "Explain Amazon Bedrock in one sentence."}],\n        "max_tokens": 1024,\n    }),\n)\nresult = json.loads(response["body"].read())', caption: { en: 'InvokeModel with a Claude model. The body is Anthropic\'s format (`max_tokens`, `anthropic_version`). For a Nova or a Llama model the body would look different.', he: 'InvokeModel עם מודל Claude. הגוף הוא בפורמט של Anthropic (`max_tokens`, `anthropic_version`). למודל Nova או Llama הגוף היה נראה אחרת.' } },
        { t: 'table', head: { en: ['', 'Converse', 'InvokeModel'], he: ['', 'Converse', 'InvokeModel'] }, rows: {
          en: [['Request format', 'The same for all models', 'Different for each provider'], ['Changing the model', 'Change one string', 'Rewrite the body and the response parsing'], ['Best for', 'Chat, tools, anything you want portable', 'Full control, embeddings and image models, single calls with large payloads'], ['IAM action', '`bedrock:InvokeModel`', '`bedrock:InvokeModel`']],
          he: [['פורמט הבקשה', 'זהה לכל המודלים', 'שונה לכל ספק'], ['החלפת מודל', 'מחליפים מחרוזת אחת', 'כותבים מחדש את הגוף ואת פענוח התשובה'], ['הכי טוב בשביל', 'צ׳אט, כלים, כל מה שרוצים שיהיה נייד', 'שליטה מלאה, מודלי embeddings ותמונות, קריאות בודדות עם payload גדול'], ['פעולת IAM', '`bedrock:InvokeModel`', '`bedrock:InvokeModel`']] } },
        { t: 'h', en: 'Five APIs, two endpoints', he: 'חמישה APIs, שני endpoints' },
        { t: 'p', en: 'Since the end of 2025 Bedrock also speaks the "languages" of OpenAI and Anthropic. So a team with existing code on the OpenAI SDK or the Anthropic SDK can point it at Bedrock by changing the base URL and the key. That gives five inference APIs:', he: 'מאז סוף 2025 Bedrock מדבר גם את ה"שפות" של OpenAI ושל Anthropic. כך צוות עם קוד קיים על ה-SDK של OpenAI או של Anthropic יכול לכוון אותו ל-Bedrock על ידי שינוי ה-base URL והמפתח. מזה יוצאים חמישה APIs ל-inference:' },
        { t: 'table', head: { en: ['API', 'Whose format', 'Best for'], he: ['API', 'הפורמט של מי', 'הכי טוב בשביל'] }, rows: {
          en: [['Converse / ConverseStream', 'Bedrock', 'Multi-turn chat with one interface for all models. Works with guardrails, stored prompts and prompt routers.'], ['InvokeModel', 'Each provider', 'Single transactions, large payloads, full control'], ['[[Responses API]]', 'OpenAI', 'Stateful conversations: the server can store the response and you continue it with `previous_response_id`'], ['[[Chat Completions]]', 'OpenAI', 'Stateless chat with the OpenAI SDK'], ['[[Messages API]]', 'Anthropic', 'Claude in its native format, with the Anthropic SDK']],
          he: [['Converse / ConverseStream', 'Bedrock', 'צ׳אט מרובה תורות עם ממשק אחד לכל המודלים. עובד עם guardrails, prompts שמורים ו-prompt routers.'], ['InvokeModel', 'כל ספק', 'פעולות בודדות, payload גדול, שליטה מלאה'], ['[[Responses API]]', 'OpenAI', 'שיחות stateful: השרת יכול לשמור את התשובה וממשיכים אותה עם `previous_response_id`'], ['[[Chat Completions]]', 'OpenAI', 'צ׳אט stateless עם ה-SDK של OpenAI'], ['[[Messages API]]', 'Anthropic', 'Claude בפורמט המקורי שלו, עם ה-SDK של Anthropic']] } },
        { t: 'code', lang: 'python', code: '# Environment:\n#   OPENAI_API_KEY=<Bedrock API key>\n#   OPENAI_BASE_URL=https://bedrock-runtime.us-east-1.amazonaws.com/openai/v1\nfrom openai import OpenAI\n\nclient = OpenAI()\nresponse = client.chat.completions.create(\n    model="global.openai.gpt-5.6-sol",\n    messages=[{"role": "user", "content": "Explain Amazon Bedrock in one sentence."}],\n)', caption: { en: 'The OpenAI SDK talking to Bedrock. Only the two environment variables changed. The key is a [[Bedrock API key]] from module 2. The closed GPT models are called through an inference profile ID such as `global.openai.gpt-5.6-sol`.', he: 'ה-SDK של OpenAI מדבר עם Bedrock. רק שני משתני הסביבה השתנו. המפתח הוא [[Bedrock API key]] ממודול 2. למודלי GPT הסגורים קוראים דרך inference profile ID כמו `global.openai.gpt-5.6-sol`.' } },
        { t: 'p', en: 'There are also **two inference endpoints**. The docs say that both run on the same engine and that the per-token price of a model is identical on both. They differ in the features around the call.', he: 'יש גם **שני endpoints ל-inference**. התיעוד אומר ששניהם רצים על אותו מנוע ושהמחיר לטוקן של מודל זהה בשניהם. הם נבדלים ביכולות שמסביב לקריאה.' },
        { t: 'table', head: { en: ['', '`bedrock-runtime` (recommended)', '`bedrock-mantle`'], he: ['', '`bedrock-runtime` (מומלץ)', '`bedrock-mantle`'] }, rows: {
          en: [['Address', '`bedrock-runtime.{region}.amazonaws.com`', '`bedrock-mantle.{region}.api.aws`'], ['Converse and InvokeModel', 'Yes', 'No'], ['OpenAI-compatible APIs', 'Yes, under the path `/openai/v1`', 'Yes'], ['Anthropic Messages API', 'Yes, under the path `/anthropic`', 'Yes'], ['Cross-Region inference profiles', 'Yes', 'No'], ['Guardrails, prompt routing', 'Yes', 'No'], ['Server-side tools (web search), background runs, your own Projects', 'No', 'Yes'], ['IAM action for inference', '`bedrock:InvokeModel`', '`bedrock-mantle:CreateInference`'], ['Quotas', 'Tokens per minute per model, input and output together', 'Separate input and output tokens per minute. Counted apart from runtime.'], ['Model invocation logging', 'Yes', 'Not captured']],
          he: [['כתובת', '`bedrock-runtime.{region}.amazonaws.com`', '`bedrock-mantle.{region}.api.aws`'], ['Converse ו-InvokeModel', 'כן', 'לא'], ['APIs תואמי OpenAI', 'כן, תחת הנתיב `/openai/v1`', 'כן'], ['Messages API של Anthropic', 'כן, תחת הנתיב `/anthropic`', 'כן'], ['Cross-Region inference profiles', 'כן', 'לא'], ['Guardrails, prompt routing', 'כן', 'לא'], ['כלים בצד השרת (חיפוש ברשת), הרצות ברקע, Projects משלך', 'לא', 'כן'], ['פעולת IAM ל-inference', '`bedrock:InvokeModel`', '`bedrock-mantle:CreateInference`'], ['Quotas', 'טוקנים לדקה לכל מודל, קלט ופלט יחד', 'טוקני קלט ופלט לדקה בנפרד. נספרים בנפרד מ-runtime.'], ['Model invocation logging', 'כן', 'לא נקלט']] } },
        { t: 'note', kind: 'tip', en: 'The rule for new work: use [[bedrock-runtime]]. Since August 2026 the docs recommend it for new applications, including code that uses the OpenAI or Anthropic SDKs. Choose [[bedrock-mantle]] when you need something that only it has: server-side tools such as web search, background (asynchronous) responses, or Projects for isolating teams. Both accept normal AWS credentials ([[SigV4]]) or a Bedrock API key.', he: 'הכלל לעבודה חדשה: משתמשים ב-[[bedrock-runtime]]. מאז אוגוסט 2026 התיעוד ממליץ עליו לאפליקציות חדשות, כולל קוד שמשתמש ב-SDKs של OpenAI או Anthropic. בוחרים ב-[[bedrock-mantle]] כשצריך משהו שיש רק בו: כלים בצד השרת כמו חיפוש ברשת, תשובות ברקע (אסינכרוניות), או Projects לבידוד בין צוותים. שניהם מקבלים credentials רגילים של AWS ([[SigV4]]) או Bedrock API key.' },
        { t: 'quiz', q: { en: 'A team has a working app on the OpenAI SDK. They want to move it to Bedrock with minimal code changes, and they need guardrails and cross-Region inference. What do you recommend?', he: 'לצוות יש אפליקציה עובדת על ה-SDK של OpenAI. הם רוצים להעביר אותה ל-Bedrock עם מינימום שינויי קוד, וצריכים guardrails ו-cross-Region inference. מה תמליץ?' },
          options: { en: ['Keep the OpenAI SDK and set its base URL to the `/openai/v1` path of `bedrock-runtime`, with a Bedrock API key', 'Rewrite everything with InvokeModel', 'Use `bedrock-mantle`, because it is the only endpoint that speaks the OpenAI format', 'It is not possible. The OpenAI SDK cannot call Bedrock.'], he: ['להשאיר את ה-SDK של OpenAI ולכוון את ה-base URL שלו לנתיב `/openai/v1` של `bedrock-runtime`, עם Bedrock API key', 'לכתוב הכול מחדש עם InvokeModel', 'להשתמש ב-`bedrock-mantle`, כי זה ה-endpoint היחיד שמדבר בפורמט של OpenAI', 'זה לא אפשרי. ה-SDK של OpenAI לא יכול לקרוא ל-Bedrock.'] },
          answer: 0, explain: { en: 'Both endpoints speak the OpenAI format. But guardrails and cross-Region inference exist only on `bedrock-runtime`, so the requirements decide. The code change is two environment variables and the model name.', he: 'שני ה-endpoints מדברים בפורמט של OpenAI. אבל guardrails ו-cross-Region inference קיימים רק ב-`bedrock-runtime`, כך שהדרישות מכריעות. שינוי הקוד הוא שני משתני סביבה ושם המודל.' } },
        { t: 'quiz', q: { en: 'A role is allowed `bedrock:InvokeModel` on all models. Its code calls a model through the `bedrock-mantle` endpoint and gets AccessDeniedException. Why?', he: 'ל-role מותר `bedrock:InvokeModel` על כל המודלים. הקוד שלו קורא למודל דרך ה-endpoint בשם `bedrock-mantle` ומקבל AccessDeniedException. למה?' },
          options: { en: ['Mantle accepts only API keys, never roles', 'The role must be created again in the mantle Region', 'Inference on mantle is a different IAM action: `bedrock-mantle:CreateInference`', 'Mantle is closed to new customers'], he: ['mantle מקבל רק API keys, אף פעם לא roles', 'צריך ליצור את ה-role מחדש ב-Region של mantle', 'inference ב-mantle הוא פעולת IAM אחרת: `bedrock-mantle:CreateInference`', 'mantle סגור ללקוחות חדשים'] },
          answer: 2, explain: { en: 'The two endpoints have separate IAM namespaces: `bedrock:` and `bedrock-mantle:`. A policy written for one gives nothing on the other. The same separation exists for quotas, metrics and logs.', he: 'לשני ה-endpoints יש מרחבי שמות נפרדים ב-IAM: `bedrock:` ו-`bedrock-mantle:`. policy שנכתבה לאחד לא נותנת כלום בשני. אותה הפרדה קיימת ל-quotas, ל-metrics וללוגים.' } },
        { t: 'match', prompt: { en: 'Match the need to the API.', he: 'התאם את הצורך ל-API.' }, pairs: [
          { a: { en: 'One code path for Claude, Nova and Llama', he: 'מסלול קוד אחד ל-Claude, Nova ו-Llama' }, b: 'Converse' },
          { a: { en: 'Show the answer word by word', he: 'להציג את התשובה מילה אחרי מילה' }, b: 'ConverseStream' },
          { a: { en: 'Call an embeddings model with its native body', he: 'לקרוא למודל embeddings עם הגוף המקורי שלו' }, b: 'InvokeModel' },
          { a: { en: 'Let the server keep the conversation and continue it by ID', he: 'לתת לשרת לשמור את השיחה ולהמשיך אותה לפי מזהה' }, b: 'Responses API' },
          { a: { en: 'Move code written with the Anthropic SDK', he: 'להעביר קוד שנכתב עם ה-SDK של Anthropic' }, b: 'Messages API' }
        ] },
        { t: 'h', en: 'Bedrock API keys in real code', he: 'Bedrock API keys בקוד אמיתי' },
        { t: 'p', en: 'You met the [[Bedrock API key]] in module 2. This is where it matters: the OpenAI and Anthropic SDKs expect one key string, not AWS signatures. boto3 does not need a key (it signs with [[SigV4]]), but it also accepts one: from version 1.39.0 it reads the variable `AWS_BEARER_TOKEN_BEDROCK` by itself. The rules a pro follows:', he: 'פגשת את ה-[[Bedrock API key]] במודול 2. כאן זה נהיה חשוב: ה-SDKs של OpenAI ושל Anthropic מצפים למחרוזת מפתח אחת, לא לחתימות של AWS. boto3 לא צריך מפתח (הוא חותם עם [[SigV4]]), אבל הוא גם מקבל מפתח: מגרסה 1.39.0 הוא קורא לבד את המשתנה `AWS_BEARER_TOKEN_BEDROCK`. הכללים שמקצוען שומר עליהם:' },
        { t: 'list', en: ['In production, use **short-term** keys and create them in code from the role your application already has. They live up to 12 hours (or less, if the session is shorter), work only in the Region where they were made, and carry exactly the permissions of that role. The docs call them "Recommended for production use".', '**Long-term** keys are "Recommended only for exploration". Behind each one AWS creates an IAM user. A long-term key in an environment variable on a server is the old, leaked-access-key problem again.', 'A key does not give permissions by itself. The principal behind it still needs `bedrock:InvokeModel` on the model.', 'A company can switch keys off: a Deny on both `bedrock:CallWithBearerToken` and `bedrock-mantle:CallWithBearerToken`. With the condition key `bedrock:bearerTokenType` (`SHORT_TERM` or `LONG_TERM`) it can allow only short-term keys.', 'Calls made with a key are logged in CloudTrail. The key itself is not written to the log.'], he: ['ב-production משתמשים במפתחות **קצרי-טווח** ויוצרים אותם בקוד מתוך ה-role שכבר יש לאפליקציה שלך. הם חיים עד 12 שעות (או פחות, אם ה-session קצר יותר), עובדים רק ב-Region שבו נוצרו, ונושאים בדיוק את ההרשאות של אותו role. התיעוד קורא להם "Recommended for production use".', 'מפתחות **ארוכי-טווח** הם "Recommended only for exploration". מאחורי כל אחד AWS יוצרת IAM user. מפתח ארוך-טווח במשתנה סביבה על שרת הוא שוב הבעיה הישנה של access key שדלף.', 'מפתח לא נותן הרשאות בעצמו. ה-principal שמאחוריו עדיין צריך `bedrock:InvokeModel` על המודל.', 'חברה יכולה לכבות מפתחות: Deny גם על `bedrock:CallWithBearerToken` וגם על `bedrock-mantle:CallWithBearerToken`. עם ה-condition key בשם `bedrock:bearerTokenType` (`SHORT_TERM` או `LONG_TERM`) היא יכולה להרשות רק מפתחות קצרי-טווח.', 'קריאות שנעשו עם מפתח נרשמות ב-CloudTrail. המפתח עצמו לא נכתב ללוג.'] },
        { t: 'code', lang: 'python', code: '# pip install -U anthropic aws-bedrock-token-generator\nfrom anthropic import Anthropic\nfrom aws_bedrock_token_generator import provide_token\n\ntoken = provide_token(region="us-east-1")   # short-term key from your current AWS credentials\nclient = Anthropic(\n    base_url="https://bedrock-runtime.us-east-1.amazonaws.com/anthropic",\n    api_key=token,\n)\nresponse = client.messages.create(\n    model="global.anthropic.claude-fable-5-2",\n    max_tokens=16000,\n    messages=[{"role": "user", "content": "Can you explain the features of Amazon Bedrock?"}],\n)', caption: { en: 'The Anthropic SDK against the `/anthropic` path of `bedrock-runtime`. No long-lived secret is stored anywhere: the key is made from the role at start-up. A short-term key expires, so a long-running service must make a new one before the old one ends.', he: 'ה-SDK של Anthropic מול הנתיב `/anthropic` של `bedrock-runtime`. שום secret ארוך-חיים לא נשמר בשום מקום: המפתח נוצר מתוך ה-role בזמן העלייה. מפתח קצר-טווח פג, ולכן שירות שרץ זמן רב חייב ליצור מפתח חדש לפני שהישן נגמר.' } },
        { t: 'quiz', q: { en: 'A team runs a container on AWS with an IAM role. To use the OpenAI SDK, they created a long-term Bedrock API key in the console and put it in the container\'s environment. What do you advise?', he: 'צוות מריץ container ב-AWS עם IAM role. כדי להשתמש ב-SDK של OpenAI, הם יצרו Bedrock API key ארוך-טווח בקונסול ושמו אותו בסביבה של ה-container. מה תמליץ?' },
          options: { en: ['It is fine, as long as the key expires in one year', 'Switch to SigV4 only: the OpenAI SDK cannot use Bedrock keys', 'Give the long-term key\'s IAM user `AmazonBedrockFullAccess` so it never fails', 'Generate a short-term key in code from the container\'s role (for example with `aws-bedrock-token-generator`), refresh it before it expires, and delete the long-term key'], he: ['זה בסדר, כל עוד המפתח פג בעוד שנה', 'לעבור ל-SigV4 בלבד: ה-SDK של OpenAI לא יכול להשתמש במפתחות Bedrock', 'לתת ל-IAM user של המפתח הארוך `AmazonBedrockFullAccess` כדי שאף פעם לא ייכשל', 'ליצור מפתח קצר-טווח בקוד מתוך ה-role של ה-container (למשל עם `aws-bedrock-token-generator`), לחדש אותו לפני שהוא פג, ולמחוק את המפתח הארוך'] },
          answer: 3, explain: { en: 'The container already has a role. A short-term key made from it has the same permissions, lives at most 12 hours and stores no secret. A long-term key is a standing secret tied to a separate IAM user, which the docs recommend only for exploration. The OpenAI SDK reads a Bedrock key from `OPENAI_API_KEY` without problems.', he: 'ל-container כבר יש role. מפתח קצר-טווח שנוצר ממנו מקבל אותן הרשאות, חי לכל היותר 12 שעות ולא שומר שום secret. מפתח ארוך-טווח הוא secret קבוע שקשור ל-IAM user נפרד, והתיעוד ממליץ עליו רק לחקירה. ה-SDK של OpenAI קורא Bedrock key מ-`OPENAI_API_KEY` בלי בעיה.' } },
        { t: 'terminal', title: { en: 'Lab: one model, three ways in', he: 'מעבדה: מודל אחד, שלוש דרכים להיכנס' }, intro: { en: 'Your shell is logged in with the `dev` profile, and `AWS_REGION` is `us-east-1`. A short-term Bedrock API key is already in the variable `$KEY`. Call Claude Sonnet 5.5 with the CLI, then with plain HTTP, then prepare the OpenAI SDK.', he: 'ה-shell שלך מחובר עם ה-profile בשם `dev`, ו-`AWS_REGION` הוא `us-east-1`. מפתח Bedrock API קצר-טווח כבר נמצא במשתנה `$KEY`. קרא ל-Claude Sonnet 5.5 עם ה-CLI, אחר כך עם HTTP רגיל, ואז הכן את ה-SDK של OpenAI.' }, shell: 'bash — ~/chat-app',
          steps: [
            { ask: { en: 'Find the inference profile ID for Claude Sonnet 5.5. List the inference profiles (a control plane call).', he: 'מצא את ה-inference profile ID של Claude Sonnet 5.5. הצג את רשימת ה-inference profiles (קריאת control plane).' }, accept: ['^aws\\s+bedrock\\s+list-inference-profiles\\b'], hint: 'aws bedrock list-inference-profiles', output: '{\n    "inferenceProfileSummaries": [\n        {\n            "inferenceProfileId": "us.anthropic.claude-sonnet-5-5",\n            "status": "ACTIVE",\n            ...\n        },\n        ...\n    ]\n}', wrong: 'Hint: listing is a control plane call, so the CLI service is "bedrock", not "bedrock-runtime".' },
            { ask: { en: 'Call the Converse API from the CLI with that profile ID. Send one user message with the text "Hello". (The CLI service name is the same as the boto3 client for inference. Its options are the API fields in kebab-case.)', he: 'קרא ל-Converse API מה-CLI עם ה-profile ID הזה. שלח הודעת משתמש אחת עם הטקסט "Hello". (שם השירות ב-CLI זהה לשם ה-client של boto3 ל-inference. האפשרויות שלו הן שדות ה-API ב-kebab-case.)' }, accept: ['^aws\\s+bedrock-runtime\\s+converse\\b.*--model-id[\\s=]["\']?us\\.anthropic\\.claude-sonnet-5-5\\b.*--messages', '^aws\\s+bedrock-runtime\\s+converse\\b.*--messages.*--model-id[\\s=]["\']?us\\.anthropic\\.claude-sonnet-5-5\\b'], hint: 'aws bedrock-runtime converse --model-id us.anthropic.claude-sonnet-5-5 --messages \'[{"role":"user","content":[{"text":"Hello"}]}]\'', output: '{\n    "output": {\n        "message": {\n            "role": "assistant",\n            "content": [ { "text": "Hello! How can I help you today?" } ]\n        }\n    },\n    "stopReason": "end_turn",\n    "usage": { "inputTokens": 8, "outputTokens": 12, "totalTokens": 20 },\n    "metrics": { "latencyMs": 540 }\n}', wrong: 'Hint: aws bedrock-runtime converse --model-id <profile id> --messages \'<JSON list>\'' },
            { ask: { en: 'Now prepare a call without AWS signatures. Put the key from `$KEY` into the environment variable that boto3 and the docs use for Bedrock API keys.', he: 'עכשיו הכן קריאה בלי חתימות של AWS. שים את המפתח מ-`$KEY` במשתנה הסביבה ש-boto3 והתיעוד משתמשים בו ל-Bedrock API keys.' }, accept: ['^export\\s+AWS_BEARER_TOKEN_BEDROCK=["\']?\\$\\{?KEY\\}?["\']?$'], hint: 'export AWS_BEARER_TOKEN_BEDROCK=$KEY', output: '' },
            { ask: { en: 'Call the same model with curl: POST to the `/model/{modelId}/converse` path of `bedrock-runtime` in us-east-1, with the key in an `Authorization: Bearer` header and a JSON body with one "Hello" message.', he: 'קרא לאותו מודל עם curl: בקשת POST לנתיב `/model/{modelId}/converse` של `bedrock-runtime` ב-us-east-1, עם המפתח ב-header מסוג `Authorization: Bearer` וגוף JSON עם הודעת "Hello" אחת.' }, accept: ['^curl\\b.*bedrock-runtime\\.us-east-1\\.amazonaws\\.com/model/[^/\\s]+/converse.*authorization:\\s*bearer'], hint: 'curl -X POST "https://bedrock-runtime.us-east-1.amazonaws.com/model/us.anthropic.claude-sonnet-5-5/converse" -H "Content-Type: application/json" -H "Authorization: Bearer $AWS_BEARER_TOKEN_BEDROCK" -d \'{"messages": [{"role": "user", "content": [{"text": "Hello"}]}]}\'', output: '{"metrics":{"latencyMs":498},"output":{"message":{"content":[{"text":"Hello! What can I do for you?"}],"role":"assistant"}},"stopReason":"end_turn","usage":{"inputTokens":8,"outputTokens":11,"totalTokens":19}}', wrong: 'Hint: the URL is https://bedrock-runtime.us-east-1.amazonaws.com/model/<model id>/converse and the header is "Authorization: Bearer <key>".' },
            { ask: { en: 'A teammate\'s code uses the OpenAI SDK. Point the SDK at the OpenAI-compatible path of `bedrock-runtime` in us-east-1 by setting its base URL variable.', he: 'הקוד של חבר צוות משתמש ב-SDK של OpenAI. כוון את ה-SDK לנתיב התואם-OpenAI של `bedrock-runtime` ב-us-east-1 על ידי הגדרת משתנה ה-base URL שלו.' }, accept: ['^export\\s+OPENAI_BASE_URL=["\']?https://bedrock-runtime\\.us-east-1\\.amazonaws\\.com/openai/v1/?["\']?$'], hint: 'export OPENAI_BASE_URL=https://bedrock-runtime.us-east-1.amazonaws.com/openai/v1', output: '', wrong: 'Hint: the path is /openai/v1 on bedrock-runtime.us-east-1.amazonaws.com.' },
            { ask: { en: 'Last: give the OpenAI SDK its key. It reads it from its usual variable. Use the Bedrock key.', he: 'אחרון: תן ל-SDK של OpenAI את המפתח שלו. הוא קורא אותו מהמשתנה הרגיל שלו. השתמש במפתח של Bedrock.' }, accept: ['^export\\s+OPENAI_API_KEY=["\']?\\$\\{?(KEY|AWS_BEARER_TOKEN_BEDROCK)\\}?["\']?$'], hint: 'export OPENAI_API_KEY=$AWS_BEARER_TOKEN_BEDROCK', output: '' }
          ],
          done: { en: 'One model, reached three ways: the AWS CLI with SigV4, plain HTTP with a bearer key, and an OpenAI SDK set up by two variables. All three went to the same endpoint, are counted against the same quota, and need the same `bedrock:InvokeModel` permission. Remember that the key you used lives at most 12 hours.', he: 'מודל אחד, שלוש דרכים להגיע אליו: ה-AWS CLI עם SigV4, HTTP רגיל עם bearer key, ו-SDK של OpenAI שהוגדר בשני משתנים. שלושתם הלכו לאותו endpoint, נספרים מול אותה quota, וצריכים את אותה הרשאת `bedrock:InvokeModel`. זכור שהמפתח שהשתמשת בו חי לכל היותר 12 שעות.' } },
        { t: 'h', en: 'Errors: which ones to retry', he: 'שגיאות: על אילו מנסים שוב' },
        { t: 'p', en: 'Production code meets errors every day. The one skill here is to sort them into two groups: **retry later** and **fix the request**. Retrying a broken request only burns time. Giving up on a busy service loses the user.', he: 'קוד ב-production פוגש שגיאות כל יום. המיומנות היחידה כאן היא למיין אותן לשתי קבוצות: **לנסות שוב אחר כך** ו**לתקן את הבקשה**. ניסיון חוזר לבקשה שבורה רק שורף זמן. לוותר מול שירות עמוס מאבד את המשתמש.' },
        { t: 'table', head: { en: ['Error', 'HTTP', 'Meaning', 'Retry?'], he: ['שגיאה', 'HTTP', 'משמעות', 'לנסות שוב?'] }, rows: {
          en: [['`ValidationException`', '400', 'The request is built wrong: a bad shape, a bad parameter, an ID that does not fit', 'No. Fix the request.'], ['`AccessDeniedException`', '403', 'IAM said no (module 2)', 'No. Fix the permissions.'], ['`ResourceNotFoundException`', '404', 'The model or the resource was not found (check the ID and the Region)', 'No'], ['`ModelTimeoutException`', '408', 'The model took too long', 'Carefully. The same huge request will probably time out again.'], ['`ModelErrorException`', '424', 'The model failed while processing the request', 'Maybe once'], ['`ThrottlingException`', '429', 'You went over a quota', 'Yes, with backoff'], ['`ModelNotReadyException`', '429', 'The model is not ready yet', 'Yes. The SDK itself retries it up to 5 times.'], ['`InternalServerException`', '500', 'A problem on the AWS side', 'Yes, with backoff'], ['`ServiceUnavailableException`', '503', 'The service has no capacity right now. This is not your quota.', 'Yes, with backoff. Consider another Region or a cross-Region profile.']],
          he: [['`ValidationException`', '400', 'הבקשה בנויה לא נכון: צורה שגויה, פרמטר שגוי, מזהה שלא מתאים', 'לא. מתקנים את הבקשה.'], ['`AccessDeniedException`', '403', 'IAM אמר לא (מודול 2)', 'לא. מתקנים את ההרשאות.'], ['`ResourceNotFoundException`', '404', 'המודל או המשאב לא נמצאו (בדוק את המזהה ואת ה-Region)', 'לא'], ['`ModelTimeoutException`', '408', 'המודל לקח יותר מדי זמן', 'בזהירות. אותה בקשה ענקית כנראה תיכשל שוב.'], ['`ModelErrorException`', '424', 'המודל נכשל בזמן עיבוד הבקשה', 'אולי פעם אחת'], ['`ThrottlingException`', '429', 'עברת quota', 'כן, עם backoff'], ['`ModelNotReadyException`', '429', 'המודל עדיין לא מוכן', 'כן. ה-SDK עצמו מנסה שוב עד 5 פעמים.'], ['`InternalServerException`', '500', 'בעיה בצד של AWS', 'כן, עם backoff'], ['`ServiceUnavailableException`', '503', 'לשירות אין קיבולת כרגע. זו לא ה-quota שלך.', 'כן, עם backoff. שקול Region אחר או cross-Region profile.']] } },
        { t: 'note', kind: 'info', en: 'Two more places where errors show up. In a stream they arrive as events with lowercase names (`throttlingException`, `modelStreamErrorException` with 424, `serviceUnavailableException`, and others). Through the Anthropic-compatible API you can also get `overloaded_error` (HTTP 529): back off and respect the `Retry-After` header. And remember the difference between 429 and 503: a 429 `ThrottlingException` is **your** account quota, a 503 is the service\'s capacity. A quota increase helps only the first.', he: 'עוד שני מקומות שבהם שגיאות מופיעות. ב-stream הן מגיעות כאירועים עם שמות באותיות קטנות (`throttlingException`, `modelStreamErrorException` עם 424, `serviceUnavailableException` ואחרים). דרך ה-API התואם-Anthropic אפשר לקבל גם `overloaded_error` (HTTP 529): עושים backoff ומכבדים את ה-header בשם `Retry-After`. וזכור את ההבדל בין 429 ל-503: ‏429 `ThrottlingException` הוא ה-quota של **החשבון שלך**, 503 הוא הקיבולת של השירות. העלאת quota עוזרת רק לראשון.' },
        { t: 'p', en: '[[Exponential backoff]] means: after a failure wait a little, and after each further failure wait twice as long. **Jitter** means adding a small random part to each wait. Without jitter, a thousand clients that were throttled at the same second all come back at the same second, and are throttled again together.', he: '[[Exponential backoff]] אומר: אחרי כישלון מחכים קצת, ואחרי כל כישלון נוסף מחכים כפול. **Jitter** אומר להוסיף חלק אקראי קטן לכל המתנה. בלי jitter, אלף לקוחות שקיבלו throttling באותה שנייה חוזרים כולם באותה שנייה, ומקבלים throttling שוב יחד.' },
        { t: 'code', lang: 'python', code: 'import random, time\nfrom botocore.exceptions import ClientError\n\nRETRYABLE = {"ThrottlingException", "ServiceUnavailableException",\n             "InternalServerException", "ModelNotReadyException"}\n\ndef converse_with_retry(client, max_attempts=5, **kwargs):\n    for attempt in range(max_attempts):\n        try:\n            return client.converse(**kwargs)\n        except ClientError as err:\n            code = err.response["Error"]["Code"]\n            if code not in RETRYABLE or attempt == max_attempts - 1:\n                raise\n            wait = min(2 ** attempt, 30) + random.random()\n            time.sleep(wait)', caption: { en: 'A manual retry loop, so that you can see the logic: waits of about 1, 2, 4, 8 seconds, each with a random part. boto3 also has built-in retries, which you configure when you create the client.', he: 'לולאת retry ידנית, כדי שתראה את הלוגיקה: המתנות של בערך 1, 2, 4, 8 שניות, כל אחת עם חלק אקראי. ל-boto3 יש גם retries מובנים, שמגדירים כשיוצרים את ה-client.' } },
        { t: 'fill', prompt: { en: 'Complete the retry logic: read the error code, retry only on throttling, and wait longer each time with jitter.', he: 'השלם את לוגיקת ה-retry: קרא את קוד השגיאה, נסה שוב רק על throttling, וחכה יותר בכל פעם עם jitter.' },
          lang: 'python', code: 'except ClientError as err:\n    code = err.response["Error"]["{{1}}"]\n    if code != "{{2}}":\n        raise\n    wait = min(2 ** {{3}}, 30) + random.random()\n    time.sleep(wait)', blanks: [ { accept: ['Code'], hint: { en: 'the key that holds the error name', he: 'המפתח שמחזיק את שם השגיאה' } }, { accept: ['ThrottlingException'], hint: { en: 'the HTTP 429 quota error', he: 'שגיאת ה-quota עם HTTP 429' } }, { accept: ['attempt'], hint: { en: 'the loop counter: 0, 1, 2…', he: 'מונה הלולאה: 0, 1, 2…' } } ],
          explain: { en: 'Two to the power of `attempt` gives 1, 2, 4, 8… seconds. `min(…, 30)` puts a ceiling on the wait. `random.random()` adds up to one second of jitter. Any other error code is raised at once, because waiting will not fix it.', he: 'שתיים בחזקת `attempt` נותן 1, 2, 4, 8… שניות. `min(…, 30)` שם תקרה להמתנה. `random.random()` מוסיף עד שנייה אחת של jitter. כל קוד שגיאה אחר נזרק מיד, כי המתנה לא תתקן אותו.' } },
        { t: 'quiz', q: { en: 'Which of these errors are worth retrying with backoff? Pick all that apply.', he: 'על אילו מהשגיאות האלה שווה לנסות שוב עם backoff? בחר את כל הנכונים.' },
          options: { en: ['`ThrottlingException` (429)', '`ValidationException` (400)', '`ServiceUnavailableException` (503)', '`AccessDeniedException` (403)'], he: ['`ThrottlingException` (429)', '`ValidationException` (400)', '`ServiceUnavailableException` (503)', '`AccessDeniedException` (403)'] },
          answer: [0, 2], explain: { en: '429 and 503 are about load: the same request can succeed a moment later. 400 and 403 are about the request itself or about your permissions. The same request will fail the same way a hundred times.', he: '429 ו-503 קשורים לעומס: אותה בקשה יכולה להצליח רגע אחר כך. 400 ו-403 קשורים לבקשה עצמה או להרשאות שלך. אותה בקשה תיכשל באותה צורה מאה פעמים.' } },
        { t: 'quiz', q: { en: 'Requests that ask for very long reports sometimes fail with `ModelTimeoutException`. Your retry loop sends the same request again, and it fails again. What is the better direction?', he: 'בקשות שמבקשות דוחות ארוכים מאוד נכשלות לפעמים עם `ModelTimeoutException`. לולאת ה-retry שלך שולחת את אותה בקשה שוב, והיא נכשלת שוב. מה הכיוון הטוב יותר?' },
          options: { en: ['Add ten more retries', 'Make each call smaller: stream the answer, lower `maxTokens`, or split the report into sections that are generated separately', 'Ask for more IAM permissions', 'Turn off the system prompt'], he: ['להוסיף עוד עשרה retries', 'להקטין כל קריאה: להזרים את התשובה, להוריד את `maxTokens`, או לפצל את הדוח לחלקים שנוצרים בנפרד', 'לבקש עוד הרשאות IAM', 'לבטל את ה-system prompt'] },
          answer: 1, explain: { en: 'A timeout means that this piece of work is too long for one call. More retries of the same work only repeat the wait. Make the unit of work smaller. Check also the timeout settings of your own HTTP client, because sometimes it is your side that gives up first.', he: 'timeout אומר שיחידת העבודה הזו ארוכה מדי לקריאה אחת. עוד retries של אותה עבודה רק חוזרים על ההמתנה. מקטינים את יחידת העבודה. בדוק גם את הגדרות ה-timeout של ה-HTTP client שלך, כי לפעמים דווקא הצד שלך מוותר ראשון.' } },
        { t: 'reveal', q: { en: 'Interview question: "Your service gets ThrottlingException from Bedrock during peaks. What do you do, in order?"', he: 'שאלת ראיון: "השירות שלך מקבל ThrottlingException מ-Bedrock בשעות שיא. מה אתה עושה, לפי הסדר?"' },
          a: { en: 'First I make the client behave well: retries with exponential backoff and jitter, and a limit on how many requests run in parallel, so that we do not make our own storm. Second, I look at how we use the quota: is `maxTokens` far higher than the real answers, are prompts longer than needed, can prompt caching take a part of the input out of the count. Third, I spread the load: a cross-Region inference profile, moving non-urgent work to batch or to off-peak hours, and maybe a fallback to another model for simple requests. Fourth, with the real traffic numbers in hand, I ask for a quota increase. If the product needs guaranteed capacity, I look at reserved capacity. I also add a CloudWatch alarm on throttles, so that we see it before the users do.', he: 'קודם גורמים ל-client להתנהג יפה: retries עם exponential backoff ו-jitter, והגבלה על כמה בקשות רצות במקביל, כדי שלא ניצור סערה משלנו. שנית, בודקים איך אנחנו משתמשים ב-quota: האם `maxTokens` גבוה בהרבה מהתשובות האמיתיות, האם הפרומפטים ארוכים מהנדרש, האם prompt caching יכול להוציא חלק מהקלט מהספירה. שלישית, מפזרים את העומס: cross-Region inference profile, העברת עבודה לא דחופה ל-batch או לשעות שקטות, ואולי fallback למודל אחר לבקשות פשוטות. רביעית, עם מספרי התעבורה האמיתיים ביד, מבקשים העלאת quota. אם המוצר צריך קיבולת מובטחת, בודקים קיבולת שמורה. מוסיפים גם alarm של CloudWatch על throttles, כדי שנראה את זה לפני המשתמשים.' } }
      ]
    },
    {
      id: 'm03l4', minutes: 16,
      title: { en: 'Inference options and cost', he: 'אפשרויות inference ועלות' },
      blocks: [
        { t: 'p', en: 'The same model can be bought in several ways. After the choice of model and the size of your prompts, this is the biggest lever on your bill. It also decides how your application behaves under load. A pro knows the whole menu and can say when each item fits.', he: 'את אותו מודל אפשר לקנות בכמה דרכים. אחרי בחירת המודל וגודל הפרומפטים, זה המנוף הכי גדול על החשבונית. זה גם קובע איך האפליקציה מתנהגת בעומס. מקצוען מכיר את כל התפריט ויודע להגיד מתי כל פריט מתאים.' },
        { t: 'table', head: { en: ['Option', 'You pay', 'Fits'], he: ['אפשרות', 'משלמים', 'מתאים ל'] }, rows: {
          en: [['[[On-demand]], Standard tier', 'Per input and output token', 'The default. Start here.'], ['Priority tier', 'Per token, at a premium', 'Requests where speed is worth money'], ['Flex tier', 'Per token, at a discount', 'Work that can wait a little: evaluations, summaries, background agents'], ['[[Batch inference]]', 'Per token, at the batch price', 'Large jobs with no user waiting'], ['Reserved tier', 'A fixed price for reserved tokens-per-minute, with a 1 or 3 month term', 'Steady, large production traffic that needs guaranteed capacity'], ['[[Provisioned Throughput]]', 'Per hour, per model unit', 'Dedicated capacity for the models that support it, and for custom models']],
          he: [['[[On-demand]], Standard tier', 'לפי טוקן קלט ופלט', 'ברירת המחדל. מתחילים כאן.'], ['Priority tier', 'לפי טוקן, בתוספת מחיר', 'בקשות שבהן מהירות שווה כסף'], ['Flex tier', 'לפי טוקן, בהנחה', 'עבודה שיכולה לחכות קצת: evaluations, סיכומים, סוכני רקע'], ['[[Batch inference]]', 'לפי טוקן, במחיר batch', 'עבודות גדולות שאף משתמש לא מחכה להן'], ['Reserved tier', 'מחיר קבוע על טוקנים-לדקה שמורים, בהתחייבות של חודש או 3 חודשים', 'תעבורת production גדולה ויציבה שצריכה קיבולת מובטחת'], ['[[Provisioned Throughput]]', 'לפי שעה, לכל model unit', 'קיבולת ייעודית למודלים שתומכים בזה, ולמודלים מותאמים']] } },
        { t: 'note', kind: 'info', en: 'This course teaches what you pay **for**, not exact prices. Prices change, and they differ by model and Region. For real numbers open the Bedrock pricing page. The few numbers in this lesson are from the docs of November 2026.', he: 'הקורס הזה מלמד **על מה** משלמים, לא מחירים מדויקים. מחירים משתנים, והם שונים לפי מודל ו-Region. למספרים אמיתיים פותחים את דף המחירים של Bedrock. המספרים המעטים בשיעור הזה הם מהתיעוד של נובמבר 2026.' },
        { t: 'h', en: 'Service tiers', he: 'Service tiers' },
        { t: 'p', en: 'A [[Service tier]] is the priority class of one request. There are four: Reserved, Priority, Standard and Flex. You choose it per request. In Converse it is one more field:', he: '[[Service tier]] הוא מחלקת העדיפות של בקשה אחת. יש ארבעה: Reserved, Priority, Standard ו-Flex. בוחרים אותו לכל בקשה. ב-Converse זה עוד שדה אחד:' },
        { t: 'code', lang: 'python', code: 'response = client.converse(\n    modelId=MODEL_ID,\n    messages=messages,\n    serviceTier={"type": "flex"},   # reserved | priority | default | flex\n)\nprint(response["serviceTier"])       # the tier that was actually applied', caption: { en: 'Leaving the field out means Standard (`default`).', he: 'השמטת השדה פירושה Standard (`default`).' } },
        { t: 'list', en: ['The on-demand quota is **shared** by Priority, Standard and Flex. Flex gives you a lower price, not more quota.', 'Not every model has every tier. Claude Fable 5.2, for example, is Standard only. Check the model card.', 'A company can forbid a tier with IAM, using the condition key `bedrock:ServiceTier`. For example: a Deny on `priority`, so that nobody pays the premium by accident.', 'The Reserved tier is not a switch that you flip. You reserve input and output tokens-per-minute through your AWS account team (the minimum is 100,000 input and 10,000 output tokens per minute), and traffic above the reservation overflows to Standard.'], he: ['ה-quota של on-demand **משותפת** ל-Priority, Standard ו-Flex. Flex נותן מחיר נמוך יותר, לא יותר quota.', 'לא לכל מודל יש כל tier. Claude Fable 5.2, למשל, הוא Standard בלבד. בדוק ב-model card.', 'חברה יכולה לאסור tier עם IAM, בעזרת ה-condition key בשם `bedrock:ServiceTier`. למשל: Deny על `priority`, כדי שאף אחד לא ישלם את התוספת בטעות.', 'ה-Reserved tier הוא לא מתג שמדליקים. מזמינים טוקנים-לדקה של קלט ופלט דרך צוות החשבון שלך ב-AWS (המינימום הוא 100,000 טוקני קלט ו-10,000 טוקני פלט לדקה), ותעבורה מעל ההזמנה גולשת ל-Standard.'] },
        { t: 'h', en: 'Batch inference', he: 'Batch inference' },
        { t: 'p', en: 'With [[Batch inference]] you do not call the model. You put a `.jsonl` file in [[S3]], one request per line, and start a job. Bedrock works through the file and writes the answers to S3. It is the right tool when nobody waits for the answer: classify last month\'s tickets, summarize 50,000 documents, generate test data.', he: 'עם [[Batch inference]] לא קוראים למודל. שמים קובץ `.jsonl` ב-[[S3]], בקשה אחת בכל שורה, ומתחילים עבודה. Bedrock עובר על הקובץ וכותב את התשובות ל-S3. זה הכלי הנכון כשאף אחד לא מחכה לתשובה: לסווג את הטיקטים של החודש שעבר, לסכם 50,000 מסמכים, ליצור מידע לבדיקות.' },
        { t: 'code', lang: 'json', code: '{"recordId": "CALL0000001", "modelInput": {"messages": [{"role": "user", "content": [{"text": "Summarize ticket 1: ..."}]}], "inferenceConfig": {"maxTokens": 1024}}}\n{"recordId": "CALL0000002", "modelInput": {"messages": [{"role": "user", "content": [{"text": "Summarize ticket 2: ..."}]}], "inferenceConfig": {"maxTokens": 1024}}}', caption: { en: 'Two lines of a batch input file in the Converse format. `modelInput` is a normal Converse request body.', he: 'שתי שורות של קובץ קלט ל-batch בפורמט Converse. `modelInput` הוא גוף רגיל של בקשת Converse.' } },
        { t: 'list', en: ['You start the job with `create_model_invocation_job` on the `bedrock` client (the control plane). It needs a job name, a model, an input and an output location in S3, and a [[Service role]] that can read and write those locations.', 'The job type is `InvokeModel` (the default, with native bodies) or `Converse`.', 'The order of the output is not guaranteed. Use `recordId` to match answers to questions.', 'On-demand traffic has priority over batch, and the docs say that job completion is not guaranteed. The default time limit is 24 hours.', 'Limits to remember: Converse-type batch jobs do not support tool calling, and prompt caching does not work with batch.'], he: ['מתחילים את העבודה עם `create_model_invocation_job` ב-client בשם `bedrock` (ה-control plane). היא צריכה שם עבודה, מודל, מיקום קלט ומיקום פלט ב-S3, ו-[[Service role]] שיכול לקרוא ולכתוב במיקומים האלה.', 'סוג העבודה הוא `InvokeModel` (ברירת המחדל, עם גופים מקוריים) או `Converse`.', 'סדר הפלט לא מובטח. משתמשים ב-`recordId` כדי להתאים תשובות לשאלות.', 'לתעבורת on-demand יש עדיפות על batch, והתיעוד אומר שסיום העבודה לא מובטח. מגבלת הזמן ברירת המחדל היא 24 שעות.', 'מגבלות שכדאי לזכור: עבודות batch מסוג Converse לא תומכות בקריאה לכלים, ו-prompt caching לא עובד עם batch.'] },
        { t: 'quiz', q: { en: 'Every night you must summarize about 50,000 support tickets. The summaries are needed by 08:00 and nobody looks at them before that. Which option fits best?', he: 'כל לילה צריך לסכם בערך 50,000 טיקטים של תמיכה. הסיכומים נדרשים עד 08:00 ואף אחד לא מסתכל עליהם קודם. איזו אפשרות הכי מתאימה?' },
          options: { en: ['The Priority tier, to be sure it is fast', 'Provisioned Throughput with a 6-month commitment', 'Batch inference (or the Flex tier): lower price, no need for an immediate answer', 'A loop of on-demand calls at 07:55'], he: ['Priority tier, כדי לוודא שזה מהיר', 'Provisioned Throughput עם התחייבות ל-6 חודשים', 'Batch inference (או Flex tier): מחיר נמוך יותר, אין צורך בתשובה מיידית', 'לולאה של קריאות on-demand ב-07:55'] },
          answer: 2, explain: { en: 'Nobody is waiting, so you should not pay for speed. Batch and Flex exist exactly for this. Priority costs extra for latency that nobody needs. Dedicated capacity for a few hours of work per night is waste. And a last-minute loop will run into the tokens-per-minute quota.', he: 'אף אחד לא מחכה, אז לא צריך לשלם על מהירות. Batch ו-Flex קיימים בדיוק בשביל זה. Priority עולה יותר בשביל latency שאף אחד לא צריך. קיבולת ייעודית בשביל כמה שעות עבודה בלילה היא בזבוז. ולולאה של הרגע האחרון תיתקע ב-quota של טוקנים לדקה.' } },
        { t: 'h', en: 'Provisioned Throughput', he: 'Provisioned Throughput' },
        { t: 'p', en: '[[Provisioned Throughput]] (PT) is dedicated capacity for one model. You buy **model units**, pay per hour, and can commit for one or six months to get a lower hourly price. The meter runs until you delete it. Three facts that people miss. First, the list of base models that support PT is short and mostly older (Nova and Llama families, a few others). The current Claude and GPT models are not in it, and for them the Reserved tier plays this role. Second, PT does not work with inference profiles or with batch. Third, PT is one of the two ways to serve a custom model (lesson 5).', he: '[[Provisioned Throughput]] (PT) הוא קיבולת ייעודית למודל אחד. קונים **model units**, משלמים לפי שעה, ואפשר להתחייב לחודש או לשישה חודשים כדי לקבל מחיר שעתי נמוך יותר. המונה רץ עד שמוחקים. שלוש עובדות שאנשים מפספסים. ראשית, רשימת מודלי הבסיס שתומכים ב-PT קצרה ורובה ישנה (משפחות Nova ו-Llama ועוד כמה). מודלי Claude ו-GPT העדכניים לא נמצאים בה, ובשבילם ה-Reserved tier ממלא את התפקיד הזה. שנית, PT לא עובד עם inference profiles או עם batch. שלישית, PT הוא אחת משתי הדרכים להגיש מודל מותאם (שיעור 5).' },
        { t: 'h', en: 'Cross-Region inference: geographic and global', he: 'Cross-Region inference: גאוגרפי וגלובלי' },
        { t: 'p', en: 'In lesson 1 you saw that an [[Inference profile]] lets Bedrock run your request in one of several Regions. There are two families of system profiles, and the choice is a business decision, not only a technical one.', he: 'בשיעור 1 ראית ש-[[Inference profile]] מאפשר ל-Bedrock להריץ את הבקשה שלך באחד מכמה Regions. יש שתי משפחות של system profiles, והבחירה היא החלטה עסקית, לא רק טכנית.' },
        { t: 'table', head: { en: ['', 'Geographic (for example `us.`)', 'Global (`global.`)'], he: ['', 'גאוגרפי (למשל `us.`)', 'גלובלי (`global.`)'] }, rows: {
          en: [['Where data is processed', 'Inside one geography (US, EU, APAC…)', 'Any supported commercial Region'], ['Price', 'Standard pricing', 'About 10% savings (docs, November 2026)'], ['Best for', 'Data residency rules', 'Lowest cost and most capacity'], ['Organization rules (SCP)', 'Must allow every destination Region of the profile', 'Must allow the special Region value `unspecified`']],
          he: [['איפה המידע מעובד', 'בתוך גאוגרפיה אחת (ארה"ב, אירופה, APAC…)', 'כל Region מסחרי נתמך'], ['מחיר', 'מחיר רגיל', 'חיסכון של בערך 10% (תיעוד, נובמבר 2026)'], ['הכי טוב בשביל', 'כללי data residency', 'העלות הנמוכה ביותר והכי הרבה קיבולת'], ['כללי ארגון (SCP)', 'חייבים להרשות כל Region יעד של ה-profile', 'חייבים להרשות את ערך ה-Region המיוחד `unspecified`']] } },
        { t: 'list', en: ['There is no extra charge for the routing. The price is set by the Region you call from.', 'Requests can run in Regions that you never enabled in your account. Data moves on the AWS network, encrypted.', '[[CloudTrail]] logs the call in the Region you called. The field `additionalEventData.inferenceRegion` shows where it really ran.', 'Example from the docs: `us.anthropic.claude-fable-5-2` called from us-east-1 can run in us-east-1, us-east-2 or us-west-2.'], he: ['אין חיוב נוסף על הניתוב. המחיר נקבע לפי ה-Region שקוראים ממנו.', 'בקשות יכולות לרוץ ב-Regions שמעולם לא הפעלת בחשבון. המידע עובר ברשת של AWS, מוצפן.', '[[CloudTrail]] רושם את הקריאה ב-Region שקראת אליו. השדה `additionalEventData.inferenceRegion` מראה איפה היא באמת רצה.', 'דוגמה מהתיעוד: `us.anthropic.claude-fable-5-2` שנקרא מ-us-east-1 יכול לרוץ ב-us-east-1, us-east-2 או us-west-2.'] },
        { t: 'p', en: 'Profiles change your IAM policy. The docs are explicit: when the `Resource` is an inference profile, you must **also** list the foundation model in every Region the profile can route to. A tight policy looks like this:', he: 'Profiles משנים את ה-IAM policy שלך. התיעוד מפורש: כשה-`Resource` הוא inference profile, חייבים לרשום **גם** את ה-foundation model בכל Region שה-profile יכול לנתב אליו. policy הדוקה נראית כך:' },
        { t: 'code', lang: 'json', code: '{\n  "Version": "2012-10-17",\n  "Statement": [\n    {\n      "Effect": "Allow",\n      "Action": ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],\n      "Resource": "arn:aws:bedrock:us-east-1:111122223333:inference-profile/us.anthropic.claude-fable-5-2"\n    },\n    {\n      "Effect": "Allow",\n      "Action": ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],\n      "Resource": [\n        "arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-fable-5-2",\n        "arn:aws:bedrock:us-east-2::foundation-model/anthropic.claude-fable-5-2",\n        "arn:aws:bedrock:us-west-2::foundation-model/anthropic.claude-fable-5-2"\n      ],\n      "Condition": {\n        "StringLike": {\n          "bedrock:InferenceProfileArn": "arn:aws:bedrock:us-east-1:111122223333:inference-profile/us.anthropic.claude-fable-5-2"\n        }\n      }\n    }\n  ]\n}', caption: { en: 'Statement 1 allows the profile. Statement 2 allows the model in each destination Region, and the condition says "only when the call came through this profile".', he: 'Statement 1 מרשה את ה-profile. Statement 2 מרשה את המודל בכל Region יעד, וה-condition אומר "רק כשהקריאה הגיעה דרך ה-profile הזה".' } },
        { t: 'quiz', q: { en: 'A role\'s policy allows `bedrock:InvokeModel` on exactly one resource: the ARN of the inference profile `us.anthropic.claude-sonnet-5-5`. The call fails with AccessDeniedException. What is missing?', he: 'ה-policy של role מרשה `bedrock:InvokeModel` על משאב אחד בדיוק: ה-ARN של ה-inference profile בשם `us.anthropic.claude-sonnet-5-5`. הקריאה נכשלת עם AccessDeniedException. מה חסר?' },
          options: { en: ['The foundation-model ARNs of that model in every Region the profile can route to', 'The action `bedrock:UseInferenceProfile`', 'A Bedrock API key', 'Nothing. Inference profiles cannot be used with roles.'], he: ['ה-ARNs מסוג foundation-model של המודל הזה בכל Region שה-profile יכול לנתב אליו', 'הפעולה `bedrock:UseInferenceProfile`', 'Bedrock API key', 'כלום. אי אפשר להשתמש ב-inference profiles עם roles.'] },
          answer: 0, explain: { en: 'IAM checks two resources on such a call: the profile, and the model in the Region where the request finally runs. Allowing only the profile is the most common cross-Region IAM bug. The action stays `bedrock:InvokeModel`. There is no special action for profiles.', he: 'IAM בודק שני משאבים בקריאה כזו: ה-profile, והמודל ב-Region שבו הבקשה רצה בסוף. להרשות רק את ה-profile הוא באג ה-IAM הכי נפוץ ב-cross-Region. הפעולה נשארת `bedrock:InvokeModel`. אין פעולה מיוחדת ל-profiles.' } },
        { t: 'h3', en: 'Application inference profiles: who spent what', he: 'Application inference profiles: מי הוציא כמה' },
        { t: 'p', en: 'Ten teams call the same model from the same account. The bill shows one line. Which team spent what? An [[Application inference profile]] answers that. You create your own profile as a copy of a model or of a system profile, put tags on it, and each team passes **its** profile ARN as the `modelId`. After the tags are activated as cost allocation tags, the bill splits by them.', he: 'עשרה צוותים קוראים לאותו מודל מאותו חשבון. בחשבונית יש שורה אחת. איזה צוות הוציא כמה? [[Application inference profile]] עונה על זה. יוצרים profile משלך כהעתק של מודל או של system profile, שמים עליו tags, וכל צוות מעביר את ה-ARN של ה-profile **שלו** בתור `modelId`. אחרי שמפעילים את ה-tags כ-cost allocation tags, החשבונית מתפצלת לפיהם.' },
        { t: 'fill', prompt: { en: 'Create an application inference profile for the support team, as a copy of a system profile, and call the model through it.', he: 'צור application inference profile לצוות התמיכה, כהעתק של system profile, וקרא למודל דרכו.' },
          lang: 'python', code: 'bedrock = boto3.client("{{1}}", region_name="us-east-1")\n\narn = bedrock.{{2}}(\n    inferenceProfileName="team-support-sonnet",\n    modelSource={"{{3}}": SYSTEM_PROFILE_ARN},\n    tags=[{"key": "team", "value": "support"}],\n)["inferenceProfileArn"]\n\nruntime = boto3.client("bedrock-runtime", region_name="us-east-1")\nruntime.converse(modelId={{4}}, messages=messages)', blanks: [ { accept: ['bedrock'], hint: { en: 'creating a resource is a control plane call', he: 'יצירת משאב היא קריאת control plane' } }, { accept: ['create_inference_profile'], hint: { en: 'snake_case of CreateInferenceProfile', he: 'snake_case של CreateInferenceProfile' } }, { accept: ['copyFrom'], hint: { en: 'the profile is a copy from a model or a system profile', he: 'ה-profile הוא העתק ממודל או מ-system profile' } }, { accept: ['arn'], hint: { en: 'the variable that holds the new profile ARN', he: 'המשתנה שמחזיק את ה-ARN של ה-profile החדש' } } ],
          explain: { en: 'Control plane to create, data plane to use. The ARN of your profile contains `application-inference-profile/`. Two limits from the docs: it works with InvokeModel and Converse (the OpenAI-compatible APIs reject it), and you cannot see application inference profiles in the Bedrock console, only through the API.', he: 'control plane כדי ליצור, data plane כדי להשתמש. ה-ARN של ה-profile שלך מכיל `application-inference-profile/`. שתי מגבלות מהתיעוד: זה עובד עם InvokeModel ו-Converse (ה-APIs תואמי OpenAI דוחים אותו), ואי אפשר לראות application inference profiles בקונסול של Bedrock, רק דרך ה-API.' } },
        { t: 'h', en: 'Prompt caching', he: 'Prompt caching' },
        { t: 'p', en: 'Many applications send the same long beginning in every request: a big system prompt, tool definitions, a long document that the user asks many questions about. With [[Prompt caching]] the model keeps its processed state for that beginning, and the next request that starts with exactly the same content reuses it. You get a faster answer, and the cached part is billed at a lower "cache read" price.', he: 'הרבה אפליקציות שולחות את אותה התחלה ארוכה בכל בקשה: system prompt גדול, הגדרות כלים, מסמך ארוך שהמשתמש שואל עליו הרבה שאלות. עם [[Prompt caching]] המודל שומר את המצב המעובד של ההתחלה הזו, והבקשה הבאה שמתחילה בדיוק באותו תוכן משתמשת בו שוב. מקבלים תשובה מהירה יותר, והחלק שב-cache מחויב במחיר "cache read" נמוך יותר.' },
        { t: 'code', lang: 'python', code: 'response = client.converse(\n    modelId="us.anthropic.claude-sonnet-5-5",\n    system=[\n        {"text": LONG_SYSTEM_PROMPT},            # long, never changes\n        {"cachePoint": {"type": "default"}},     # cache everything before this\n    ],\n    messages=[{"role": "user", "content": [{"text": question}]}],\n)\nprint(response["usage"])', caption: { en: 'A [[Cache checkpoint]] is one more block. It says: cache the whole prefix up to here.', he: '[[Cache checkpoint]] הוא עוד בלוק אחד. הוא אומר: שמור ב-cache את כל הקידומת עד כאן.' } },
        { t: 'list', en: ['The request is processed in a fixed order: `tools`, then `system`, then `messages`. A checkpoint caches **everything before it**. If anything earlier changes, even one character, the cache does not match.', 'There is a minimum size. Below it the call works but nothing is cached. The minimum depends on the model: 512 tokens for the Claude 5.x models, 1,024 or 4,096 for several older ones.', 'A cache entry lives for a [[TTL]] of 5 minutes, and every hit resets the clock. Claude models can also use a 1-hour TTL (`"ttl": "1h"` inside the `cachePoint`).', 'You can place at most 4 checkpoints in one request.', 'Anthropic models on Bedrock cache only when you ask ("explicit"). Nova text prompts and OpenAI GPT models also cache automatically, on a best-effort basis ("implicit"), so keep the fixed content first.', 'A hit is not guaranteed. The entry lives on the server that processed it, and cross-Region routing can cause extra cache writes.'], he: ['הבקשה מעובדת בסדר קבוע: `tools`, אחר כך `system`, אחר כך `messages`. checkpoint שומר ב-cache את **כל מה שלפניו**. אם משהו מוקדם יותר משתנה, אפילו תו אחד, ה-cache לא מתאים.', 'יש גודל מינימלי. מתחתיו הקריאה עובדת אבל שום דבר לא נשמר. המינימום תלוי במודל: 512 טוקנים למודלי Claude 5.x, ו-1,024 או 4,096 לכמה ישנים יותר.', 'רשומה ב-cache חיה [[TTL]] של 5 דקות, וכל פגיעה מאפסת את השעון. מודלי Claude יכולים להשתמש גם ב-TTL של שעה (`"ttl": "1h"` בתוך ה-`cachePoint`).', 'אפשר לשים לכל היותר 4 checkpoints בבקשה אחת.', 'מודלים של Anthropic ב-Bedrock שומרים ב-cache רק כשמבקשים ("explicit"). פרומפטים של טקסט ב-Nova ומודלי GPT של OpenAI שומרים גם אוטומטית, על בסיס best effort ("implicit"), ולכן שמים את התוכן הקבוע ראשון.', 'פגיעה לא מובטחת. הרשומה חיה על השרת שעיבד אותה, וניתוב cross-Region יכול לגרום לכתיבות cache נוספות.'] },
        { t: 'p', en: 'How do you know that it works? Look at `usage`. With caching there are two more counters, and `inputTokens` now counts **only the part that was not cached**:', he: 'איך יודעים שזה עובד? מסתכלים על `usage`. עם caching יש עוד שני מונים, ו-`inputTokens` סופר עכשיו **רק את החלק שלא היה ב-cache**:' },
        { t: 'code', lang: 'json', code: '// First request: the prefix is written to the cache\n{ "inputTokens": 120, "cacheWriteInputTokens": 20000, "cacheReadInputTokens": 0, "outputTokens": 250 }\n\n// Second request, two minutes later: the prefix is read from the cache\n{ "inputTokens": 135, "cacheWriteInputTokens": 0, "cacheReadInputTokens": 20000, "outputTokens": 240 }', caption: { en: 'Total input = `inputTokens` + `cacheReadInputTokens` + `cacheWriteInputTokens`. Writing to the cache is billed at the cache-write price (which can be higher than normal input), reading at the discounted cache-read price.', he: 'סך הקלט = `inputTokens` + `cacheReadInputTokens` + `cacheWriteInputTokens`. כתיבה ל-cache מחויבת במחיר cache-write (שיכול להיות גבוה מקלט רגיל), קריאה במחיר cache-read המוזל.' } },
        { t: 'quiz', q: { en: 'A response shows `"inputTokens": 135, "cacheReadInputTokens": 20000, "cacheWriteInputTokens": 0`. How many input tokens did the model really receive, and what happened?', he: 'תשובה מראה `"inputTokens": 135, "cacheReadInputTokens": 20000, "cacheWriteInputTokens": 0`. כמה טוקני קלט המודל באמת קיבל, ומה קרה?' },
          options: { en: ['135. The cache removed the rest from the prompt.', '20,000. The 135 are output tokens.', '19,865. Cache reads are subtracted from the input.', '20,135. It was a cache hit: 20,000 tokens were read from the cache and only 135 were processed as new input.'], he: ['135. ה-cache הסיר את השאר מהפרומפט.', '20,000. ה-135 הם טוקני פלט.', '19,865. קריאות cache מופחתות מהקלט.', '20,135. זו הייתה פגיעת cache: 20,000 טוקנים נקראו מה-cache ורק 135 עובדו כקלט חדש.'] },
          answer: 3, explain: { en: 'The model still sees the whole prompt. Caching changes the price and the speed, not the content. With caching on, `inputTokens` alone is misleading: a dashboard that sums only `inputTokens` will show that your prompts suddenly became tiny.', he: 'המודל עדיין רואה את כל הפרומפט. caching משנה את המחיר ואת המהירות, לא את התוכן. כש-caching דולק, `inputTokens` לבדו מטעה: דשבורד שמסכם רק את `inputTokens` יראה שהפרומפטים שלך פתאום נהיו זעירים.' } },
        { t: 'fill', prompt: { en: 'Your agent sends the same 30 tool definitions on every call. Add a cache checkpoint as the last element of the tools list.', he: 'הסוכן שלך שולח את אותן 30 הגדרות כלים בכל קריאה. הוסף cache checkpoint כאלמנט האחרון ברשימת הכלים.' },
          lang: 'python', code: 'tool_config = {\n    "tools": [\n        *TOOL_SPECS,\n        {"{{1}}": {"type": "{{2}}"}},\n    ]\n}', blanks: [ { accept: ['cachePoint'], hint: { en: 'camelCase: the checkpoint block', he: 'camelCase: בלוק ה-checkpoint' } }, { accept: ['default'], hint: { en: 'the only checkpoint type', he: 'סוג ה-checkpoint היחיד' } } ],
          explain: { en: 'The same `{"cachePoint": {"type": "default"}}` block works in three places: at the end of `toolConfig.tools`, inside `system`, and inside the content of a message. Tools come first in the processing order, so tool definitions that never change are the best thing to cache.', he: 'אותו בלוק `{"cachePoint": {"type": "default"}}` עובד בשלושה מקומות: בסוף `toolConfig.tools`, בתוך `system`, ובתוך ה-content של הודעה. כלים באים ראשונים בסדר העיבוד, ולכן הגדרות כלים שלא משתנות אף פעם הן הדבר הכי טוב לשמור ב-cache.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Chat / Text playground', 'Cross-Region inference', 'Batch inference', 'Provisioned Throughput', 'API keys', 'Settings'], active: 'Chat / Text playground', crumbs: ['Amazon Bedrock', 'Chat / Text playground'],
          heading: 'Chat / Text playground',
          panels: [
            { title: 'Configurations', n: 1, fields: [ { label: 'Prompt caching', type: 'toggle', value: true, n: 2 } ] },
            { title: 'Caching metrics', n: 3, text: 'View cache checkpoints' }
          ],
          callouts: [
            { n: 1, en: 'The Configurations menu of the playground holds the settings of the test run.', he: 'תפריט ה-Configurations של ה-playground מחזיק את הגדרות ריצת הבדיקה.' },
            { n: 2, en: 'One switch turns prompt caching on for the chat, so you can try it without writing code.', he: 'מתג אחד מדליק prompt caching לצ׳אט, כך שאפשר לנסות בלי לכתוב קוד.' },
            { n: 3, en: 'After a few messages you can view the cache checkpoints and a pop-up with the caching metrics: how many tokens were written to the cache and how many were read from it.', he: 'אחרי כמה הודעות אפשר לראות את ה-cache checkpoints וחלון קופץ עם מדדי ה-caching: כמה טוקנים נכתבו ל-cache וכמה נקראו ממנו.' }
          ],
          caption: { en: 'The prompt caching controls of a chat playground, simplified. Only this part of the screen is shown.', he: 'פקדי ה-prompt caching של chat playground, בצורה מפושטת. מוצג רק החלק הזה של המסך.' } },
        { t: 'quiz', q: { en: 'You added a cache checkpoint after a 6,000-token system prompt on a Claude 5.x model. After a day, `cacheReadInputTokens` is 0 on every call and `cacheWriteInputTokens` is about 6,000 on every call. The system prompt starts with: "Current time: 2026-11-13 10:42:07". What is wrong?', he: 'הוספת cache checkpoint אחרי system prompt של 6,000 טוקנים במודל Claude 5.x. אחרי יום, `cacheReadInputTokens` הוא 0 בכל קריאה ו-`cacheWriteInputTokens` הוא בערך 6,000 בכל קריאה. ה-system prompt מתחיל ב: "Current time: 2026-11-13 10:42:07". מה לא בסדר?' },
          options: { en: ['The prompt is below the minimum size for caching', 'The timestamp changes on every request, so the prefix is never identical and every call writes a new cache entry', 'Caching works only with InvokeModel', 'The 5-minute TTL is too long'], he: ['הפרומפט מתחת לגודל המינימלי ל-caching', 'חותמת הזמן משתנה בכל בקשה, ולכן הקידומת אף פעם לא זהה וכל קריאה כותבת רשומת cache חדשה', 'Caching עובד רק עם InvokeModel', 'ה-TTL של 5 דקות ארוך מדי'] },
          answer: 1, explain: { en: 'Caching needs an identical prefix. One changing value at the start (a time, a user name, a request ID) breaks everything after it. And it is worse than no caching, because you pay the cache-write price every time. The fix: stable content first, the checkpoint, and only then the things that change.', he: 'Caching צריך קידומת זהה. ערך משתנה אחד בהתחלה (שעה, שם משתמש, מזהה בקשה) שובר את כל מה שאחריו. וזה גרוע יותר מבלי caching, כי משלמים את מחיר ה-cache-write בכל פעם. התיקון: תוכן יציב ראשון, ה-checkpoint, ורק אחר כך הדברים שמשתנים.' } },
        { t: 'note', kind: 'tip', en: 'When does caching save money? When the same long prefix is read **several times within the TTL**. A big prompt that is used once pays the write price and never gets a read. And a bonus that matters under load: for Claude and GPT models, tokens read from the cache are not counted against your rate limit. Caching therefore also raises the traffic you can serve.', he: 'מתי caching חוסך כסף? כשאותה קידומת ארוכה נקראת **כמה פעמים בתוך ה-TTL**. פרומפט גדול שמשתמשים בו פעם אחת משלם את מחיר הכתיבה ולא מקבל אף קריאה. ובונוס שחשוב בעומס: במודלי Claude ו-GPT, טוקנים שנקראו מה-cache לא נספרים מול מגבלת הקצב שלך. לכן caching גם מעלה את התעבורה שאפשר לשרת.' },
        { t: 'h', en: 'Intelligent prompt routing', he: 'Intelligent prompt routing' },
        { t: 'p', en: '[[Intelligent prompt routing]] gives you one endpoint in front of **two models of the same family**. For every request the router predicts whether the cheaper model will answer well enough. If yes, it uses the cheaper one. You pass the router ARN as the `modelId`, and the response tells you which model answered in `trace.promptRouter.invokedModelId`. Know the limits before you propose it: today it supports only some Nova and Llama models (not Claude), it is tuned for English prompts, and it does not learn from your own application data.', he: '[[Intelligent prompt routing]] נותן לך endpoint אחד לפני **שני מודלים מאותה משפחה**. לכל בקשה הנתב חוזה האם המודל הזול יענה מספיק טוב. אם כן, הוא משתמש בזול. מעבירים את ה-ARN של הנתב בתור `modelId`, והתשובה אומרת לך איזה מודל ענה בשדה `trace.promptRouter.invokedModelId`. הכר את המגבלות לפני שאתה מציע את זה: היום הוא תומך רק בחלק ממודלי Nova ו-Llama (לא Claude), הוא מכוון לפרומפטים באנגלית, והוא לא לומד מהמידע של האפליקציה שלך.' },
        { t: 'h', en: 'Quotas: how tokens are really counted', he: 'Quotas: איך טוקנים באמת נספרים' },
        { t: 'p', en: 'On `bedrock-runtime` the main [[Quota]] is [[TPM]], tokens per minute, per model and per Region, with input and output counted together. You find the quotas in the Service Quotas console under the service "Amazon Bedrock". Their names tell you a lot:', he: 'ב-`bedrock-runtime` ה-[[Quota]] העיקרית היא [[TPM]], טוקנים לדקה, לכל מודל ולכל Region, כשקלט ופלט נספרים יחד. את ה-quotas מוצאים בקונסול של Service Quotas תחת השירות "Amazon Bedrock". השמות שלהן מספרים הרבה:' },
        { t: 'table', head: { en: ['Quota name', 'Scope'], he: ['שם ה-quota', 'היקף'] }, rows: {
          en: [['"Cross-Region InvokeModel tokens per minute for {model}"', 'Per model and Region, when you call through a cross-Region profile'], ['"On-demand InvokeModel tokens per minute for {model}"', 'Per model and Region, single-Region on-demand calls'], ['"InvokeModel requests per minute for {model}"', 'Only some models have it (Claude Opus 4.7 and 4.8, for example, have no RPM quota)'], ['"Cross-Model Max Tokens Per Day"', 'One daily total per account and Region, across **all** models. Since September 2026 it replaces the old per-model daily quotas.']],
          he: [['"Cross-Region InvokeModel tokens per minute for {model}"', 'לכל מודל ו-Region, כשקוראים דרך cross-Region profile'], ['"On-demand InvokeModel tokens per minute for {model}"', 'לכל מודל ו-Region, קריאות on-demand ב-Region אחד'], ['"InvokeModel requests per minute for {model}"', 'רק לחלק מהמודלים יש אותה (ל-Claude Opus 4.7 ו-4.8, למשל, אין quota של RPM)'], ['"Cross-Model Max Tokens Per Day"', 'סכום יומי אחד לכל חשבון ו-Region, על פני **כל** המודלים. מאז ספטמבר 2026 היא מחליפה את ה-quotas היומיות הישנות לכל מודל.']] } },
        { t: 'p', en: 'Despite the word "InvokeModel" in the names, these quotas are shared by every API you use against that model on `bedrock-runtime`: InvokeModel, Converse, Responses, Chat Completions. Traffic to `bedrock-mantle` is counted separately, with its own input and output quotas. Going over any quota gives a `ThrottlingException`. Two rules about **how** the tokens are counted surprise almost everyone.', he: 'למרות המילה "InvokeModel" בשמות, ה-quotas האלה משותפות לכל API שמשתמשים בו מול המודל הזה ב-`bedrock-runtime`: InvokeModel, Converse, Responses, Chat Completions. תעבורה ל-`bedrock-mantle` נספרת בנפרד, עם quotas משלה לקלט ולפלט. חריגה מכל quota נותנת `ThrottlingException`. שני כללים על **איך** הטוקנים נספרים מפתיעים כמעט את כולם.' },
        { t: 'list', ordered: true, en: ['**Output tokens weigh more.** For many models each output token is multiplied by a [[Burndown rate]] when it is counted against the quota. For example 5x for many Anthropic models, 10x for Claude Fable 5.2 and Opus 5.5, and 1x for most other models. This is for the quota only. Your bill counts real tokens.', '**`maxTokens` is reserved up front.** When a request starts, the quota is charged with the input tokens plus your whole `maxTokens`. When it ends, the charge is corrected to what was really used: input tokens + cache-write tokens + (output tokens × burndown rate). Tokens read from the cache do not count.'], he: ['**טוקני פלט שוקלים יותר.** בהרבה מודלים כל טוקן פלט מוכפל ב-[[Burndown rate]] כשסופרים אותו מול ה-quota. למשל פי 5 בהרבה מודלים של Anthropic, פי 10 ב-Claude Fable 5.2 וב-Opus 5.5, ופי 1 ברוב המודלים האחרים. זה רק לצורך ה-quota. החשבונית סופרת טוקנים אמיתיים.', '**`maxTokens` נשמר מראש.** כשבקשה מתחילה, ה-quota מחויבת בטוקני הקלט ועוד כל ה-`maxTokens` שלך. כשהיא מסתיימת, החיוב מתוקן למה שבאמת נוצל: טוקני קלט + טוקני cache-write + (טוקני פלט × burndown rate). טוקנים שנקראו מה-cache לא נספרים.'] },
        { t: 'quiz', q: { en: 'A request to a model with a burndown rate of 5x uses 1,000 input tokens and 100 output tokens. How many tokens does it take from the TPM quota, and how many are billed?', he: 'בקשה למודל עם burndown rate של פי 5 משתמשת ב-1,000 טוקני קלט וב-100 טוקני פלט. כמה טוקנים היא לוקחת מה-quota של TPM, וכמה מחויבים?' },
          options: { en: ['1,100 from the quota, 1,100 billed', '5,500 from the quota, 5,500 billed', '1,500 from the quota, 1,100 billed', '1,100 from the quota, 1,500 billed'], he: ['1,100 מה-quota, 1,100 מחויבים', '5,500 מה-quota, 5,500 מחויבים', '1,500 מה-quota, 1,100 מחויבים', '1,100 מה-quota, 1,500 מחויבים'] },
          answer: 2, explain: { en: 'Quota: 1,000 + (100 × 5) = 1,500. Bill: 1,000 input + 100 output = 1,100 real tokens. The burndown rate never touches the bill. It means that applications with long answers reach their TPM limit much sooner than the raw token count suggests.', he: 'Quota: 1,000 + (100 × 5) = 1,500. חשבונית: 1,000 קלט + 100 פלט = 1,100 טוקנים אמיתיים. ה-burndown rate אף פעם לא נוגע בחשבונית. המשמעות היא שאפליקציות עם תשובות ארוכות מגיעות לגבול ה-TPM הרבה יותר מוקדם ממה שספירת הטוקנים הגולמית מרמזת.' } },
        { t: 'quiz', q: { en: 'A developer sets `maxTokens` to 64,000 on every call "to be safe". Real answers are about 300 tokens. With only a few parallel users the app gets ThrottlingException, although the real token usage is far below the TPM quota. Why?', he: 'מפתח קובע `maxTokens` ל-64,000 בכל קריאה "ליתר ביטחון". התשובות האמיתיות הן בערך 300 טוקנים. עם כמה משתמשים במקביל בלבד האפליקציה מקבלת ThrottlingException, למרות שהשימוש האמיתי בטוקנים רחוק מתחת ל-quota של TPM. למה?' },
          options: { en: ['Each request reserves its input tokens plus the whole `maxTokens` when it starts, so a few parallel requests fill the quota until they finish', 'A high `maxTokens` makes the model write 64,000 tokens', 'A high `maxTokens` raises the burndown rate', 'The quota counts characters, not tokens'], he: ['כל בקשה שומרת בתחילתה את טוקני הקלט שלה ועוד כל ה-`maxTokens`, כך שכמה בקשות במקביל ממלאות את ה-quota עד שהן מסתיימות', '`maxTokens` גבוה גורם למודל לכתוב 64,000 טוקנים', '`maxTokens` גבוה מעלה את ה-burndown rate', 'ה-quota סופרת תווים, לא טוקנים'] },
          answer: 0, explain: { en: 'The reservation is corrected when the request ends. But while requests are running, each one holds 64,000 tokens of headroom. The docs say it directly: setting `max_tokens` far too high wastes TPM headroom and lowers concurrency. Set it close to the longest answer you really expect.', he: 'השמירה מתוקנת כשהבקשה מסתיימת. אבל בזמן שהבקשות רצות, כל אחת מחזיקה 64,000 טוקנים של מרווח. התיעוד אומר את זה ישירות: לקבוע `max_tokens` גבוה מדי מבזבז מרווח TPM ומוריד את מספר הבקשות המקבילות. קובעים אותו קרוב לתשובה הארוכה ביותר שבאמת מצפים לה.' } },
        { t: 'note', kind: 'tip', en: 'Asking for more quota: you request an increase on "Cross-Region InvokeModel tokens per minute for {model}", and support then offers to raise the related quotas too. The docs say that priority goes to customers who already use their current quota, so bring real traffic numbers. There are no increases for Legacy models. Default quotas can also differ from account to account. Under load, watch the CloudWatch metric `InvocationThrottles`, and remember that tokens read from the cache do not count toward TPM.', he: 'בקשת quota נוספת: מבקשים העלאה על "Cross-Region InvokeModel tokens per minute for {model}", והתמיכה מציעה אז להעלות גם את ה-quotas הקשורות. התיעוד אומר שעדיפות ניתנת ללקוחות שכבר מנצלים את ה-quota הנוכחית שלהם, אז מביאים מספרי תעבורה אמיתיים. אין העלאות למודלים במצב Legacy. גם ה-quotas ברירת המחדל יכולות להיות שונות מחשבון לחשבון. בעומס, עוקבים אחרי מדד ה-CloudWatch בשם `InvocationThrottles`, וזוכרים שטוקנים שנקראו מה-cache לא נספרים ל-TPM.' },
        { t: 'h3', en: 'One more switch: latency-optimized inference', he: 'עוד מתג אחד: latency-optimized inference' },
        { t: 'p', en: 'Some models have faster-serving variants that you ask for per request with `performanceConfig={"latency": "optimized"}` (the default is `"standard"`). It is still marked as a preview, it is billed at its own (higher) rate, and the list of models is short and old (for example Nova Pro and some Llama 3.1 models, through cross-Region profiles). If its quota runs out, the request falls back to standard and is billed at the standard rate. Good to know, rarely the answer.', he: 'לחלק מהמודלים יש גרסאות הגשה מהירות יותר שמבקשים לכל בקשה עם `performanceConfig={"latency": "optimized"}` (ברירת המחדל היא `"standard"`). זה עדיין מסומן כ-preview, מחויב בתעריף משלו (גבוה יותר), ורשימת המודלים קצרה וישנה (למשל Nova Pro וכמה מודלי Llama 3.1, דרך cross-Region profiles). אם ה-quota שלו נגמרת, הבקשה חוזרת ל-standard ומחויבת בתעריף standard. טוב לדעת, לעיתים רחוקות התשובה.' },
        { t: 'match', prompt: { en: 'Match the situation to the best option.', he: 'התאם את המצב לאפשרות הכי טובה.' }, pairs: [
          { a: { en: 'A new product, traffic unknown', he: 'מוצר חדש, תעבורה לא ידועה' }, b: { en: 'On-demand, Standard tier', he: 'On-demand, Standard tier' } },
          { a: { en: 'Classify 3 million old emails by next week', he: 'לסווג 3 מיליון מיילים ישנים עד שבוע הבא' }, b: { en: 'Batch inference', he: 'Batch inference' } },
          { a: { en: 'Every request starts with the same 15,000-token manual', he: 'כל בקשה מתחילה באותו מדריך של 15,000 טוקנים' }, b: { en: 'Prompt caching', he: 'Prompt caching' } },
          { a: { en: 'EU customer data must stay in the EU', he: 'מידע של לקוחות אירופאים חייב להישאר באירופה' }, b: { en: 'A geographic inference profile', he: 'Geographic inference profile' } },
          { a: { en: 'Finance wants the Bedrock bill split by team', he: 'הכספים רוצים את חשבונית Bedrock מפוצלת לפי צוות' }, b: { en: 'Application inference profiles with tags', he: 'Application inference profiles עם tags' } },
          { a: { en: 'A background agent where a slower answer is fine', he: 'סוכן רקע שבו תשובה איטית יותר בסדר' }, b: { en: 'Flex tier', he: 'Flex tier' } }
        ] },
        { t: 'reveal', q: { en: 'Interview question: "Our Bedrock bill doubled. Where do you look, and what can you do without hurting quality?"', he: 'שאלת ראיון: "חשבונית ה-Bedrock שלנו הוכפלה. איפה אתה מחפש, ומה אפשר לעשות בלי לפגוע באיכות?"' },
          a: { en: 'First I find where the tokens go: usage per model and per feature, from the `usage` numbers we log, from CloudWatch token metrics, or from the bill split by application inference profile tags. Usually one feature dominates, and usually the cost is input tokens: long system prompts, large retrieved contexts, long chat histories. Then, in order of effort. Trim what we send: shorter prompts, fewer retrieved chunks, summarized history. Turn on prompt caching for the stable prefix. Move work that nobody waits for to batch or to the Flex tier. Route simple requests to a smaller model and keep the big one for hard cases, checked against our evaluation set. Use a global inference profile where data rules allow it. Set `maxTokens` close to reality. And I add a budget alert and a per-feature dashboard, so that the next doubling is seen in a day and not in a month.', he: 'קודם מוצאים לאן הטוקנים הולכים: שימוש לכל מודל ולכל יכולת, ממספרי ה-`usage` שאנחנו רושמים, ממדדי הטוקנים ב-CloudWatch, או מהחשבונית המפוצלת לפי tags של application inference profiles. בדרך כלל יכולת אחת שולטת, ובדרך כלל העלות היא טוקני קלט: system prompts ארוכים, הקשרים גדולים שאוחזרו, היסטוריות צ׳אט ארוכות. ואז, לפי סדר המאמץ. מקצצים במה ששולחים: פרומפטים קצרים יותר, פחות chunks מאוחזרים, היסטוריה מסוכמת. מדליקים prompt caching לקידומת היציבה. מעבירים עבודה שאף אחד לא מחכה לה ל-batch או ל-Flex tier. מנתבים בקשות פשוטות למודל קטן יותר ושומרים את הגדול למקרים הקשים, בבדיקה מול סט ה-evaluation שלנו. משתמשים ב-global inference profile איפה שכללי המידע מרשים. קובעים `maxTokens` קרוב למציאות. ומוסיפים התראת תקציב ודשבורד לכל יכולת, כדי שההכפלה הבאה תיראה בתוך יום ולא בתוך חודש.' } }
      ]
    },
    {
      id: 'm03l5', minutes: 14,
      title: { en: 'Customizing models: when, how, and when not', he: 'התאמת מודלים: מתי, איך, ומתי לא' },
      blocks: [
        { t: 'p', en: 'Sooner or later someone in the room says: "Let\'s train our own model." To **customize** a model means to change its weights with your data, so you get a new model of your own. Bedrock can do this in several ways, and this lesson shows them at overview level. But the first professional skill here is knowing when **not** to do it.', he: 'במוקדם או במאוחר מישהו בחדר אומר: "בואו נאמן מודל משלנו." **להתאים** מודל פירושו לשנות את המשקלים שלו עם המידע שלך, כך שמקבלים מודל חדש משלך. Bedrock יודע לעשות את זה בכמה דרכים, והשיעור הזה מראה אותן ברמת סקירה. אבל המיומנות המקצועית הראשונה כאן היא לדעת מתי **לא** לעשות את זה.' },
        { t: 'h', en: 'The ladder: cheap steps first', he: 'הסולם: קודם הצעדים הזולים' },
        { t: 'flow', steps: { en: ['Better prompt: clear instructions and examples', 'RAG: give the model your documents', 'Pick the right model size, tested on your evaluation set', 'Fine-tune or distill', 'Import or host your own model'], he: ['פרומפט טוב יותר: הוראות ברורות ודוגמאות', 'RAG: לתת למודל את המסמכים שלך', 'לבחור את גודל המודל הנכון, בבדיקה על סט ה-evaluation', 'Fine-tuning או distillation', 'לייבא או לארח מודל משלך'] }, caption: { en: 'Each step costs more, takes longer and is harder to undo than the one before. Climb only when the step below has really failed on your evaluation set.', he: 'כל צעד עולה יותר, לוקח יותר זמן וקשה יותר לביטול מהצעד שלפניו. מטפסים רק כשהצעד שמתחת באמת נכשל על סט ה-evaluation שלך.' } },
        { t: 'table', head: { en: ['The problem', 'The usual right tool', 'Why'], he: ['הבעיה', 'הכלי הנכון בדרך כלל', 'למה'] }, rows: {
          en: [['The model does not know our facts, and they change every week', '[[RAG]]', 'Fine-tuning does not reliably teach facts, and a trained model is out of date on the day you deploy it. RAG reads today\'s documents and can show its sources.'], ['Wrong format or tone', 'Prompt, examples, structured output', 'These fix most format problems in hours, not weeks'], ['A big model is good enough but too slow or expensive at high volume', '[[Distillation]]', 'Teach a small model to copy the big one on this one task'], ['A narrow task where checking an answer is easier than writing it', '[[Reinforcement fine-tuning]]', 'A reward function can grade many answers without hand-written labels'], ['Very consistent output on a narrow task, with thousands of good examples', 'Supervised [[Fine-tuning]]', 'The examples are the specification'], ['We already have our own open-weight model', '[[Custom Model Import]]', 'Serve it inside Bedrock next to the other models']],
          he: [['המודל לא מכיר את העובדות שלנו, והן משתנות כל שבוע', '[[RAG]]', 'Fine-tuning לא מלמד עובדות בצורה אמינה, ומודל מאומן מיושן ביום שמעלים אותו. RAG קורא את המסמכים של היום ויכול להראות את המקורות שלו.'], ['פורמט או טון לא נכונים', 'פרומפט, דוגמאות, structured output', 'אלה מתקנים את רוב בעיות הפורמט בשעות, לא בשבועות'], ['מודל גדול מספיק טוב אבל איטי או יקר מדי בנפח גבוה', '[[Distillation]]', 'ללמד מודל קטן להעתיק את הגדול במשימה האחת הזו'], ['משימה צרה שבה לבדוק תשובה קל יותר מלכתוב אותה', '[[Reinforcement fine-tuning]]', 'פונקציית תגמול יכולה לתת ציון להרבה תשובות בלי תוויות שנכתבו ביד'], ['פלט עקבי מאוד במשימה צרה, עם אלפי דוגמאות טובות', '[[Fine-tuning]] מפוקח (supervised)', 'הדוגמאות הן המפרט'], ['כבר יש לנו מודל open-weight משלנו', '[[Custom Model Import]]', 'להגיש אותו בתוך Bedrock ליד המודלים האחרים']] } },
        { t: 'note', kind: 'warn', en: 'The costs people forget. Training is billed per token processed (training tokens × epochs), plus a monthly storage fee for the custom model, plus the cost of serving it. Preparing good data takes the most time. And the hidden one: your custom model is frozen on an old base model. When a better base model comes out (in this field, within months), you have to train again to benefit.', he: 'העלויות שאנשים שוכחים. אימון מחויב לפי טוקן מעובד (טוקני אימון × epochs), ועוד דמי אחסון חודשיים למודל המותאם, ועוד עלות ההגשה שלו. הכנת מידע טוב לוקחת הכי הרבה זמן. והעלות הנסתרת: המודל המותאם שלך קפוא על מודל בסיס ישן. כשיוצא מודל בסיס טוב יותר (בתחום הזה, תוך חודשים), צריך לאמן מחדש כדי ליהנות ממנו.' },
        { t: 'quiz', q: { en: 'A product manager wants to fine-tune a model on the company price list, because the support bot gives old prices. Prices change every week. What do you propose?', he: 'מנהל מוצר רוצה לעשות fine-tuning למודל על מחירון החברה, כי בוט התמיכה נותן מחירים ישנים. המחירים משתנים כל שבוע. מה תציע?' },
          options: { en: ['Fine-tune every week with the new price list', 'Use RAG: retrieve the current prices at question time and tell the model to answer only from them', 'Distill a larger model that knows more prices', 'Raise the temperature so the model guesses less'], he: ['לעשות fine-tuning כל שבוע עם המחירון החדש', 'להשתמש ב-RAG: לאחזר את המחירים העדכניים בזמן השאלה ולהורות למודל לענות רק מתוכם', 'לעשות distillation ממודל גדול יותר שמכיר יותר מחירים', 'להעלות את ה-temperature כדי שהמודל ינחש פחות'] },
          answer: 1, explain: { en: 'Facts that change belong in retrieval, not in weights. A weekly fine-tune costs training every week, is still out of date between runs, and can still mix old and new prices. No base model knows your prices, so distillation does not help. Temperature has nothing to do with knowledge.', he: 'עובדות שמשתנות שייכות לאחזור, לא למשקלים. fine-tuning שבועי עולה אימון כל שבוע, עדיין מיושן בין הרצות, ועדיין יכול לערבב מחירים ישנים וחדשים. אף מודל בסיס לא מכיר את המחירים שלך, אז distillation לא עוזר. ל-temperature אין קשר לידע.' } },
        { t: 'h', en: 'Three ways to customize', he: 'שלוש דרכים להתאים' },
        { t: 'p', en: 'The Bedrock docs list three customization methods today. They differ in what **you** must bring.', he: 'התיעוד של Bedrock מפרט היום שלוש שיטות התאמה. הן נבדלות במה ש**אתה** צריך להביא.' },
        { t: 'table', head: { en: ['Method', 'You bring', 'What happens'], he: ['שיטה', 'אתה מביא', 'מה קורה'] }, rows: {
          en: [['Supervised fine-tuning', 'Labeled examples: prompts with the answers you want', 'The model is trained to produce answers like yours'], ['Reinforcement fine-tuning (RFT)', 'Prompts, plus a reward function: a Lambda grader or a model-as-a-judge', 'The model writes several answers per prompt, the reward function scores them, and training (a method called GRPO) pushes it toward the higher-scoring answers'], ['Distillation', 'Prompts, a big "teacher" model and a small "student" model', 'Bedrock asks the teacher for answers (it can also synthesize more data, up to 15,000 prompt-response pairs) and fine-tunes the student on them']],
          he: [['Supervised fine-tuning', 'דוגמאות מתויגות: פרומפטים עם התשובות שאתה רוצה', 'המודל מאומן לייצר תשובות כמו שלך'], ['Reinforcement fine-tuning (RFT)', 'פרומפטים, ועוד פונקציית תגמול: Lambda שנותנת ציון או model-as-a-judge', 'המודל כותב כמה תשובות לכל פרומפט, פונקציית התגמול נותנת להן ציון, והאימון (שיטה בשם GRPO) דוחף אותו לכיוון התשובות עם הציון הגבוה'], ['Distillation', 'פרומפטים, מודל "מורה" גדול ומודל "תלמיד" קטן', 'Bedrock מבקש מהמורה תשובות (הוא יכול גם לייצר עוד מידע, עד 15,000 זוגות של פרומפט ותשובה) ועושה fine-tuning לתלמיד עליהן']] } },
        { t: 'p', en: 'Which models can you customize? The list is short, and it is mostly smaller and older models. For supervised fine-tuning it includes Nova 2 Lite, Nova Lite, Micro and Pro, several Llama 3.x models and Claude 3 Haiku. For RFT: Nova 2 Lite (us-east-1), and gpt-oss-20B and Qwen3 32B (us-west-2). Open-weight models can also be fine-tuned through the OpenAI-compatible files and fine-tuning-jobs APIs. The newest frontier models, such as Claude 5.x, are not on the list. That alone answers many "let\'s fine-tune" discussions: the model you would fine-tune is weaker than the one you already use with a good prompt.', he: 'אילו מודלים אפשר להתאים? הרשימה קצרה, ורובה מודלים קטנים וישנים יותר. ל-supervised fine-tuning היא כוללת את Nova 2 Lite, את Nova Lite, Micro ו-Pro, כמה מודלי Llama 3.x ואת Claude 3 Haiku. ל-RFT: Nova 2 Lite (us-east-1), ו-gpt-oss-20B ו-Qwen3 32B (us-west-2). אפשר גם לעשות fine-tuning למודלי open-weight דרך ה-APIs התואמי-OpenAI של files ו-fine-tuning jobs. מודלי החזית החדשים ביותר, כמו Claude 5.x, לא ברשימה. זה לבד עונה על הרבה דיונים של "בואו נעשה fine-tuning": המודל שהיית מאמן חלש יותר מזה שאתה כבר משתמש בו עם פרומפט טוב.' },
        { t: 'match', prompt: { en: 'Match the method to what it needs from you.', he: 'התאם את השיטה למה שהיא צריכה ממך.' }, pairs: [
          { a: 'Supervised fine-tuning', b: { en: 'Prompts with the exact answers you want', he: 'פרומפטים עם התשובות המדויקות שאתה רוצה' } },
          { a: 'Reinforcement fine-tuning', b: { en: 'A way to score answers: a Lambda grader or a judge model', he: 'דרך לתת ציון לתשובות: Lambda שנותנת ציון או מודל שופט' } },
          { a: 'Distillation', b: { en: 'Prompts, a teacher model and a student model', he: 'פרומפטים, מודל מורה ומודל תלמיד' } },
          { a: 'Custom Model Import', b: { en: 'Your own model weights in Hugging Face format', he: 'משקלי מודל משלך בפורמט Hugging Face' } },
          { a: 'RAG', b: { en: 'Documents to search at question time, no training', he: 'מסמכים לחיפוש בזמן השאלה, בלי אימון' } }
        ] },
        { t: 'h', en: 'Distillation: the most practical one', he: 'Distillation: השיטה הכי מעשית' },
        { t: 'p', en: 'Here is a common story. You launched with a big model, quality is good, and now the volume is high and the bill hurts. [[Distillation]] lets a small, cheap model learn this one task from the big one. You choose a teacher and a student and give prompts as a `.jsonl` file in S3. Bedrock gets the teacher\'s answers and fine-tunes the student. You can add some labeled pairs of your own as "golden" examples.', he: 'הנה סיפור נפוץ. השקתם עם מודל גדול, האיכות טובה, ועכשיו הנפח גבוה והחשבונית כואבת. [[Distillation]] מאפשר למודל קטן וזול ללמוד את המשימה האחת הזו מהגדול. בוחרים מורה ותלמיד ונותנים פרומפטים כקובץ `.jsonl` ב-S3. Bedrock מקבל את התשובות של המורה ועושה fine-tuning לתלמיד. אפשר להוסיף כמה זוגות מתויגים משלך כדוגמאות "זהב".' },
        { t: 'p', en: 'There is a smart second data source: your own production traffic. If [[Model invocation logging]] is on, the logs in S3 hold real prompts, and you can filter them by the `requestMetadata` labels you set on each call (lesson 2). You can use only the prompts (the teacher answers them again), or the prompt-response pairs (then the teacher in the job must be the same model that wrote those answers). The teacher\'s calls are billed at normal on-demand prices.', he: 'יש מקור מידע שני וחכם: התעבורה שלך ב-production. אם [[Model invocation logging]] דולק, הלוגים ב-S3 מחזיקים פרומפטים אמיתיים, ואפשר לסנן אותם לפי תוויות ה-`requestMetadata` שקבעת בכל קריאה (שיעור 2). אפשר להשתמש רק בפרומפטים (המורה עונה עליהם שוב), או בזוגות פרומפט-תשובה (ואז המורה בעבודה חייב להיות אותו מודל שכתב את התשובות האלה). הקריאות של המורה מחויבות במחירי on-demand רגילים.' },
        { t: 'quiz', q: { en: 'You plan to distill your "ticket summary" feature next quarter, using real production prompts. What should you set up **today**?', he: 'אתה מתכנן לעשות distillation ליכולת "סיכום טיקט" ברבעון הבא, עם פרומפטים אמיתיים מ-production. מה צריך להגדיר **היום**?' },
          options: { en: ['A Provisioned Throughput purchase for the student model', 'A higher TPM quota for the teacher', 'Model invocation logging to S3, and a `requestMetadata` label such as `feature=ticket-summary` on every call of that feature', 'Nothing. Bedrock keeps all prompts for 90 days anyway.'], he: ['רכישת Provisioned Throughput למודל התלמיד', 'quota גבוהה יותר של TPM למורה', 'Model invocation logging ל-S3, ותווית `requestMetadata` כמו `feature=ticket-summary` בכל קריאה של היכולת הזו', 'כלום. Bedrock שומר ממילא את כל הפרומפטים 90 יום.'] },
          answer: 2, explain: { en: 'Invocation logging is off by default, and logs are not created backwards. Without the label you cannot separate this feature\'s prompts from the rest. Bedrock does not keep your prompts for you to reuse. Serving the student is a decision for after the evaluation, not before.', he: 'Invocation logging כבוי כברירת מחדל, ולוגים לא נוצרים לאחור. בלי התווית אי אפשר להפריד את הפרומפטים של היכולת הזו משאר הפרומפטים. Bedrock לא שומר את הפרומפטים שלך כדי שתשתמש בהם שוב. הגשת התלמיד היא החלטה לאחרי ה-evaluation, לא לפני.' } },
        { t: 'note', kind: 'tip', en: 'For RFT, the docs advise starting small: 100 to 200 examples. The hard part is not the data, it is a reward function that really measures what "good" means. If you cannot write that grader, you are not ready for RFT.', he: 'ל-RFT, התיעוד ממליץ להתחיל בקטן: 100 עד 200 דוגמאות. החלק הקשה הוא לא המידע, אלא פונקציית תגמול שבאמת מודדת מה זה "טוב". אם אתה לא יכול לכתוב את הבודק הזה, אתה לא מוכן ל-RFT.' },
        { t: 'h', en: 'Running the job and serving the result', he: 'הרצת העבודה והגשת התוצאה' },
        { t: 'p', en: 'A customization job is a control plane call on the `bedrock` client (`create_model_customization_job`). Its exact options differ per method, so check the docs for them. The job runs for a while. Instead of polling, you can react to the EventBridge event "Model Customization Job State Change". At the end you have a custom model, and now you must decide how to serve it. There are two ways:', he: 'עבודת התאמה היא קריאת control plane ב-client בשם `bedrock` (`create_model_customization_job`). האפשרויות המדויקות שלה שונות לכל שיטה, אז בדוק אותן בתיעוד. העבודה רצה זמן מה. במקום לבדוק שוב ושוב, אפשר להגיב לאירוע ה-EventBridge בשם "Model Customization Job State Change". בסוף יש לך מודל מותאם, ועכשיו צריך להחליט איך להגיש אותו. יש שתי דרכים:' },
        { t: 'table', head: { en: ['', 'Provisioned Throughput', 'Custom model on-demand deployment'], he: ['', 'Provisioned Throughput', 'Custom model on-demand deployment'] }, rows: {
          en: [['You pay', 'Per hour per model unit, from purchase until you delete it', 'Per token, like a normal model'], ['Fits', 'Steady, high traffic', 'Spiky or low traffic, tests, internal tools'], ['Limits', 'Only models on the PT list', 'us-east-1 and us-west-2. Base models: Nova Lite, Nova 2 Lite, Nova Micro, Nova Pro, Llama 3.3 70B. The model must be customized on or after 2025-07-16.'], ['What you pass as `modelId`', 'The provisioned model ARN', 'The deployment ARN']],
          he: [['משלמים', 'לפי שעה לכל model unit, מהרכישה ועד שמוחקים', 'לפי טוקן, כמו מודל רגיל'], ['מתאים ל', 'תעבורה יציבה וגבוהה', 'תעבורה קופצנית או נמוכה, בדיקות, כלים פנימיים'], ['מגבלות', 'רק מודלים ברשימת ה-PT', 'us-east-1 ו-us-west-2. מודלי בסיס: Nova Lite, Nova 2 Lite, Nova Micro, Nova Pro, Llama 3.3 70B. המודל חייב להיות מותאם ב-2025-07-16 או אחרי.'], ['מה מעבירים בתור `modelId`', 'ה-ARN של ה-provisioned model', 'ה-ARN של ה-deployment']] } },
        { t: 'code', lang: 'python', code: 'import boto3\n\nbedrock = boto3.client("bedrock", region_name="us-east-1")\nresp = bedrock.create_custom_model_deployment(\n    modelDeploymentName="ticket-labeler-prod",\n    modelArn=CUSTOM_MODEL_ARN,\n    description="Fine-tuned Nova Lite that labels support tickets",\n)\ndeployment_arn = resp["customModelDeploymentArn"]\n\n# Later, when the deployment status is Active:\nruntime = boto3.client("bedrock-runtime", region_name="us-east-1")\nresponse = runtime.converse(\n    modelId=deployment_arn,\n    messages=[{"role": "user", "content": [{"text": ticket_text}]}],\n)', caption: { en: 'Deploy a custom model for on-demand use, then call it with Converse like any other model. Only the `modelId` is different.', he: 'פריסת מודל מותאם לשימוש on-demand, ואז קריאה אליו עם Converse כמו לכל מודל אחר. רק ה-`modelId` שונה.' } },
        { t: 'fill', prompt: { en: 'Create an on-demand deployment for your custom model and use it in a Converse call.', he: 'צור on-demand deployment למודל המותאם שלך והשתמש בו בקריאת Converse.' },
          lang: 'python', code: 'resp = bedrock.{{1}}(\n    modelDeploymentName="ticket-labeler-prod",\n    modelArn=CUSTOM_MODEL_ARN,\n)\narn = resp["{{2}}"]\n\nruntime.converse({{3}}=arn, messages=messages)', blanks: [ { accept: ['create_custom_model_deployment'], hint: { en: 'snake_case: create + custom model deployment', he: 'snake_case: create + custom model deployment' } }, { accept: ['customModelDeploymentArn'], hint: { en: 'camelCase: the ARN of the new deployment', he: 'camelCase: ה-ARN של ה-deployment החדש' } }, { accept: ['modelId'], hint: { en: 'the same parameter you always use for the model', he: 'אותו פרמטר שתמיד משתמשים בו למודל' } } ],
          explain: { en: 'The pattern is the same everywhere in Bedrock: create a resource with the control plane, get an ARN, pass that ARN as `modelId` to the data plane. A provisioned model, an inference profile, a prompt router and a custom deployment all work this way.', he: 'הדפוס זהה בכל מקום ב-Bedrock: יוצרים משאב עם ה-control plane, מקבלים ARN, מעבירים את ה-ARN הזה בתור `modelId` ל-data plane. provisioned model, inference profile, prompt router ו-custom deployment כולם עובדים כך.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['#Tune', 'Custom models', 'Imported models', '#Infer', 'Cross-Region inference', 'Batch inference', 'Provisioned Throughput', 'Custom model on-demand'], active: 'Custom models', crumbs: ['Amazon Bedrock', 'Custom models', 'Deploy for on-demand'],
          task: { en: 'Your fine-tuned model `ticket-labeler-nova-lite` passed its evaluation. Deploy it for on-demand use. Name the deployment `ticket-labeler-prod`, write a short description that mentions tickets, and create it.', he: 'המודל שעשית לו fine-tuning, `ticket-labeler-nova-lite`, עבר את ה-evaluation שלו. פרוס אותו לשימוש on-demand. תן ל-deployment את השם `ticket-labeler-prod`, כתוב תיאור קצר שמזכיר tickets, וצור אותו.' },
          heading: 'Deploy for on-demand',
          panels: [
            { title: 'Deployment details', n: 1, desc: 'Model: ticket-labeler-nova-lite', fields: [
              { label: 'Deployment Name', type: 'input', value: '', placeholder: 'my-deployment', n: 2, expect: 'ticket-labeler-prod', hint: { en: 'Use exactly the name from the task: ticket-labeler-prod', he: 'השתמש בדיוק בשם מהמשימה: ticket-labeler-prod' } },
              { label: 'Description', type: 'input', value: '', placeholder: 'Optional', expect: '/ticket/i', hint: { en: 'Any short text with the word "ticket", for example "Labels support tickets"', he: 'כל טקסט קצר עם המילה "ticket", למשל "Labels support tickets"' } },
              { label: 'Tags', type: 'text', value: 'team = support', n: 3 } ] }
          ],
          buttons: ['Cancel', 'Create'],
          callouts: [
            { n: 1, en: 'You reach this page from Custom models > Models tab > select the model > Set up inference > Deploy for on-demand.', he: 'מגיעים לדף הזה מ-Custom models > הלשונית Models > בחירת המודל > Set up inference > Deploy for on-demand.' },
            { n: 2, en: 'The deployment name is how you will find it later. When its status is Active, you copy its ARN and use it as `modelId`.', he: 'שם ה-deployment הוא הדרך שבה תמצא אותו אחר כך. כשהסטטוס שלו Active, מעתיקים את ה-ARN שלו ומשתמשים בו בתור `modelId`.' },
            { n: 3, en: 'Tags help to split the cost by team, as with application inference profiles.', he: 'Tags עוזרים לפצל את העלות לפי צוות, כמו ב-application inference profiles.' }
          ],
          success: { en: 'The deployment is being created. You pay per token, with no hourly charge. When the status is Active, call it with Converse using the deployment ARN.', he: 'ה-deployment נוצר. משלמים לפי טוקן, בלי חיוב שעתי. כשהסטטוס Active, קוראים לו עם Converse בעזרת ה-ARN של ה-deployment.' },
          caption: { en: 'The on-demand deployment form for a custom model, simplified. The labels follow the docs; the real page may show more.', he: 'טופס ה-on-demand deployment למודל מותאם, בצורה מפושטת. התוויות לפי התיעוד; הדף האמיתי עשוי להראות יותר.' } },
        { t: 'h', en: 'Custom Model Import: bring your own weights', he: 'Custom Model Import: להביא משקלים משלך' },
        { t: 'p', en: 'With [[Custom Model Import]] you bring an open-weight model that you trained somewhere else (for example in SageMaker AI) and serve it in Bedrock, with the same IAM, logging and APIs as the other models. The facts that decide whether it fits:', he: 'עם [[Custom Model Import]] מביאים מודל open-weight שאימנת במקום אחר (למשל ב-SageMaker AI) ומגישים אותו ב-Bedrock, עם אותם IAM, לוגים ו-APIs כמו המודלים האחרים. העובדות שמכריעות אם זה מתאים:' },
        { t: 'list', en: ['Format: Hugging Face files (`.safetensors` weights, `config.json`, tokenizer files), from S3 or from SageMaker AI.', 'Supported architectures include Llama (2, 3, 3.1, 3.2, 3.3), Mistral, Mixtral, Qwen (2, 2.5, 3 and the VL variants), GPTBigCode, Flan T5, and GPT-OSS 20B and 120B (us-east-1 only). No embedding models.', 'Limits: weights under 200 GB for text models (100 GB for multimodal), context under 128K tokens.', 'Regions: us-east-1, us-east-2, us-west-2, eu-central-1.', 'You call it with InvokeModel (or the streaming version) and the imported model ARN. Converse is not supported for every architecture (not for Qwen3, for example). No batch inference.'], he: ['פורמט: קבצי Hugging Face (משקלי `.safetensors`, `config.json`, קבצי tokenizer), מ-S3 או מ-SageMaker AI.', 'הארכיטקטורות הנתמכות כוללות Llama ‏(2, 3, 3.1, 3.2, 3.3), Mistral, Mixtral, Qwen ‏(2, 2.5, 3 וגרסאות ה-VL), GPTBigCode, Flan T5, ו-GPT-OSS 20B ו-120B (רק ב-us-east-1). אין מודלי embedding.', 'מגבלות: משקלים מתחת ל-200 GB למודלי טקסט (100 GB למולטימודליים), context מתחת ל-128K טוקנים.', 'Regions: us-east-1, us-east-2, us-west-2, eu-central-1.', 'קוראים לו עם InvokeModel (או גרסת ה-streaming) וה-ARN של המודל המיובא. Converse לא נתמך בכל ארכיטקטורה (למשל לא ב-Qwen3). אין batch inference.'] },
        { t: 'p', en: 'The price model is different from everything else in this module. You do not pay per token. You pay for hardware time, in **Custom Model Units** (CMU): one CMU is a slice of the hardware, and a model copy needs a fixed number of them. Billing is per CMU per minute, in 5-minute windows, from the first successful call. When traffic grows, Bedrock adds model copies. The formula: **copies × CMUs per copy × price per CMU-minute × minutes**.', he: 'מודל המחיר שונה מכל השאר במודול הזה. לא משלמים לפי טוקן. משלמים על זמן חומרה, ב-**Custom Model Units** ‏(CMU): CMU אחד הוא פרוסה של החומרה, ועותק של מודל צריך מספר קבוע מהן. החיוב הוא לכל CMU לדקה, בחלונות של 5 דקות, מהקריאה המוצלחת הראשונה. כשהתעבורה גדלה, Bedrock מוסיף עותקים של המודל. הנוסחה: **עותקים × CMUs לעותק × מחיר לדקת CMU × דקות**.' },
        { t: 'quiz', q: { en: 'Your imported model gets a short burst of traffic every hour, and Bedrock scales it from 1 to 3 copies during the burst. What mostly drives the bill?', he: 'המודל המיובא שלך מקבל פרץ תעבורה קצר כל שעה, ו-Bedrock מגדיל אותו מעותק אחד ל-3 עותקים בזמן הפרץ. מה בעיקר קובע את החשבונית?' },
          options: { en: ['The number of input and output tokens', 'The number of requests', 'The size of the S3 bucket with the weights', 'How many model copies are active, times the CMUs per copy, times the minutes they run'], he: ['מספר טוקני הקלט והפלט', 'מספר הבקשות', 'הגודל של ה-S3 bucket עם המשקלים', 'כמה עותקים של המודל פעילים, כפול ה-CMUs לעותק, כפול הדקות שהם רצים'] },
          answer: 3, explain: { en: 'Imported models are billed for hardware time, not tokens. More copies for longer means a higher bill, even if each request is small. You can read the CMUs per copy of your model with `GetImportedModel` (`customModelUnitsPerModelCopy`).', he: 'מודלים מיובאים מחויבים על זמן חומרה, לא על טוקנים. יותר עותקים לזמן ארוך יותר פירושו חשבונית גבוהה יותר, גם אם כל בקשה קטנה. את מספר ה-CMUs לעותק של המודל שלך אפשר לקרוא עם `GetImportedModel` ‏(`customModelUnitsPerModelCopy`).' } },
        { t: 'note', kind: 'jargon', en: 'One more door to know: **Bedrock Marketplace**. It is a catalog of 100+ extra models. You subscribe to one and deploy it to an endpoint that SageMaker AI manages. You pay for the instance (plus any model fee), and you call it through InvokeModel or Converse with the endpoint ARN as `modelId`. It is not serverless like the main catalog: you pay while the endpoint runs.', he: 'עוד דלת שכדאי להכיר: **Bedrock Marketplace**. זה קטלוג של יותר מ-100 מודלים נוספים. נרשמים לאחד ופורסים אותו ל-endpoint ש-SageMaker AI מנהל. משלמים על ה-instance (ועוד דמי מודל אם יש), וקוראים לו דרך InvokeModel או Converse עם ה-ARN של ה-endpoint בתור `modelId`. זה לא serverless כמו הקטלוג הראשי: משלמים כל עוד ה-endpoint רץ.' },
        { t: 'order', prompt: { en: 'Put a professional customization project in order.', he: 'סדר פרויקט התאמה מקצועי.' }, items: { en: ['Write an evaluation set from real inputs, with expected answers', 'Try a better prompt, examples and RAG, and measure', 'Try a smaller or larger base model on the same set', 'Only if the gap remains: fine-tune or distill', 'Compare the custom model to the best prompt-only setup on the same set', 'Deploy it (on-demand or provisioned) and keep monitoring quality and cost'], he: ['לכתוב סט evaluation מקלטים אמיתיים, עם תשובות צפויות', 'לנסות פרומפט טוב יותר, דוגמאות ו-RAG, ולמדוד', 'לנסות מודל בסיס קטן או גדול יותר על אותו סט', 'רק אם הפער נשאר: fine-tuning או distillation', 'להשוות את המודל המותאם למערך הכי טוב של פרומפט בלבד על אותו סט', 'לפרוס אותו (on-demand או provisioned) ולהמשיך לנטר איכות ועלות'] },
          explain: { en: 'The evaluation set comes first and is used at every step. Without it you cannot prove that the expensive step was worth it, and you cannot tell when the next base model makes your custom model unnecessary.', he: 'סט ה-evaluation בא ראשון ומשמש בכל שלב. בלעדיו אי אפשר להוכיח שהצעד היקר היה שווה את זה, ואי אפשר לדעת מתי מודל הבסיס הבא הופך את המודל המותאם שלך למיותר.' } },
        { t: 'reveal', q: { en: 'Interview question: "When would you fine-tune instead of using RAG or prompting?"', he: 'שאלת ראיון: "מתי היית עושה fine-tuning במקום RAG או פרומפטים?"' },
          a: { en: 'Rarely, and only with evidence. If the problem is missing or changing knowledge, I use RAG: it is fresh, cheap to update and can cite sources. If the problem is format or tone, a better prompt, examples and structured output usually fix it. I consider customization when I have a narrow, stable task with lots of traffic, an evaluation set, and a clear gap that prompting did not close. Typical cases: distilling a big model into a small one to cut cost and latency, or RFT when I can write a grader. I also check that the base model is customizable at all, which rules out most of the newest frontier models, and I count the full cost: training, storage, serving, and training again when a better base model appears.', he: 'לעיתים רחוקות, ורק עם ראיות. אם הבעיה היא ידע חסר או משתנה, אני משתמש ב-RAG: הוא עדכני, זול לעדכון ויכול לצטט מקורות. אם הבעיה היא פורמט או טון, פרומפט טוב יותר, דוגמאות ו-structured output בדרך כלל מתקנים אותה. אני שוקל התאמה כשיש לי משימה צרה ויציבה עם הרבה תעבורה, סט evaluation, ופער ברור שהפרומפטים לא סגרו. מקרים טיפוסיים: distillation של מודל גדול לקטן כדי לחתוך עלות ו-latency, או RFT כשאני יכול לכתוב בודק. אני גם בודק שבכלל אפשר להתאים את מודל הבסיס, מה שמוציא את רוב מודלי החזית החדשים, וסופר את כל העלות: אימון, אחסון, הגשה, ואימון מחדש כשמופיע מודל בסיס טוב יותר.' } }
      ]
    },
    {
      id: 'm03l6', minutes: 15,
      title: { en: 'Jargon and scenarios workout', he: 'אימון ז׳רגון ותרחישים' },
      blocks: [
        { t: 'p', en: 'This lesson has no new theory. It mixes everything from the module into the kind of questions that come up in design reviews, on-call shifts and interviews. Answer before you look.', he: 'בשיעור הזה אין תיאוריה חדשה. הוא מערבב את כל מה שבמודול לסוג השאלות שעולות בסקירות תכנון, במשמרות on-call ובראיונות. ענה לפני שאתה מסתכל.' },
        { t: 'match', prompt: { en: 'Match the term to its plain meaning.', he: 'התאם את המונח למשמעות הפשוטה שלו.' }, pairs: [
          { a: 'Inference profile', b: { en: 'A model plus the Regions where a request may run', he: 'מודל ועוד ה-Regions שבהם בקשה יכולה לרוץ' } },
          { a: 'Model card', b: { en: 'The docs page with a model\'s IDs, limits and features', he: 'דף התיעוד עם המזהים, המגבלות והיכולות של מודל' } },
          { a: 'Burndown rate', b: { en: 'How much each output token weighs against the quota', he: 'כמה כל טוקן פלט שוקל מול ה-quota' } },
          { a: 'Service tier', b: { en: 'The priority and price class of one request', he: 'מחלקת העדיפות והמחיר של בקשה אחת' } },
          { a: 'Cache checkpoint', b: { en: '"Cache everything before this point"', he: '"שמור ב-cache את כל מה שלפני הנקודה הזו"' } },
          { a: 'Application inference profile', b: { en: 'Your own tagged profile, to split cost by team', he: 'profile משלך עם tags, לפיצול עלות לפי צוות' } }
        ] },
        { t: 'match', prompt: { en: 'Match the job to the boto3 client or endpoint.', he: 'התאם את הפעולה ל-client של boto3 או ל-endpoint.' }, pairs: [
          { a: { en: 'List models and inference profiles', he: 'להציג מודלים ו-inference profiles' }, b: '`bedrock`' },
          { a: { en: 'Call `converse` or `count_tokens`', he: 'לקרוא ל-`converse` או ל-`count_tokens`' }, b: '`bedrock-runtime`' },
          { a: { en: 'Retrieve from a knowledge base at run time', he: 'לאחזר מ-knowledge base בזמן ריצה' }, b: '`bedrock-agent-runtime`' },
          { a: { en: 'Responses API with background runs and web search', he: 'Responses API עם הרצות ברקע וחיפוש ברשת' }, b: '`bedrock-mantle`' }
        ] },
        { t: 'quiz', q: { en: 'A bank in Frankfurt must keep customer data inside the EU. A developer used a `global.` profile "because it is 10% cheaper". What is the problem?', he: 'בנק בפרנקפורט חייב לשמור מידע של לקוחות בתוך האיחוד האירופי. מפתח השתמש ב-profile מסוג `global.` "כי הוא זול ב-10%". מה הבעיה?' },
          options: { en: ['A global profile may process the request in any supported commercial Region, so the data can leave the EU. Use an EU geographic profile.', 'Global profiles do not work from Frankfurt', 'Global profiles cost more, not less', 'Nothing. Data never leaves the Region you call.'], he: ['global profile עשוי לעבד את הבקשה בכל Region מסחרי נתמך, כך שהמידע יכול לצאת מהאיחוד. משתמשים ב-geographic profile של אירופה.', 'global profiles לא עובדים מפרנקפורט', 'global profiles עולים יותר, לא פחות', 'כלום. המידע אף פעם לא יוצא מה-Region שקוראים אליו.'] },
          answer: 0, explain: { en: 'Geographic profiles keep processing inside one geography and exist exactly for data residency rules. Global profiles trade that for lower cost and more capacity. The saving is real, but it is not the developer\'s decision when a legal rule exists. Check the exact profile ID for your geography in the docs.', he: 'Geographic profiles משאירים את העיבוד בתוך גאוגרפיה אחת וקיימים בדיוק בשביל כללי data residency. Global profiles מוותרים על זה תמורת עלות נמוכה יותר ויותר קיבולת. החיסכון אמיתי, אבל זו לא החלטה של המפתח כשיש כלל משפטי. בדוק בתיעוד את ה-profile ID המדויק לגאוגרפיה שלך.' } },
        { t: 'quiz', q: { en: 'Your organization has an SCP that denies every Region except us-east-1 and us-west-2. Calls through a `global.` profile fail, calls through the `us.` profile work. What must the SCP allow for the global profile?', he: 'בארגון שלך יש SCP שאוסר כל Region חוץ מ-us-east-1 ו-us-west-2. קריאות דרך profile מסוג `global.` נכשלות, קריאות דרך ה-profile מסוג `us.` עובדות. מה ה-SCP חייב להרשות בשביל ה-global profile?' },
          options: { en: ['The action `bedrock:UseGlobalProfile`', 'Every commercial Region, one by one', 'The special value `"aws:RequestedRegion": "unspecified"` (or an exception for the profile ARN)', 'Nothing. SCPs do not apply to Bedrock.'], he: ['הפעולה `bedrock:UseGlobalProfile`', 'כל Region מסחרי, אחד אחרי השני', 'הערך המיוחד `"aws:RequestedRegion": "unspecified"` (או חריגה ל-ARN של ה-profile)', 'כלום. SCPs לא חלים על Bedrock.'] },
          answer: 2, explain: { en: 'For a global profile the destination Region is not a normal Region name, so Region-deny SCPs see `unspecified`. Geographic profiles need the opposite fix: allow all of their destination Regions. And a company that wants to forbid global routing does exactly this in reverse: a Deny with `aws:RequestedRegion = unspecified`.', he: 'ב-global profile ה-Region היעד הוא לא שם Region רגיל, ולכן SCPs שאוסרים Regions רואים `unspecified`. Geographic profiles צריכים את התיקון ההפוך: להרשות את כל ה-Regions היעד שלהם. וחברה שרוצה לאסור ניתוב גלובלי עושה בדיוק את זה הפוך: Deny עם `aws:RequestedRegion = unspecified`.' } },
        { t: 'quiz', q: { en: 'You want to know the input token count of a big prompt before you send it to Claude Fable 5.2, so you call `count_tokens` on `bedrock-runtime`. It fails. Why?', he: 'אתה רוצה לדעת את מספר טוקני הקלט של פרומפט גדול לפני שאתה שולח אותו ל-Claude Fable 5.2, אז אתה קורא ל-`count_tokens` ב-`bedrock-runtime`. זה נכשל. למה?' },
          options: { en: ['CountTokens costs money and your budget is empty', 'This model\'s card lists CountTokens as not supported on `bedrock-runtime`. The docs point to Anthropic\'s `count_tokens` on the mantle endpoint instead.', 'Token counting needs a Bedrock API key', 'CountTokens works only for output tokens'], he: ['CountTokens עולה כסף והתקציב שלך ריק', 'ב-card של המודל הזה CountTokens מסומן כלא נתמך ב-`bedrock-runtime`. התיעוד מפנה במקום זה ל-`count_tokens` של Anthropic ב-endpoint של mantle.', 'ספירת טוקנים צריכה Bedrock API key', 'CountTokens עובד רק לטוקני פלט'] },
          answer: 1, explain: { en: 'CountTokens itself is free and counts input tokens. But Claude models that exist only through cross-Region inference do not support it on `bedrock-runtime`. Once more: the model card decides, not the general docs page.', he: 'CountTokens עצמו חינמי וסופר טוקני קלט. אבל מודלי Claude שקיימים רק דרך cross-Region inference לא תומכים בו ב-`bedrock-runtime`. שוב: ה-model card מכריע, לא דף התיעוד הכללי.' } },
        { t: 'quiz', q: { en: 'Which statements about cross-Region inference are true? Pick all that apply.', he: 'אילו משפטים על cross-Region inference נכונים? בחר את כל הנכונים.' },
          options: { en: ['There is no extra charge for the routing; the price follows the Region you call from', 'CloudTrail logs the call in the source Region, and `inferenceRegion` shows where it ran', 'It works with Provisioned Throughput', 'It is available on `bedrock-mantle` too'], he: ['אין חיוב נוסף על הניתוב; המחיר הולך לפי ה-Region שקוראים ממנו', 'CloudTrail רושם את הקריאה ב-Region המקור, ו-`inferenceRegion` מראה איפה היא רצה', 'זה עובד עם Provisioned Throughput', 'זה זמין גם ב-`bedrock-mantle`'] },
          answer: [0, 1], explain: { en: 'Inference profiles do not support Provisioned Throughput, and cross-Region profiles exist only on `bedrock-runtime`. The first two are exactly the facts an auditor asks about: who pays what, and where the data was processed.', he: 'Inference profiles לא תומכים ב-Provisioned Throughput, ו-cross-Region profiles קיימים רק ב-`bedrock-runtime`. שני הראשונים הם בדיוק העובדות שמבקר שואל עליהן: מי משלם כמה, ואיפה המידע עובד.' } },
        { t: 'quiz', q: { en: 'Your security team turned on model invocation logging. They see Converse calls in the logs, but not the calls of a new service that uses the Responses API with `background=true`. Why?', he: 'צוות האבטחה שלך הדליק model invocation logging. הם רואים בלוגים קריאות Converse, אבל לא את הקריאות של שירות חדש שמשתמש ב-Responses API עם `background=true`. למה?' },
          options: { en: ['Responses API calls are never logged', 'Logging records only streaming calls', 'The new service has no IAM role', 'Background runs exist only on `bedrock-mantle`, and calls to `bedrock-mantle` are not captured by invocation logging'], he: ['קריאות Responses API אף פעם לא נרשמות', 'הלוגים רושמים רק קריאות streaming', 'לשירות החדש אין IAM role', 'הרצות ברקע קיימות רק ב-`bedrock-mantle`, וקריאות ל-`bedrock-mantle` לא נקלטות ב-invocation logging'] },
          answer: 3, explain: { en: 'On `bedrock-runtime` the Responses API is always synchronous (`background=true` gives a 400), so this service must be on mantle. Invocation logging covers runtime calls, including Responses and Chat Completions there, but not mantle. If full logging is a requirement, that is a reason to stay on `bedrock-runtime`.', he: 'ב-`bedrock-runtime` ה-Responses API תמיד סינכרוני (`background=true` נותן 400), ולכן השירות הזה חייב להיות ב-mantle. Invocation logging מכסה קריאות runtime, כולל Responses ו-Chat Completions שם, אבל לא את mantle. אם לוגים מלאים הם דרישה, זו סיבה להישאר ב-`bedrock-runtime`.' } },
        { t: 'quiz', q: { en: 'A teammate wants to buy Provisioned Throughput for Claude Sonnet 5.5 before a big launch, "to be safe". What do you tell them?', he: 'חבר צוות רוצה לקנות Provisioned Throughput ל-Claude Sonnet 5.5 לפני השקה גדולה, "ליתר ביטחון". מה תגיד לו?' },
          options: { en: ['Good idea, buy 1 model unit with no commitment', 'Current Claude models are not on the PT list. Look at a quota increase with real numbers, cross-Region profiles, and the Reserved tier through the AWS account team.', 'PT is free for the first month', 'Use PT through a `global.` inference profile'], he: ['רעיון טוב, קנה model unit אחד בלי התחייבות', 'מודלי Claude עדכניים לא ברשימת ה-PT. בדוק העלאת quota עם מספרים אמיתיים, cross-Region profiles, ואת ה-Reserved tier דרך צוות החשבון של AWS.', 'PT חינמי בחודש הראשון', 'להשתמש ב-PT דרך inference profile מסוג `global.`'] },
          answer: 1, explain: { en: 'The PT model list is short and old. For current models, guaranteed capacity comes from the Reserved tier (a fixed price for reserved tokens-per-minute, a 1 or 3 month term). And PT never works with inference profiles anyway.', he: 'רשימת המודלים של PT קצרה וישנה. למודלים עדכניים, קיבולת מובטחת מגיעה מה-Reserved tier (מחיר קבוע על טוקנים-לדקה שמורים, התחייבות של חודש או 3 חודשים). ו-PT ממילא אף פעם לא עובד עם inference profiles.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Chat / Text playground', 'Cross-Region inference', 'Batch inference', 'Provisioned Throughput', 'Custom models', 'API keys', 'Settings'], active: 'Batch inference', crumbs: ['Amazon Bedrock', 'Batch inference', 'Create job'],
          task: { en: 'Set up the nightly ticket summaries as a batch job. Name it `tickets-nightly`. Your input file uses the Converse request format. Input folder: `s3://acme-batch/in/`. Output folder: `s3://acme-batch/out/`. The team already has a batch service role, so use it.', he: 'הגדר את סיכומי הטיקטים הליליים כעבודת batch. תן לה את השם `tickets-nightly`. קובץ הקלט שלך משתמש בפורמט הבקשה של Converse. תיקיית קלט: `s3://acme-batch/in/`. תיקיית פלט: `s3://acme-batch/out/`. לצוות כבר יש service role ל-batch, אז השתמש בו.' },
          heading: 'Create batch inference job',
          panels: [
            { title: 'Job details', n: 1, fields: [
              { label: 'Job name', type: 'input', value: '', placeholder: 'my-batch-job', expect: 'tickets-nightly', hint: { en: 'The name from the task: tickets-nightly', he: 'השם מהמשימה: tickets-nightly' } },
              { label: 'Select model', type: 'text', value: 'Nova 2 Lite' } ] },
            { title: 'Model invocation type', n: 2, fields: [
              { label: 'Model invocation type', type: 'radio', options: ['InvokeModel', 'Converse'], value: 'InvokeModel', expect: 'Converse', hint: { en: 'The input lines are Converse request bodies, so the job type must match', he: 'שורות הקלט הן גופי בקשות Converse, ולכן סוג העבודה חייב להתאים' } } ] },
            { title: 'Input data', n: 3, fields: [
              { label: 'Browse S3', type: 'input', value: '', placeholder: 's3://bucket/prefix/', expect: '/^s3:\\/\\/acme-batch\\/in\\/?$/', hint: { en: 'The input folder from the task: s3://acme-batch/in/', he: 'תיקיית הקלט מהמשימה: s3://acme-batch/in/' } } ] },
            { title: 'Output data', fields: [
              { label: 'Browse S3', type: 'input', value: '', placeholder: 's3://bucket/prefix/', expect: '/^s3:\\/\\/acme-batch\\/out\\/?$/', hint: { en: 'The output folder from the task: s3://acme-batch/out/', he: 'תיקיית הפלט מהמשימה: s3://acme-batch/out/' } },
              { label: 'Customize encryption settings (advanced)', type: 'toggle', value: false } ] },
            { title: 'Service access', n: 4, fields: [
              { label: 'Service role', type: 'radio', options: ['Create and use a new service role', 'Use an existing service role'], value: 'Create and use a new service role', expect: 'Use an existing service role', hint: { en: 'The team already has a role that can read the input and write the output', he: 'לצוות כבר יש role שיכול לקרוא את הקלט ולכתוב את הפלט' } } ] }
          ],
          buttons: ['Cancel', 'Create batch inference job'],
          callouts: [
            { n: 1, en: 'Job details: a name and the model. The job runs on the `bedrock` control plane (`create_model_invocation_job`), not on `bedrock-runtime`.', he: 'Job details: שם והמודל. העבודה רצה על ה-control plane בשם `bedrock` ‏(`create_model_invocation_job`), לא על `bedrock-runtime`.' },
            { n: 2, en: 'InvokeModel (the default) expects native request bodies; Converse expects Converse bodies. Remember: Converse-type jobs do not support tool calling.', he: 'InvokeModel (ברירת המחדל) מצפה לגופי בקשה מקוריים; Converse מצפה לגופי Converse. זכור: עבודות מסוג Converse לא תומכות בקריאה לכלים.' },
            { n: 3, en: 'The input can be a folder or one `.jsonl` file. Media files referenced by S3 URI must be in the same bucket and folder tree.', he: 'הקלט יכול להיות תיקייה או קובץ `.jsonl` אחד. קבצי מדיה שמופנים ב-S3 URI חייבים להיות באותו bucket ובאותו עץ תיקיות.' },
            { n: 4, en: 'Bedrock reads and writes S3 with a service role, not with your own identity. For VPC settings or a bucket in another account you need the API, not the console.', he: 'Bedrock קורא וכותב ל-S3 עם service role, לא עם הזהות שלך. להגדרות VPC או ל-bucket בחשבון אחר צריך את ה-API, לא את הקונסול.' }
          ],
          success: { en: 'The job is submitted. Results will appear in s3://acme-batch/out/, in any order, so match them by recordId. Add an EventBridge rule on "Batch Inference Job State Change" instead of polling.', he: 'העבודה נשלחה. התוצאות יופיעו ב-s3://acme-batch/out/, בסדר כלשהו, אז מתאימים אותן לפי recordId. הוסף כלל EventBridge על "Batch Inference Job State Change" במקום לבדוק שוב ושוב.' },
          caption: { en: 'The create-job page for batch inference, simplified to the sections named in the docs. Which models support batch: check the docs.', he: 'דף יצירת עבודת batch inference, מפושט לחלקים שמופיעים בתיעוד. אילו מודלים תומכים ב-batch: בדוק בתיעוד.' } },
        { t: 'quiz', q: { en: 'Your batch job finished. The output lines are not in the same order as the input lines. What do you do?', he: 'עבודת ה-batch שלך הסתיימה. שורות הפלט לא באותו סדר כמו שורות הקלט. מה עושים?' },
          options: { en: ['Run the job again with one record per job', 'Match each output to its input by `recordId`', 'Report a bug to AWS', 'Sort the output alphabetically'], he: ['להריץ שוב את העבודה עם רשומה אחת לכל עבודה', 'להתאים כל פלט לקלט שלו לפי `recordId`', 'לדווח על באג ל-AWS', 'למיין את הפלט לפי האלפבית'] },
          answer: 1, explain: { en: 'The order is not guaranteed by design. That is what `recordId` is for. If you do not set it, Bedrock adds one, but your own IDs (for example a ticket number) make the matching trivial.', he: 'הסדר לא מובטח מלכתחילה. בשביל זה יש `recordId`. אם לא קובעים אותו, Bedrock מוסיף אחד, אבל מזהים משלך (למשל מספר טיקט) הופכים את ההתאמה לפשוטה.' } },
        { t: 'reveal', q: { en: 'Interview question: "What is the difference between a model ID and an inference profile, and why does it matter for IAM?"', he: 'שאלת ראיון: "מה ההבדל בין model ID ל-inference profile, ולמה זה חשוב ל-IAM?"' },
          a: { en: 'A model ID names a model and runs the request in the Region I call. An inference profile names a model plus a set of Regions, and Bedrock picks one with capacity. Geographic profiles stay inside one geography; global profiles can use any commercial Region and are cheaper. Many new models can only be called through a profile. For IAM, a call through a profile is checked twice: on the profile ARN and on the foundation-model ARN in the Region where the request finally runs. So the policy must allow both, and the good pattern is to allow the model ARNs only with the condition `bedrock:InferenceProfileArn`, so the model cannot be called around the profile. SCPs that deny Regions must allow the destination Regions, or `unspecified` for global profiles.', he: 'model ID מציין מודל ומריץ את הבקשה ב-Region שקראתי אליו. inference profile מציין מודל ועוד קבוצת Regions, ו-Bedrock בוחר אחד עם קיבולת. Geographic profiles נשארים בתוך גאוגרפיה אחת; global profiles יכולים להשתמש בכל Region מסחרי והם זולים יותר. להרבה מודלים חדשים אפשר לקרוא רק דרך profile. ב-IAM, קריאה דרך profile נבדקת פעמיים: על ה-ARN של ה-profile ועל ה-ARN של ה-foundation model ב-Region שבו הבקשה רצה בסוף. לכן ה-policy חייבת להרשות את שניהם, והדפוס הטוב הוא להרשות את ה-ARNs של המודל רק עם ה-condition בשם `bedrock:InferenceProfileArn`, כך שאי אפשר לקרוא למודל בעקיפת ה-profile. SCPs שאוסרים Regions חייבים להרשות את ה-Regions היעד, או `unspecified` ל-global profiles.' } },
        { t: 'reveal', q: { en: 'Interview question: "Design the model-calling layer for a new product. What goes into it?"', he: 'שאלת ראיון: "תכנן את שכבת הקריאה למודלים במוצר חדש. מה נכנס אליה?"' },
          a: { en: 'One small module that every feature uses. The model or profile ID comes from configuration, per feature. It uses Converse (or ConverseStream for chat), so models are swappable. It sets `maxTokens` per feature close to reality, checks `stopReason` on every call, and logs `usage`, latency and the served tier with a feature label. It sends `requestMetadata` (feature, tenant) so the invocation logs can be filtered and later used for distillation. It retries 429 and 5xx with exponential backoff and jitter, fails fast on 400 and 403, and limits parallel calls. Stable prompt parts go first with a cache checkpoint. Credentials come from the role, with short-term API keys only where an SDK needs a key. Around it: a cross-Region profile that fits our data rules, application inference profiles or IAM principal tags for cost per team, CloudWatch alarms on throttles and errors, and an evaluation set that runs whenever we change the model.', he: 'מודול קטן אחד שכל היכולות משתמשות בו. ה-model או profile ID מגיע מקונפיגורציה, לכל יכולת. הוא משתמש ב-Converse (או ConverseStream לצ׳אט), כך שאפשר להחליף מודלים. הוא קובע `maxTokens` לכל יכולת קרוב למציאות, בודק `stopReason` בכל קריאה, ורושם `usage`, latency וה-tier שהגיש, עם תווית יכולת. הוא שולח `requestMetadata` (יכולת, לקוח) כדי שאפשר יהיה לסנן את ה-invocation logs ולהשתמש בהם אחר כך ל-distillation. הוא מנסה שוב על 429 ו-5xx עם exponential backoff ו-jitter, נכשל מהר על 400 ו-403, ומגביל קריאות מקבילות. חלקי פרומפט יציבים באים ראשונים עם cache checkpoint. ה-credentials מגיעים מה-role, עם API keys קצרי-טווח רק איפה ש-SDK צריך מפתח. מסביב: cross-Region profile שמתאים לכללי המידע שלנו, application inference profiles או tags של IAM principal לעלות לפי צוות, alarms של CloudWatch על throttles ושגיאות, וסט evaluation שרץ בכל פעם שמחליפים מודל.' } },
        { t: 'reveal', q: { en: 'Interview question: "A customer asks: does AWS or the model provider see our prompts?"', he: 'שאלת ראיון: "לקוח שואל: האם AWS או ספק המודל רואים את הפרומפטים שלנו?"' },
          a: { en: 'The provider does not: Bedrock runs models in accounts owned by the Bedrock service team, the providers have no access to them, and the FAQ says content is not used to improve base models and is not shared with providers. But "nothing is kept" depends on the model. Some newer models have automated abuse detection: for OpenAI models (except gpt-oss) flagged traffic is kept up to 30 days, and for Claude Fable 5.x all traffic is kept up to 30 days and flagged traffic may get human review by AWS, which requires the account to opt in with the `aws_review` data retention mode. Retained data stays inside AWS, in the destination Region for cross-Region calls. So I answer per model, from the model card and the data retention docs, and I show how the customer can enforce their rule, for example with an SCP on the data retention mode.', he: 'הספק לא רואה: Bedrock מריץ מודלים בחשבונות שבבעלות צוות השירות של Bedrock, לספקים אין גישה אליהם, וה-FAQ אומר שהתוכן לא משמש לשיפור מודלי בסיס ולא משותף עם ספקים. אבל "שום דבר לא נשמר" תלוי במודל. בחלק מהמודלים החדשים יש זיהוי שימוש לרעה אוטומטי: במודלי OpenAI (חוץ מ-gpt-oss) תעבורה שסומנה נשמרת עד 30 יום, וב-Claude Fable 5.x כל התעבורה נשמרת עד 30 יום ותעבורה שסומנה עשויה לעבור סקירה אנושית של AWS, מה שדורש מהחשבון להסכים עם מצב ה-data retention בשם `aws_review`. מידע שנשמר נשאר בתוך AWS, ב-Region היעד בקריאות cross-Region. לכן אני עונה לכל מודל, מה-model card ומתיעוד ה-data retention, ומראה איך הלקוח יכול לאכוף את הכלל שלו, למשל עם SCP על מצב ה-data retention.' } },
        { t: 'task', title: { en: 'After landing: try it in a real account', he: 'אחרי הנחיתה: לנסות בחשבון אמיתי' }, steps: {
          en: ['In the Bedrock console, open the Model catalog. Pick Claude Sonnet 5.5 and one Nova model, and read their model cards: In-Region support, service tiers, prompt caching minimum.', 'Run `aws bedrock list-inference-profiles` and find the `us.` and `global.` profiles of one model.', 'Write a 20-line Python script with `converse`: a system prompt, two turns of history, `maxTokens`, and a print of `stopReason` and `usage`. Then switch the `modelId` to a Nova model and run it again unchanged.', 'Turn the script into `converse_stream` and print the `metadata` event at the end.', 'Add a 2,000-token system prompt with a `cachePoint`, call twice within 5 minutes, and compare `cacheWriteInputTokens` and `cacheReadInputTokens`.', 'Open Service Quotas for Amazon Bedrock and find the TPM quota of the model you used, and the "Cross-Model Max Tokens Per Day" quota.', 'Turn on model invocation logging to S3 in Settings, make one call with `requestMetadata`, and find it in the log.'],
          he: ['בקונסול של Bedrock, פתח את ה-Model catalog. בחר את Claude Sonnet 5.5 ומודל Nova אחד, וקרא את ה-model cards שלהם: תמיכה ב-In-Region, service tiers, המינימום ל-prompt caching.', 'הרץ `aws bedrock list-inference-profiles` ומצא את ה-profiles מסוג `us.` ו-`global.` של מודל אחד.', 'כתוב סקריפט Python של 20 שורות עם `converse`: system prompt, שני תורות של היסטוריה, `maxTokens`, והדפסה של `stopReason` ו-`usage`. אחר כך החלף את ה-`modelId` למודל Nova והרץ שוב בלי שינוי.', 'הפוך את הסקריפט ל-`converse_stream` והדפס את אירוע ה-`metadata` בסוף.', 'הוסף system prompt של 2,000 טוקנים עם `cachePoint`, קרא פעמיים בתוך 5 דקות, והשווה את `cacheWriteInputTokens` ו-`cacheReadInputTokens`.', 'פתח את Service Quotas עבור Amazon Bedrock ומצא את ה-quota של TPM למודל שהשתמשת בו, ואת ה-quota בשם "Cross-Model Max Tokens Per Day".', 'הדלק model invocation logging ל-S3 ב-Settings, בצע קריאה אחת עם `requestMetadata`, ומצא אותה בלוג.'] } }
      ]
    }
  ]
});
